  ["_CeladonMart2FMiddleAgedManText"] = "Le SUPEREPOUSSE\ntient les faibles\11POKEMON a\11l'ecart...\12C'est un REPOUSSE\nplus puissant!",
  ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER} recoit\n{RAM:wStringBuffer}!",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "CT18: RIPOSTE!\nBon allez...\11Bonne chance!",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "Ton sac est plein\na craquer!",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "J'ai fini!!!!\nJ'ai fini\11POKEMON!!!!\12Pas toi? Yahaha!\nPrends donc ceci,\11petit!",
  ["_CeladonMart3FCurrentFloorSignText"] = "2eme: JEUX VIDEO",
  ["_CeladonMart3FFightingGameText"] = "Kan contre Ryo!\nHadoh Ken!",
  ["_CeladonMart3FGameBoyKid1Text"] = "Tous les POKEMON\ncaptures ont un\11numero d'immatri-\11culation et un\11nom de DO\11(Dresseur\11d'Origine)!",
  ["_CeladonMart3FGameBoyKid2Text"] = "Ouaiiis!\12Mon chum va\nm'echanger son\11KANGOUREX contre\11mon GRAVALANCH!",
  ["_CeladonMart3FGameBoyKid3Text"] = "Cool! Un\nGRAVALANCH!\12J'adore les\nGRAVALANCH!\12Qu...Hein??\12GRAVALANCH se\ntransforme en un\11autre POKEMON!",
  ["_CeladonMart3FLittleBoyText"] = "Le numero d'imma-\ntriculation d'un\11POKEMON sert a\11l'identifier lors\11d'un echange!",
  ["_CeladonMart3FPokemonPosterText"] = "Rouge et Bleu!\nDeux POKEMON!",
  ["_CeladonMart3FPuzzleGameText"] = "Quatre lignes!\nEn un seul coup!",
  ["_CeladonMart3FRPGText"] = "Un RPG! Cool...\nMais trop dur!",
  ["_CeladonMart3FSNESText"] = "Une SUPER\nNINTENDO!",
  ["_CeladonMart3FSportsGameText"] = "Un jeu de sport!\nVive le foot!",
  ["_CeladonMart4FCurrentFloorSignText"] = "Un cadeau...\nL'amour...\11La vie!\123eme: CADEAUX\12Vive les\nevolutions!\11Les PIERRES sont\11en vente!",
  ["_CeladonMart4FSuperNerdText"] = "J'offre une belle\nPOKEpoupee a ma\11blonde!",
  ["_CeladonMart4FYoungsterText"] = "Ecoute donc...\12Tu peux fuir face\naux POKEMON\11sauvages en les\11occupant avec une\11POKEPOUPEE!",
  ["_CeladonMart5FCurrentFloorSignText"] = "4eme: MEDICAMENTS",
  ["_CeladonMart5FGentlemanText"] = "Les accelerateurs\nde POKEMON sont\11en vente icitte.\12Le CALCIUM\naugmente les\11capacites\11SPECIALES.\12Le CARBONE\naugmente la\11VITESSE.",
  ["_CeladonMart5FSailorText"] = "J'veux acheter un\naccelerateur de\11POKEMON!\12Une PROTEINE\naugmentera\11l'ATTAQUE.\12Le FER augmente\nla DEFENSE!",
  ["_CeladonMartRoofCurrentFloorSignText"] = "DERNIER ETAGE:\nDISTRIBUTEURS",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "Ai soif!\nVeux boire!",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Quelle boisson\nlui offrir?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "Heu...\nNon merci.\11A pu soif!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "Ai soif!\nVeux boire!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "Plus de place!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} recoit\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} recoit\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} recoit:\nCT49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "\12{RAM:wStringBuffer}:\nLASER GLACE!\12Cette attaque\npourra geler\11l'ennemi!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "\12{RAM:wStringBuffer}:\nEBOULEMENT!\12Cette attaque\npeut faire peur\11a l'ennemi!",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "\12TM49...\nTRIPLATTAQUE!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Ouais ouais!\12DE L'EAU!\12C'est cool!\12Tiens...c'est\npour toi!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Ouaiiis!\12D'la LIMONADE!\12Top top top!\12V'la pour toi!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Ouaiiis!\12Du SODA COOL!\12Merciiii!\12Tiens, prends ca!",
  ["_CeladonMartRoofSuperNerdText"] = "Ma soeur est\ndresseur. Tu le\11crois, ca?\12Mais c'est une\np'tite peste!\11Elle m'agace!",
  ["_CeladonPokecenterBeautyText"] = "J'ai pris la\nPISTE CYCLABLE\11depuis HEMMINGFORD!",
  ["_CeladonPokecenterGentlemanText"] = "La POKEFLUTE\nreveille les\11POKEMON grace aux\11ultrasons!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "L'ATTAQUE de tous\ntes POKEMON est\11augmentee.\12Il permet aussi\nd'utiliser la CS\11FLASH.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "Les POKEMON d'un\nniveau inferieur\11a 30 t'obeiront.\12S'ils sont d'un\nniveau superieur,\11ils seront\11incontrolables!\12Tu pourras aussi\nutiliser la CS\11COUPE en-dehors\11des combats.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "Tous les POKEMON\nobeiront a tes\11ordres!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "Les POKEMON de\nniveau 70 ou\11moins t'obeiront.\12S'ils sont d'un\nniveau superieur,\11ils seront\11incontrolables!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Les BADGES sont\nportes par des\11dresseurs de haut\11niveau.\12Mmm... Tu en as\nau moins un.\12Ces BADGES ont\nd'etranges\11pouvoirs!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Reviens me voir\nquand tu veux.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Dis-moi...\12Lequel des 8\nBADGES veux-tu\11que je decrive?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "Les POKEMON\njusqu'au niveau\1150 t'obeiront.\12Ceux d'un niveau\nsuperieur seront\11incontrolables!\12Tu pourras aussi\nutiliser la CS\11FORCE.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "La DEFENSE de\ntous tes POKEMON\11sera augmentee.\12Tu pourras aussi\nutiliser la CS\11SURF en-dehors\11des combats.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "La VITESSE de\ntous tes POKEMON\11sera un p'tit peu\11augmentee.\12Tu pourras aussi\nutiliser la CS\11VOL en-dehors des\11combats.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Le SPECIAL de tes\nPOKEMON sera un\11peu augmente.",
  ["_CeruleanCityBikeShopSign"] = "Plus vite que le\nvent, plus vite\11dans les villes!\11...CYCLES A GOGO",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "FLAGADOSS, cogne!\nMais non! Tu fais\11n'importe quoi!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "Allez! FLAGADOSS!\nAttaque! Attaque!\11Mais non!!! Tu\11m'ecoutes, oui?",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "FLAGADOSS, REPLI!\nNon! Pas ca!\12Pfff... C'est dur\nde controler un\11POKEMON!\12Seuls les bons\ndresseurs se font\11obeir par leurs\11POKEMON!",
  ["_CeruleanCityCooltrainerF2Text"] = "Ze veux une zolie\nBICYCLETTE!\12Ze la veux toute\nrouze!",
  ["_CeruleanCityCooltrainerMText"] = "T'es un dresseur?\nCapturer...\11Collectionner...\11Se friter...\11Dur, hein?",
  ["_CeruleanCityGuardText"] = "Ces pauvres gens\nont ete voles.\12L'odieuse TEAM\nROCKET est\11derriere tout ca.\11C'est sur!\12Meme les forces\nde police ont du\11mal a lutter!",
  ["_CeruleanCityGymSign"] = "BAIE-COMEAU\nARENE POKEMON\11CHAMPION: MANON\12La petite pest...\nHeu...sirene!",
  ["_CeruleanCityRivalDefeatedText"] = "Houla!\nCalmos minable!\11T'as gagne, OK!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: He!\nTu sais quoi?\12Chuis alle chez\nTI-GUY et y m'a tout\11montre ses\11POKEMON rares!\12Ca m'a rajoute\nplein d'pages sur\11mon bo POKEDEX!\12Tout l'monde sait\nque TI-GUY est un\11POKEMANIAC!\12Il a meme invente\nle stockage des\11POKEMON par PC!\12T'as qu'a aller\nl'voir!\12Bon, je trace.\nTchao minab'!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: Yo!\n{PLAYER}!\12Faque tu t'en\nsors?\12Moi c'est l'pied!\nJ'ai chope un tas\11de POKEMON mega\11puissants et\11tetra balezes!\12Fais-moi voir\nc'que t'as, p'tit\11minable!",
  ["_CeruleanCityRivalVictoryText"] = "Heh!\nT'es pas de taille\11pour mon genie,\11tabarnak!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "\12J'decampe...\nBye bye!",
  ["_CeruleanCityRocketIGiveUpText"] = "Stop!\nJ'me rends!\11T'es trop fort!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "OK! Voila la CT\nqu'j'ai volee!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} recupere\nCT28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "Tu portes trop\nd'trucs!\12Je dois te donner\nca avant d'fuir.\11C'est ecrit dans\11l'histoire!",
  ["_CeruleanCityRocketText"] = "He le lutin!\nC'est pas chez\11toi, icitte...\11Quoi? Moi?\12J'suis innocent!\nHein? Quoi dit?\11Tu m'crois pas?\11Tu m'cherches?",
  ["_CeruleanCitySignText"] = "BAIE-COMEAU\nBaignee par une\11aura d'un bleu\11mysterieux",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "FLAGADOSS ignore\nles ordres...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "FLAGADOSS\nflane...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "FLAGADOSS pionce\ncomme une masse.",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "FLAGADOSS se\nbalade...",
  ["_CeruleanCitySuperNerd1Text"] = "Ce buisson devant\nla boutique blo-\11que le passage.\12Il doit y avoir\nun moyen de\11passer.",
  ["_CeruleanCitySuperNerd2Text"] = "Tu fais une\nencyclopedie sur\11les POKEMON?\11Pas mal...",
  ["_CeruleanCitySuperNerd3Text"] = "Des POKEMON trop\npuissants vivent\11dans la CAVE\11AZUREE!\12Seul le CHAMPION\nde la LIGUE\11POKEMON a le\11droit d'y entrer!",
  ["_CeruleanCityTrainerTipsText"] = "ASTUCE\12Appuyer sur B\npendant une evo-\11lution l'annule.",
  ["_CeruleanGymAfterBattleText1"] = "Tu dois te battre\ncontre d'autres\11dresseurs pour\11connaitre ton\11niveau.",
  ["_CeruleanGymAfterBattleText2"] = "MANON est super\nforte!\12Elle va pas\nse faire avoir\11par un rigolo\11comme toi!",
  ["_CeruleanGymBattleText1"] = "Je suis ben\nbaleze!\12MANON attendra!",
  ["_CeruleanGymBattleText2"] = "Plaouff!\12J'suis preums!\nBaston!",
  ["_CeruleanGymEndBattleText1"] = "Oh!\nJ'me suis fait\11ecraser!",
  ["_CeruleanGymEndBattleText2"] = "Glargh!\nC'est dingue!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "Tu as battu\nMANON! Capotant!\12Toi et moi, on\nforme une super\11equipe!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "Salut a toi!\nFutur champion!\12Un conseil?\12La CHAMPIONNE,\nMANON, est une\11specialiste des\11POKEMON de l'eau!\12Absorbe l'eau\navec des POKEMON\11des plantes!\12Ou grille-les\navec de\11l'electricite!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "Le BADGECASCADE\noblige tous les\11POKEMON d'un\11niveau inferieur\11a 30 a t'obeir!\12Les echanges\naussi!\12En plus, tu peux\nasteur\11utiliser la CS\11COUPE!\12Tu peux COUPER\nles arbustes\11et ouvrir de\11nouveaux chemins!\12Tu gagnes aussi ma\nCT favorite!",
  ["_CeruleanGymMistyPreBattleText"] = "Salut! T'es un\nnouveau!\12Si tu veux etre\nun vrai dresseur,\11il te faut une\11strategie pour\11tes POKEMON!\12C'est quoi ta\ntactique pour\11capturer les\11POKEMON sauvages?\12Moi je leur fonce\ndans le tas avec\11mes POKEMON\11aquatiques!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "Whouha!\nT'es super fort!\12Ben correct!\12Je te donne le\nBADGECASCADE pour\11m'avoir battue!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER} recoit\nla CT11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "La CT11 contient\nBULLES D'O!\12Apprends-la a un\nPOKEMON de l'eau!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "Ton inventaire\nest plein!",
  ["_CeruleanMartCooltrainerFText"] = "As-tu deja vu des\nSUPER BONBONS??\12Quand un POKEMON\nen mange un, il\11gagne un niveau!",
  ["_CeruleanMartCooltrainerMText"] = "Le REPOUSSE tient\nles POKEMON\11sauvages a\11l'ecart.\12Mets tes POKEMON\nles plus costauds\11en premier pour\11une plus grande\11efficacite!",
  ["_CeruleanPokecenterGentlemanText"] = "Tu connais TI-GUY?\12On raconte que\nc'est un vrai\11POKEMANIAC!\12Les gens sont\njaloux de TI-GUY.\12Nous sommes tous\ndes POKEMANIACs,\11non?",
  ["_CeruleanPokecenterGuyText"] = "TI-GUY a une sacree\ncollection de\11POKEMON!\12Et des rares, en\nplus...",
  ["_CeruleanPokecenterSuperNerdText"] = "Sacre TI-GUY!\12Il donnerait\nn'importe quoi\11pour mettre la\11main sur un\11POKEMON rare!",
  ["_CeruleanTradeHouseGrannyText"] = "Mon mari aime\nles echanges de\11POKEMON.\12Si t'aimes\ncollectionner,\11fais des echanges\11avec lui, OK?",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Ces ROCKET, ils\nsont si mechants!\12Regarde ce qu'ils\nont fait icitte!\12Ils m'ont vole\nune CT pour\11apprendre a leurs\11POKEMON a\11creuser des\11TUNNELS!\12Ca m'a coute les\nyeux de la tete!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "Contre mauvaise\nfortune bon\11coeur!\12Je vas apprendre\na mon TAUPIQUEUR\11a creuser des\11TUNNELS sans CT!",
  ["_CeruleanTrashedHouseGirlText"] = "La TEAM ROCKET\ndoit asteur\11creuser des\11TUNNELS dans tout\11ce qui bouge!",
  ["_CeruleanTrashedHouseWallHoleText"] = "La TEAM ROCKET a\ncreuse une\11nouvelle sortie!",
  ["_ChampionsRoomOakComeWithMeText"] = "TREMBLAY: {PLAYER}!\12Cette victoire...\nTu la dois pas\11entierement a tes\11qualites!\12Tu as tant baigne\nd'amour tes chers\11petits POKEMON!\12Et ca... \nC'est bien. \11{PLAYER}!\11Suis-moi!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "TREMBLAY: Tu as gagne!\nFelicitations!\11Tu es le nouveau\11champion de la\11LIGUE POKEMON!\12Tu as tant change\ndepuis ton depart\11avec {RAM:wNameBuffer}!\12{PLAYER}, t'es\ngrand asteur!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "TREMBLAY: {RIVAL}!\nJe suis... decu!\12Apprenant que tu\navais vaincu le\11CONSEIL des 4, je\11suis venu en\11vitesse!\12Mais le temps\nd'arriver jusqu'\11icitte, t'avais\11deja perdu...\11C'est dingue!\12{RIVAL}! As-tu\ncompris pourquoi\11ton equipe s'est\11fait moucher?\12Tu as oublie de\ntraiter tes\11POKEMON avec\11amour!\12Et oui mon p'tit\nbonhomme.\11C'est de meme et\11pis c'est tout!",
  ["_ChampionsRoomOakText"] = "TREMBLAY: {PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "Pourquoi?\nPourquoi j'ai\11perdu, tabarnak?\12J'ai jamais fait\nd'erreur en\11elevant mes\11POKEMON...\12Maudit! T'es le\nnouveau champion\11de la POKEMON\11LEAGUE!\12Ben que\nj'haisse ca,\11l'admettre.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}:\nBonjour minable.\12Je t'attends\ndepuis une bonne\11plombe, {PLAYER}!\12Ton devoir en\ntant que rival\11est d'entrainer\11mes POKEMON.\12En ameliorant mon\nPOKEDEX, j'ai\11recherche les\11POKEMON sur-\11puissants!\12J'ai ainsi cree\nl'equipe ultime,\11efficace contre\11tous les types de\11POKEMON!\12Ca t'epate, hein?\12Je suis le\nchampion POKEMON!\12Tu sais c'que ca\nveut dire?\12Ecoute ca,\nminable!\12Je suis le\ndresseur le plus\11puissant du\11monde! Yaaa!",
  ["_ChanseyDexEntry"] = "Un POKEMON rare\net difficile a\ncapturer qui\12porte chance et\nbien-etre a son\npossesseur.<DEXEND>",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_CharizardDexEntry"] = "Il peut fondre\nla roche de son\nsouffle brulant.\12Il est souvent la\ncause de nombreux\nincendies.<DEXEND>",
  ["_CharmanderDexEntry"] = "Il prefere les\nendroits chauds.\nEn cas de pluie,\12de la vapeur\nse forme autour\nde sa queue.<DEXEND>",
  ["_CharmeleonDexEntry"] = "En agitant sa\nqueue, il peut\nelever le niveau\12de la temperature\na un degre\nincroyable.<DEXEND>",
  ["_ChooseABoxText"] = "Choisissez une\nBOITE POKE.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "DEFLAGRATION est\nla technique de\11feu ultime!\12La donne pas\na un POKEMON de\11l'eau, ca ferait\11pas bon menage!",
  ["_CinnabarGymBlainePreBattleText"] = "Salutations.\12Mon nom est...\nARMAND! Je suis\11le CHAMPION de\11l'ARENE de\11PERCE!\12Mes POKEMON\nflamboyants vont\11te reduire en\11cendres!\12Haha! J'espere\nque t'as de\11l'ANTI-BRULE!\11Y va bientot\11faire ben chaud!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} obtient:\n{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Vlouff!\nJe me suis fait\11vaporiser!\12Tu as gagne le\nBADGE VOLCAN!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "\12CT38 :\nDEFLAGRATION!\12Elle convient a\nun POKEMON du\11feu!\12REPTINCEL ou\nPONYTA feront\11l'affaire!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "Ton inventaire\nest plein!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Haha!\12Le BADGE VOLCAN\naugmente le\11SPECIAL de tes\11POKEMON!\12Prends ca aussi!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}! Tu as\nbattu ARMAND!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "Salut! Graine de\nchampion!\12ARMAND, le\nflamboyant, est\11un pro des\11POKEMON de feu!\12C'est le moment\nde jeter de\11l'eau sur le feu!\12Prends donc des\nANTI-BRULE avec\11toi! Ca peut\11toujours servir!",
  ["_CinnabarGymQuizCorrectText"] = "Bonne reponse!\12En avant!",
  ["_CinnabarGymQuizIncorrectText"] = "N'importe quoi!",
  ["_CinnabarGymQuizIntroText"] = "Quiz POKEMON!\12Une bonne reponse\nouvrira la porte!\12Une erreur et\nc'est la guerre!\12Pour preserver\nune equipe avant\11d'affronter le\11CHAMPION...\12Mieux vaut eviter\nles erreurs!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Le feu, ca brule,\nles flammes, faut\11pas mettre la\11main d'dans...\12Brule, brule...\nJ'aime le feu...",
  ["_CinnabarGymSuperNerd1BattleText"] = "Un POKEMON du\nfeu, c'est chaud!",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "Yaha!\nFait chaud, non?",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "Je vole, j'y peux\nrien. Je vole des\11POKEMON, et\11j'me marre bien!",
  ["_CinnabarGymSuperNerd2BattleText"] = "Avant, j'etais un\nvoleur, j'avais\11honte...\11Aujourd'hui je\11suis un dresseur\11et je suis fier!",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "Ah!\nJ'ai honte, je me\11rends!",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "J'suis un\ncerebral, tu peux\11pas comprendre!",
  ["_CinnabarGymSuperNerd3BattleText"] = "Les POKEMON, je\nmaitrise, faque\11toi, tu peux pas\11gagner!",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "Ben...\nMais...ben...!",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "Si y'avait des\nPOKEMON voleurs,\11j'en aurais des\11tas! Moi, c'que\11j'aime, c'est les\11cambriolages!",
  ["_CinnabarGymSuperNerd4BattleText"] = "Les POKEMON du\nfeu, j'adore!",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "Flouf!\nC'est l'feu!",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "Tout petit,\nARMAND aimait se\11promener dans les\11montagnes.\11Un jour, il s'est\11perdu et il eut\11ben froid! Mais\11un POKEMON de feu\11apparut...\12La lumiere de ses\nailes enflammees\11permit a ARMAND\11de retrouver son\11chemin! Depuis\11il adore les\11POKEMON de feu!",
  ["_CinnabarGymSuperNerd5BattleText"] = "Hehe! Je sais\npourquoi ARMAND\11est devenu un\11dresseur!",
  ["_CinnabarGymSuperNerd5EndBattleText"] = "Ouch!",
  ["_CinnabarGymSuperNerd6AfterBattleText"] = "PONYTA...\nFEUNARD...\11C'est chaud!",
  ["_CinnabarGymSuperNerd6BattleText"] = "J'ai bourlingue\ndans pas mal\11d'ARENES, p'tit\11gars! Mais ma\11preferee c'est\11celle-ci!",
  ["_CinnabarGymSuperNerd6EndBattleText"] = "Yacha!\nFait ben chaud!",
