  ["_FuchsiaCityLaprasSignText"] = "Nom: LOKHLASS\12Le roi des mers.",
  ["_FuchsiaCityPokecenterGuyText"] = "LE PARC SAFARI\nregorge de\11POKEMON.\12On y trouve aussi\nde ben rares!",
  ["_FuchsiaCityPokemonText"] = "!",
  ["_FuchsiaCitySafariGameSignText"] = "JEU DU SAFARI\nChope-les tous!",
  ["_FuchsiaCitySafariZoneSignText"] = "LE PARADIS DES\nPOKEMON\11PARC SAFARI",
  ["_FuchsiaCitySignText"] = "HEMMINGFORD\nRose comme la\11passion",
  ["_FuchsiaCitySlowpokeSignText"] = "Nom: RAMOLOSS\12Sympa mais...\nMega-lent!",
  ["_FuchsiaCityVoltorbSignText"] = "Nom: VOLTORBE\12Portrait crache\nd'une POKE BALL.",
  ["_FuchsiaCityWardensHomeSignText"] = "PARC SAFARI\nMAISON DU GARDIEN",
  ["_FuchsiaCityYoungster1Text"] = "Connais-tu le jeu\ndu SAFARI?\11Certains POKEMON\11apparaissent\11qu'a cet endroit.",
  ["_FuchsiaCityYoungster2Text"] = "Cette BALL est\npour vrai un\11POKEMON.",
  ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "Salut,\n{PLAYER}!\12Ca mord?",
  ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "Oh non!\12Ton inventaire\nest plein!",
  ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "Cool! T'as l'air\nd'un bon gars!\12Prends ca!\nQue la Grand'\11Peche soit avec\11toi, p'tit!\12{PLAYER} recoit\nune {RAM:wStringBuffer}!",
  ["_FuchsiaGoodRodHouseFishingGuruText"] = "Je suis le grand\nfrere du MAITRE\11PECHEUR!\12Moi, mon truc,\nc'est la peche!\12T'aimes la\npeche, petit?",
  ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "Oh...Pas cool!\nPas cool du tout!",
  ["_FuchsiaGymGymGuideBeatKogaText"] = "Un ninja? Bah...\nC'est gros, roux\11et ca fait\11coin-coin! Non?",
  ["_FuchsiaGymGymGuideChampInMakingText"] = "Hop la! Graine\nde champion!\12L'ARENE de\nHEMMINGFORD est un\11vrai casse-tete!\12KOGA te semblera\nproche, mais de\11nombreux murs le\11protegeront!\12Trouve les trous\nentre les murs\11pour l'atteindre!",
  ["_FuchsiaGymKogaBeforeBattleText"] = "KOGA: Gwahahaha!\12Un nain ose me\ndefier? Moi, le\11grand le beau le\11terrible KOGA?\12Par l'enfer,\npar le sang,\11par l'acier,\11j'vais gagner!\12Puisse la poigne\nde mes poisons\11petrifier de peur\11la paix et tes\11petits POKEMON!",
  ["_FuchsiaGymKogaPostBattleAdviceText"] = "TOXIK fera\nsouffrir de plus\11en plus un\11POKEMON pendant\11un combat!\12De quoi filer la\npetoche!",
  ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "Gwaha...heu?\nTu as prouve ta\11valeur!\12Ouvre ta mimine\ncar voici...\11le BADGE AME!",
  ["_FuchsiaGymKogaReceivedTM06Text"] = "{PLAYER} recoit:\n{RAM:wStringBuffer}!",
  ["_FuchsiaGymKogaSoulBadgeInfoText"] = "Le BADGE AME fera\nmonter la DEFENSE\11de tes POKEMON!\12Il te permettra\naussi d'utiliser\11SURF!\12Attends! Prends\naussi ceci!",
  ["_FuchsiaGymKogaTM06ExplanationText"] = "\12CT06: TOXIK!\12Cette technique\nsecrete et sacree\11est vieille d'au\11moins 400 ans!\11...j'te jure!",
  ["_FuchsiaGymKogaTM06NoRoomText"] = "Gnaaaa!!!\nTon inventaire\11est plein!",
  ["_FuchsiaGymRocker1AfterBattleText"] = "Tu penses-tu avec\nta tete? Heu?\11Syntax Error!",
  ["_FuchsiaGymRocker1BattleText"] = "La force...\nPas glop.\12La strategie... \nGlop glop!\12Viens la...\nPas bouger...\11Et...\11Mange ta mandale!",
  ["_FuchsiaGymRocker1EndBattleText"] = "Que?\nQue quoi?",
  ["_FuchsiaGymRocker2AfterBattleText"] = "L'entrainement...\nC'est le pied!",
  ["_FuchsiaGymRocker2BattleText"] = "J'veux etre un\nninja, pour faire\11yaaaaa!",
  ["_FuchsiaGymRocker2EndBattleText"] = "Geuh...\nA perdu!",
  ["_FuchsiaGymRocker3AfterBattleText"] = "Les attaques de\npoison et de\11sommeil sont ben\11puissantes! Oui!",
  ["_FuchsiaGymRocker3BattleText"] = "Crois-tu pouvoir\nme battre? Haha.\11Nabot!",
  ["_FuchsiaGymRocker3EndBattleText"] = "Quoi?\nEul'nabot m'a\11battu?",
  ["_FuchsiaGymRocker4AfterBattleText"] = "Chuis cuit!\nVoila un conseil!\12Fais attention\naux trous entre\11les murs...",
  ["_FuchsiaGymRocker4BattleText"] = "Pas bouger!\12Nos jolis murs\ninvisibles sont\11sympas, non?",
  ["_FuchsiaGymRocker4EndBattleText"] = "Whoa!\nTout mort!",
  ["_FuchsiaGymRocker5AfterBattleText"] = "J'suis nul!",
  ["_FuchsiaGymRocker5BattleText"] = "J'veux etre un\nninja et sauter\11d'arbre en arbre!\12Comme a la tivi.\nComme X-PORC, le\11goret d'l'espace!",
  ["_FuchsiaGymRocker5EndBattleText"] = "Gruik!",
  ["_FuchsiaGymRocker6AfterBattleText"] = "La lumiere\nengendre l'ombre. \12Quel cote de la\nForce choisis-tu?",
  ["_FuchsiaGymRocker6BattleText"] = "KOGA fait partie\nd'une grande\11famille de\11terribles ninjas!\12Et toi? D'ou\nviens-tu? Qui\11es-tu? Pourquoi?",
  ["_FuchsiaGymRocker6EndBattleText"] = "...\nDefaite.",
  ["_FuchsiaMartCooltrainerFText"] = "Tu connais la\nVITESSE +? Elle\11augmente la\11vitesse de ton\11POKEMON pendant\11un combat!",
  ["_FuchsiaMartMiddleAgedManText"] = "As-t'une affiche\ndu PARC SAFARI?\12Et des cartes?\nEt des almanachs?",
  ["_FuchsiaMeetingRoomSafariZoneWorker1"] = "Nous avons\nsurnomme le\11GARDIEN, RAMOLOSS.\12Ben, oui! Il\nressemble a un\11RAMOLOSS!",
  ["_FuchsiaMeetingRoomSafariZoneWorker2"] = "RAMOLOSS s'y\nconnait ben gros\11en POKEMON!\12Il a meme des\nfossiles de\11POKEMON rares et\11anciens!",
  ["_FuchsiaMeetingRoomSafariZoneWorker3"] = "RAMOLOSS m'a\nparle, mais je ne\11comprends rien a\11c'qu'il m'dit.\12Je crois qu'il a\nun probleme pour\11parler!",
  ["_FuchsiaPokecenterCooltrainerFText"] = "Y'a un petit\npassage a l'ouest\11de MONT-TREMBLANT.\12Il mene au\nquartier general\11de la LIGUE\11POKEMON.\11Ce QG est la plus\11haute autorite\11des dresseurs.",
  ["_FuchsiaPokecenterRockerText"] = "Un seul POKEMON\npuissant est\11pas suffisant.\12Il faut tous les\nfaire evoluer de\11facon egale.",
  ["_FullHealText"] = "{RAM:wNameBuffer}\nest soigne!",
  ["_FullyParalyzedText"] = "{USER}\nest paralyse!",
  ["_GainedText"] = "{RAM:wNameBuffer} gagne\n",
