  ["_GameCornerClerk2WantSomeCoinsText"] = "Quoi ca? Tu veux-tu\ndes jetons?",
  ["_GameCornerClerk2YouHaveLotsOfCoinsText"] = "T'en as des\njetons, toi!",
  ["_GameCornerCoinCaseText"] = "T'as pas\nde BOITE JETON!",
