  ["_GameCornerMiddleAgedMan1Text"] = "Ecoute donc ca...\12On raconte que\nce tripot est\11tenu par la TEAM\11ROCKET.",
  ["_GameCornerMiddleAgedWomanText"] = "Ce que j'peux\nm'eclater! Yaaa!",
  ["_GameCornerNoCoinsText"] = "T'as pas\nde jetons!",
  ["_GameCornerOopsForgotCoinCaseText"] = "Oups! Pas de\nBOITE JETON!",
