  ["_GroundRoseText"] = "Le sol s'est leve\ndans le coin!",
  ["_GrowlitheDexEntry"] = "Pour proteger\nson territoire il\naboie et mord\12jusqu'a ce que\nles intrus\ns'enfuient.<DEXEND>",
  ["_GyaradosDexEntry"] = "Gigantesque et\nmalefique, il est\ncapable de raser\12une ville dans un\nacces de rage\nterrifiante.<DEXEND>",
  ["_GymStatueText1"] = "ARENE POKEMON\nde {RAM:wGymCityName}\11CHAMPION:\11{RAM:wGymLeaderName}\12VAINQUEURS:\n{RIVAL}",
  ["_GymStatueText2"] = "ARENE POKEMON\nde {RAM:wGymCityName}\11CHAMPION:\11{RAM:wGymLeaderName}\12VAINQUEURS:\n{RIVAL}\11{PLAYER}",
  ["_HMCantDeleteText"] = "Les CS peuvent\netre oubliees!",
  ["_HallOfFameOakText"] = "TREMBLAY: Hum-hum!\nFelicitations\11{PLAYER}!\12Cet etage est\nreserve aux\11celebrites\11POKEMON!\12Les champions de\nla LIGUE sont\11consacres icitte!\12Leurs POKEMON\nsont enregistres\11en tant que\11CELEBRITES!\12{PLAYER}! Long\nfut ton periple\11jusqu'a la\11victoire!\12Encore bravo.\nToi et tes chers\11POKEMON etes\11tous celebres!",
  ["_HasSubstituteText"] = "{USER}\na un CLONE!",
  ["_HaunterDexEntry"] = "Il peut se\nglisser a travers\nles murs comme\12une creature\nd'une autre\ndimension.<DEXEND>",
