  ["_HorseaDexEntry"] = "Repute pour tirer\navec precision\nun jet d'encre\12sur des insectes\nvolants depuis la\nsurface de l'eau.<DEXEND>",
  ["_HurtByBurnText"] = "{USER}\nbrule!",
  ["_HurtByLeechSeedText"] = "{USER}\nperd son energie!",
