  ["_HurtItselfText"] = "Sa folie lui in-\nflige des degats!",
  ["_HypnoDexEntry"] = "En fixant son\nadversaire, il\nl'assaille avec\12les attaques PSY\nd'HYPNOSE et de\nCHOC MENTAL.<DEXEND>",
  ["_IceHealText"] = "{RAM:wNameBuffer}\nest degele!",
  ["_IgnoredOrdersText"] = "{RAM:wBattleMonNick}\nignore les ordres!",
  ["_IndigoPlateauHQText"] = "QUEBEC\nQuartier general\11de la LIGUE\11POKEMON",
  ["_IndigoPlateauLobbyCooltrainerFText"] = "A partir d'icitte,\nt'affronteras\11les quatre\11membres du....\11CONSEIL des 4!\12Remporte la\nvictoire et une\11porte s'ouvrira\11vers le prochain\11dresseur. Bonne\11chance, petit!",
  ["_IndigoPlateauLobbyGymGuideText"] = "Salut! Champion\nen herbe!\12Tu vas devoir\naffronter le\11CONSEIL des 4\11dans l'ordre pour\11triompher de la\11LIGUE POKEMON.\12Si tu perds,\nd'abord t'auras\11honte, et ensuite\11tu devras tout\11recommencer!\11Faque fais bien\11attention et...\11Ecrase-les!",
  ["_IndigoPlateauStatuesText1"] = "QUEBEC",
  ["_IndigoPlateauStatuesText2"] = "Le reve de tout\ndresseur!\11Quartier general\11de la LIGUE\11POKEMON.",
  ["_IndigoPlateauStatuesText3"] = "La plus haute\ninstance POKEMON.\11Quartier general\11de la LIGUE\11POKEMON.",
  ["_IntoText"] = "\nen {RAM:wNameBuffer}!",
