  ["_KoffingDexEntry"] = "Son corps,\nconstitue de gaz\ntoxiques et\12instables, peut\nexploser\nsoudainement.<DEXEND>",
  ["_KrabbyDexEntry"] = "Ses pinces sont\ndes armes ben\npuissantes. Elles\12lui servent aussi\na garder son\nequilibre.<DEXEND>",
  ["_LancesRoomLanceAfterBattleText"] = "Comment mes\ndragons ont-ils\11pu succomber a\11tes attaques,\11{PLAYER}?\12Tu es desormais\nchampion de la\11LIGUE POKEMON!\12Enfin...\nPas tout a fait.\11Une epreuve doit\11encore t'etre\11imposee...\12Un grand dresseur\nt'attend. Son nom\11est...\12{RIVAL}!\nIl a vaincu le\11CONSEIL des 4\11avant toi!\12Il est le vrai\nchampion POKEMON!",
  ["_LancesRoomLanceBeforeBattleText"] = "Ah! Enfin...\nJ'ai entendu\11parler de toi, \11{PLAYER}!\12Je regne sur le\nCONSEIL des 4!\11Mon nom est PETER\11le dresseur de\11dragons!\12Les dragons sont\ndes POKEMON\11mystiques!\12Les capturer et\nles entrainer est\11difficile mais\11leurs pouvoirs\11sont superieurs!\12Ils sont presque\ninvincibles!\12Le glas de la\ndefaite et de la\11honte sonne pour\11toi...\12L'entends-tu?",
  ["_LancesRoomLanceEndBattleText"] = "Incroyable!\12Tu as bien merite\nle titre de...\11Maitre POKEMON!",
  ["_LaprasDexEntry"] = "Ce POKEMON en\nvoie d'extinction\npeut transporter\12des passagers sur\nson dos par-dela\nles oceans.<DEXEND>",
  ["_LavenderCuboneHouseBrunetteGirlGhostIsGoneText"] = "Le SPECTRE de\nla TOUR DE VAL-JALBERT\11est parti!\12Quelqu'un a du\napaiser son ame\11tourmentee!",
  ["_LavenderCuboneHouseBrunetteGirlPoorCubonesMotherText"] = "Je deteste ces\nmechants ROCKET!\12La pauvre mere de\nOSSELAIT...\12Elle est morte en\nessayant\11d'echapper a la\11TEAM ROCKET!",
  ["_LavenderCuboneHouseCuboneText"] = "OSSELAIT: Lailaii!",
  ["_LavenderMartBaldingGuyText"] = "Je cherche des\nobjets permettant\11d'augmenter la\11puissance d'un\11POKEMON en\11combat.\12ATTAQUE +,\nDEFENSE +,\11SPECIAL + et\11VITESSE +, c'est\11ca qu'je cherche.\12Sais-t'ou je\npeux en trouver?",
  ["_LavenderMartCooltrainerMNuggetText"] = "J'ai trouve une\nPEPITE dans les\11montagnes.\12Je l'ai vendue...\n...5000¥!",
  ["_LavenderMartCooltrainerMReviveText"] = "Connais-tu\nle RAPPEL? Il\11permet de\11reanimer un\11POKEMON K.O.!",
  ["_LavenderPokecenterGentlemanText"] = "La TEAM ROCKET\nferait n'importe\11quoi pour de\11l'cash!",
  ["_LavenderPokecenterGuyText"] = "Les OSSELAIT\nportent un crane,\11non?\12Certains seraient\nprets a en payer\11le prix fort!",
  ["_LavenderPokecenterLittleGirlText"] = "J'ai vu la mere\nde OSSELAIT se\11faire tuer par la\11TEAM ROCKET!",
  ["_LavenderTownCooltrainerMText"] = "Cette ville est\nle cimetiere des\11POKEMON.\12La TOUR DE VAL-JALBERT\nest le lieu de\11recueillement.",
  ["_LavenderTownLittleGirlDoYouBelieveInGhostsText"] = "Crois-t'aux\nSPECTRES?",
  ["_LavenderTownLittleGirlHaHaGuessNotText"] = "T'as raison.\12La main toute\nblanche sur ton\11epaule est fausse\11faque...",
  ["_LavenderTownLittleGirlSoThereAreBelieversText"] = "Pour vrai? Il en\nfaut...",
  ["_LavenderTownPokemonHouseSignText"] = "BENEVOLAT DE\nVAL-JALBERT\11MAISON POKEMON",
  ["_LavenderTownPokemonTowerSignText"] = "Paix a l'ame des\nPOKEMON\11TOUR DE VAL-JALBERT",
  ["_LavenderTownSignText"] = "VAL-JALBERT\nLe pourpre de\11la noblesse",
  ["_LavenderTownSilphScopeSignText"] = "Tout nouveau\nSCOPE SYLPHE!\12Voir l'invisible!\12SYLPHE INC.",
  ["_LavenderTownSuperNerdText"] = "Des SPECTRES sont\napparus dans la\11TOUR DE VAL-JALBERT.\12Ils doivent etre\nles esprits des\11POKEMON tues par\11la ROCKET.",
  ["_LearnedMove1Text"] = "{RAM:wLearnMoveMonName}\napprend...\11{RAM:wStringBuffer}!",
  ["_LickitungDexEntry"] = "Il peut projeter\nsa langue comme\nun cameleon. Tout\12contact avec elle\nprovoque une\nirritation.<DEXEND>",
  ["_LightScreenProtectedText"] = "{USER}\nest protege con-\11tre les attaques\11speciales!",
  ["_LinedUpText"] = " en ligne!\n{RAM:wStringBuffer} jetons!",
