  ["_LinkCableHelpText1"] = "ASTUCE\12Le Cable Link",
  ["_LinkCableHelpText2"] = "Quel chapitre\ntu veux lire?",
  ["_LinkCableInfoText1"] = "Apres avoir\nconnecte deux\11GAME BOY, parlez\11a l'hotesse a\11droite dans tout\11CENTRE POKEMON.",
