  ["_LinkCanceledText"] = "La connexion a\nechoue.",
  ["_LoafingAroundText"] = "{RAM:wBattleMonNick}\nse balade...",
  ["_LoreleisRoomLoreleiAfterBattleText"] = "Tu es fort.\nZ'est bien.\12Mais la LIGUE\nPOKEMON te\11rezerve d'autres\11zurprizes!",
  ["_LoreleisRoomLoreleiBeforeBattleText"] = "Bienvenue a la\nLIGUE POKEMON!\12Je zuis OLGA du\nCONZEIL des 4!\12Je zuis la\nmaitrezze des\11POKEMON de glaze!\12Et la glaze...\nZ'est drop fort!\12Tes POKEMON\nzeront a ma merzi\11une fois geles!\12Ach! Ach! Ach!\nZ'est parti!",
  ["_LoreleisRoomLoreleiDontRunAwayText"] = "Une voix:\nFuis pas!",
  ["_LoreleisRoomLoreleiEndBattleText"] = "Comment\nas-t'oze?",
  ["_LoweredItsHeadText"] = "\nprend du recul!",
  ["_MachampDexEntry"] = "Ses coups de\npoing sont si\npuissants qu'ils\12font voler ses\nadversaires\njusqu'a l'horizon.<DEXEND>",
  ["_MachokeDexEntry"] = "Son corps est si\npuissant qu'il\nlui faut une\12ceinture de force\npour equilibrer\nses mouvements.<DEXEND>",
  ["_MachopDexEntry"] = "Il adore la\nmusculation.\nIl pratique les\12arts martiaux\npour devenir\nencore plus fort.<DEXEND>",
  ["_MadeWhirlwindText"] = "\ncree un cyclone!",
  ["_MagazinesText"] = "Des magazines\nPOKEMON!\12Des cahiers\nPOKEMON!\12Des dessins\nPOKEMON!",
  ["_MagikarpDexEntry"] = "Autrefois, il\netait ben gros\nplus puissant que\12cette creature\nminablement\nfaible.<DEXEND>",
  ["_MagmarDexEntry"] = "Son corps en\nfusion brule\nd'une flamme\12orangee, le\nrendant invisible\ndans le feu.<DEXEND>",
  ["_MagnemiteDexEntry"] = "Il controle la\ngravite pour\npouvoir voler. Il\12attaque avec des\nCAGE-ECLAIR.<DEXEND>",
  ["_MagnetonDexEntry"] = "Constitue de\nMAGNETI relies\nles uns aux\12autres, il\napparait lorsque\nle soleil brille.<DEXEND>",
  ["_MankeyDexEntry"] = "Il se met en\ncolere ben vite.\nCalme ou furieux,\12son humeur change\nd'une seconde a\nl'autre.<DEXEND>",
  ["_MarowakDexEntry"] = "L'os qu'il tient\ndans sa main est\nune arme. Il peut\12le lancer avec\nadresse pour\nassommer sa proie.<DEXEND>",
  ["_MartSignText"] = "Faites le plein\nd'objets!\12BOUTIQUE PKMN",
  ["_MeowthDexEntry"] = "Il adore les\npieces de monnaie.\nIl hante les rues\12a la recherche de\npieces oubliees\npar les passants.<DEXEND>",
  ["_MetapodDexEntry"] = "Il est vulnerable\naux attaques tant\nque sa carapace\12fragile expose\nson corps tendre\net mou.<DEXEND>",
  ["_MewDexEntry"] = "Unique et rare,\nson existence est\nremise en cause\12par les experts.\nPeu nombreux sont\nceux qui l'ont vu.<DEXEND>",
  ["_MewtwoBattleText"] = "Miou!",
  ["_MewtwoDexEntry"] = "Il est le fruit\nde nombreuses\nexperiences\12genetiques\nhorribles et\nmalsaines.<DEXEND>",
