  ["_MrFujisHouseLittleGirlPokemonAreNiceToHugText"] = "C'est si doux!\nFaire un calin a\11un POKEMON,\11c'est chou!",
  ["_MrFujisHouseLittleGirlThisIsMrFujisHouseText"] = "Voici la cabane\nde MR.FUJI.\12C'est pour vrai un\nchic type!\12Il est a la\nrecherche des\11POKEMON orphelins\11et abandonnes!",
  ["_MrFujisHouseMrFujiHasMyFluteHelpedYouText"] = "MR.FUJI: Ma FLUTE\nt'a ete utile?",
  ["_MrFujisHouseMrFujiIThinkThisMayHelpYourQuestText"] = "MR.FUJI: {PLAYER}.\12Ta quete pour\ncompleter ton\11POKEDEX echouera\11si t'aimes pas\11tes POKEMON.\12Je crois que ceci\nte sera utile.",
  ["_MrFujisHouseMrFujiPokeFluteExplanationText"] = "\12En jouant de la\nPOKEFLUTE, les\11POKEMON endormis\11se reveilleront.\12Elle marche sur\ntous les POKEMON.",
  ["_MrFujisHouseMrFujiPokeFluteNoRoomText"] = "Ton inventaire\nest plein!",
  ["_MrFujisHouseMrFujiPokedexText"] = "Grand concours de\ndessin de\11POKEMON!\12Le formulaire\nd'inscription\11est...\12...Hein? Il a\ndisparu!",
  ["_MrFujisHouseMrFujiReceivedPokeFluteText"] = "{PLAYER} obtient:\n{RAM:wStringBuffer}!",
