  ["_MrFujisHouseSuperNerdMrFujiIsntHereText"] = "Ce sacre MR.FUJI\nest pas la.\11Ou est-il?",
  ["_MrMimeDexEntry"] = "Derangez-le\npendant qu'il\nmime et il se\12battra en\ndistribuant des\nvolees de claques.<DEXEND>",
