  ["_MrPsychicsHouseMrPsychicYouWantedThisText"] = "...Chut! Pas un\nmot!\12Tu veux ca?",
  ["_MtMoon1FBewareZubatSign"] = "Fais gaffe! Les\nNOSFERAPTI sont\11des vampires!",
  ["_MtMoon1FCooltrainerF1AfterBattleText"] = "Comment on fait\npour sortir d'icitte?",
  ["_MtMoon1FCooltrainerF1BattleText"] = "Houla! C'est plus\nbaleze que j'le\11croyais, icitte!",
  ["_MtMoon1FCooltrainerF1EndBattleText"] = "RHAA!\nJ'ai perdu!",
  ["_MtMoon1FCooltrainerF2AfterBattleText"] = "Y parait qu'il\ny a des fossiles\11ben anciens\11dans le coin.",
  ["_MtMoon1FCooltrainerF2BattleText"] = "De quoi? J'attends\nmes potes icitte.",
  ["_MtMoon1FCooltrainerF2EndBattleText"] = "Nan!\nJ'ai perdu?",
  ["_MtMoon1FHikerAfterBattleText"] = "Cet endroit est\npas pour les\11mioches comme toi!",
  ["_MtMoon1FHikerBattleText"] = "YAHA! Tu m'as fait\npeur! Quoi? Mais\11t'es qu'un mioche!",
  ["_MtMoon1FHikerEndBattleText"] = "Whoa!\nTu m'as encore\11fait peur!!!",
  ["_MtMoon1FSuperNerdAfterBattleText"] = "J'dois m'trouver\ndes POKEMON plus\11costauds!",
  ["_MtMoon1FSuperNerdBattleText"] = "Ho!\nTu m'cherches?",
  ["_MtMoon1FSuperNerdEndBattleText"] = "Mes\nPOKEMON\11sont nuls!",
  ["_MtMoon1FYoungster1AfterBattleText"] = "J'suis la pour\nimpressionner les\11filles!\11Ouais mon gars!",
  ["_MtMoon1FYoungster1BattleText"] = "Tu es-tu aussi venu\npour explorer?",
  ["_MtMoon1FYoungster1EndBattleText"] = "Hmm!\nPerdre c'est MAL!",
  ["_MtMoon1FYoungster2AfterBattleText"] = "Je les ai vus!\nC'etait la\11TEAM ROCKET!",
  ["_MtMoon1FYoungster2BattleText"] = "Dans les grottes\non trouve de la\11racaille.\11T'en es?",
  ["_MtMoon1FYoungster2EndBattleText"] = "Ha!\nTu m'as eu!",
  ["_MtMoon1FYoungster3AfterBattleText"] = "Les NOSFERAPTI\nsont puissants!\11En attraper un\11peut etre utile!",
  ["_MtMoon1FYoungster3BattleText"] = "Je traverse ces\ngrottes pour\11aller a BAIE-COMEAU!",
  ["_MtMoon1FYoungster3EndBattleText"] = "J'ai...\nPerdu...",
  ["_MtMoonB2FDomeFossilYouWantText"] = "Tu veux-tu le\nfossile DOME?",
  ["_MtMoonB2FHelixFossilYouWantText"] = "Tu veux-tu le\nfossile NAUTILE?",
  ["_MtMoonB2FReceivedFossilText"] = "{PLAYER} obtient\n{RAM:wStringBuffer}!",
  ["_MtMoonB2FRocket1AfterBattleText"] = "A cause de toi\nj'suis vert!\11La TEAM ROCKET me\11vengera!",
