  ["_MtMoonB2FRocket2BattleText"] = "Nous autres, TEAM\nROCKET, on est des\11gangsters de\11POKEMON, calvaire!",
  ["_MtMoonB2FRocket2EndBattleText"] = "NOOOONNN!\nJ'ai perdu!",
  ["_MtMoonB2FRocket3AfterBattleText"] = "Si tu trouves un\nfossile, tu me le\11donnes et tu\11decampes, pige?",
  ["_MtMoonB2FRocket3BattleText"] = "Ca bosse dur\nicitte!\11Faque du balai,\11le mouflet!",
  ["_MtMoonB2FRocket3EndBattleText"] = "OK,\nt'es pas mauvais!",
  ["_MtMoonB2FRocket4AfterBattleText"] = "Les POKEMON\nexistaient bien\11avant l'homme...",
  ["_MtMoonB2FRocket4BattleText"] = "Les p'tits gamins\ns'occupent pas\11des affaires\11des grands!",
  ["_MtMoonB2FRocket4EndBattleText"] = "...\nJ'suis epuise!",
