  ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "OK, je prends\ncelui-ci!",
  ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "Loin d'icitte, sur\nla PERCE,\11se trouve un\11LABO POKEMON.\12On essaye d'y\nregenerer des\11fossiles de\11POKEMON.",
  ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "Hep! Toi la!\12Ces fossiles sont\na moi!\11Pas touche!",
  ["_MtMoonB2FYouHaveNoRoomText"] = "Attends, ton\ninventaire est\11plein!",
  ["_MtMoonB2fSuperNerdEachTakeOneText"] = "Chacun le sien!\nDe meme,\11pas de jaloux!",
  ["_MtMoonPokecenterBenchGuyText"] = "Tu devrais ranger\ntes POKEMON en\11trop via un PC!",
  ["_MtMoonPokecenterGentlemanText"] = "La TEAM ROCKET\na encore attaque\11les habitants\11de BAIE-COMEAU...\12La TEAM ROCKET\nest toujours aux\11infos!",
  ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "Bonjour l'ami!\nJ'ai une super\11affaire a te\11proposer!\12Je t'offre une\nMAGICARPE pour\11juste ¥500!\11Qu'en dis-tu?",
  ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "T'es a sec, mon\np'tit bouchon!",
  ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "Ni repris,\nni echange!",
  ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "Non? Va-zy lui!\nC'est un service\11que j'te rends!",
  ["_MtMoonPokecenterYoungsterText"] = "J'ai 6 POKE BALL\na ma ceinture.\12On peut\ntransporter que 6\11POKEMON.",
  ["_MukDexEntry"] = "Il est recouvert\nd'une epaisse\ncouche toxique.\12Il laisse une\ntrace empoisonnee\nderriere lui.<DEXEND>",
  ["_MultiHitText"] = "L'ennemi est\ntouche ",
  ["_Museum1FGamblerText"] = "Voici un\nsublime fossile!",
  ["_Museum1FOldAmberText"] = "L'AMBRE c'est\nbeau!!!",
  ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "L'AMBRE est de la\nseve fossilisee.",
  ["_Museum1FScientist1ComeAgainText"] = "A bientot!",
  ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "Te cache pas\ndans l'ombre!\12Enfin, si ca\nt'amuse! Au fait,\11sais-t'a quoi\11sert l'AMBRE?",
  ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "T'as pas\nassez d'cash.",
  ["_Museum1FScientist1GoToOtherSideText"] = "Va de l'autre\ncote!",
  ["_Museum1FScientist1TakePlentyOfTimeText"] = "Prends tout ton\ntemps pour\11regarder!",
  ["_Museum1FScientist1ThankYouText"] = "50¥! Parfait!\nMerci!",
  ["_Museum1FScientist1TheresALabSomewhereText"] = "Dans un certain\nlabo, on essaie\11de regenerer les\11anciens POKEMON\11grace a l'AMBRE.",
  ["_Museum1FScientist1WouldYouLikeToComeInText"] = "50¥ le ticket\npour un enfant.\12Tu veux-tu\nentrer?",
  ["_Museum1FScientist2GetTheOldAmberCheckText"] = "Chut! Va faire\nexaminer ce\11morceau d'AMBRE!",
  ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER} obtient\nVIEIL AMBRE!",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "Je crois qu'il y\na des traces\11d'ADN de POKEMON\11dans ce morceau\11d'ambre.\12Ca serait super\ncool capotant de\11regenerer un\11POKEMON a partir\11de cette pierre!\11Non? Hein?\12Mais personne ne\nme croit!\12J'ai une faveur a\nte demander!\12Apporte ca a mon\nLABO POKEMON pour\11l'examiner!",
  ["_Museum1FScientist2YouDontHaveSpaceText"] = "Ton inventaire\nest plein!",
