  ["_Museum2FBrunetteGirlText"] = "Je veux un\nPIKACHU!\12Popa va m'en\ntrouver un!",
  ["_Museum2FGrampsText"] = "20 Juillet 1969!\12L'homme a marche\nsur la lune!\12J'ai achete une\ntivi couleur!",
  ["_Museum2FHikerText"] = "Oui, oui, tu vas\nl'avoir ton\11PIKACHU...\11C'est ca.",
  ["_Museum2FMoonStoneSignText"] = "Des meteores sont\ntombes sur le\11MONT SELENITE.\11(PIERRE LUNE?)",
  ["_Museum2FScientistText"] = "Nous faisons une\nexposition sur\11l'espace.",
  ["_Museum2FSpaceShuttleSignText"] = "NAVETTE SPATIALE\nCOLUMBIA",
  ["_Museum2FYoungsterText"] = "PIERRE LUNE?\12Ouais? Et faque?",
  ["_MustRechargeText"] = "{USER}\nest a plat!",
  ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "{RAM:wNameBuffer}?\nC'est un nom\11parfait, fais-moi\11confiance, je\11m'y connais!\12Prends soin de\n{RAM:wNameBuffer}!",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "Faque petit, t'es\ncontent? Hmm...\11Reviens me voir\11quand tu veux!",
  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "{RAM:wNameBuffer}?\nMouais, c'est pas\11mal!\12Mais tu voudrais\nque je lui donne\11un nom un p'tit peu...\11plus...qui aurait\11plus de......\11Mieux, quoi!\12Bon, faque?",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "OK! Ce POKEMON\na ete renomme\11{RAM:wBuffer}!\12Oh, mais oui!\nC'est bien mieux\11qu'avant!",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "Salut tout le\nmonde! Je suis le\11GRAND DONNEUR DE\11NOMS!\12Dis-moi, petit,\ntu serais pas du\11genre a vouloir\11donner un p'tit\11nom a un de tes\11POKEMON?",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "Et faque, c'est\nquoi qu'on va lui\11donner comme nom\11a celui-la?",
