  ["_NeedYourPokemonText"] = "OK! Confiez-nous\nvos POKEMON!",
  ["_NewBadgeRequiredText"] = "Non! Un nouveau\nBADGE est requis.",
  ["_NewBicycleText"] = "Une BICYCLETTE\ntoute neuve! Top!",
  ["_NidokingDexEntry"] = "Sa queue est une\narme redoutable,\nil s'en sert pour\12attraper sa proie\net lui broyer les\nos.<DEXEND>",
  ["_NidoqueenDexEntry"] = "Ses ecailles ben\nresistantes et\nson corps massif\12sont des armes\ndevastatrices.<DEXEND>",
  ["_NidoranFDexEntry"] = "Ce POKEMON est\nherisse de dards\nempoisonnes.\12Les femelles ont\ndes dards plus\npetits.<DEXEND>",
  ["_NidoranMDexEntry"] = "Son ouie ben\nfine l'avertit du\ndanger. Plus\12ses cornes sont\ngrandes, plus son\npoison est mortel.<DEXEND>",
