  ["_NidorinoDexEntry"] = "Ben agressif, il\nest prompt a\nrepondre a la\12violence. La\ncorne sur sa tete\nest venimeuse.<DEXEND>",
  ["_NinetalesDexEntry"] = "Ben intelligent\net rancunier.\nAttrape-lui une\12de ses queues et\nil te maudira\npour 1000 ans.<DEXEND>",
