  ["_NothingToDepositText"] = "T'as rien\na stocker.",
  ["_OHKOText"] = "Capote patate!",
  ["_OKExclamationText"] = "!",
  ["_OakLabEmailText"] = "Y'a un courriel!\12...\12Avis a tous les\ndresseurs de\11POKEMON!\12Le CONSEIL des 4\nest pret a punir\11tout concurrent!\12Presente tes\nmeilleurs POKEMON\11et decouvre\11ton niveau\11en tant que\11dresseur!\12LIGUE POKEMON,\nQUEBEC\12PS: PROF. TREMBLAY,\nta visite est\11attendue...",
  ["_OakSpeechText1"] = "Bien le bonjour!\nBienvenue dans le\11monde magique des\11POKEMON!\12Mon nom est TREMBLAY!\nLes gens souvent\11m'appellent le\11PROF POKEMON!",
  ["_OakSpeechText2A"] = "Ce monde est\npeuple de\11creatures du nom\11de POKEMON!",
  ["_OakSpeechText2B"] = "\12Pour certains,\nles POKEMON sont\11des animaux\11domestiques, pour\11d'autres, ils\11sont un moyen de\11combattre.\12Pour ma part...\12L'etude des\nPOKEMON est\11ma profession.",
  ["_OakSpeechText3"] = "{PLAYER}!\12Ta quete des\nPOKEMON est sur\11le point de\11commencer!\12Un tout nouveau\nmonde de reves,\11d'aventures et\11de POKEMON\11t'attend! Dingue!",
  ["_OaksAideComeBackText"] = "Dans ce cas...\12Reviens quand tu\nauras ",
  ["_OaksAideGotItemText"] = "{PLAYER} obtient\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "Capote! Tu as\n",
  ["_OaksAideHiText"] = "Salut! Tu te\nrappelles? Je\11suis l'assistant\11du Prof. Chen!\12Si t'attrapes \n",
  ["_OaksAideNoRoomText"] = "Oh! Tu as plus\nde place pour\11{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Voyons voir...\nOh! Tu as\11attrape que ",
  ["_OaksLabGirlText"] = "Le PROF. TREMBLAY est\nla reference en\11matiere de\11POKEMON!\12Il est ben\nrespecte parmi\11les dresseurs de\11POKEMON!",
  ["_OaksLabGivePokeballsExplanationText"] = "\12Quand un POKEMON\nsauvage apparait,\11il faut jouer\11serre.\12Lance-lui une\nPOKE BALL pour le\ncapturer!\12Mais ca ne\nmarchera pas a\11tous les coups!\12Un POKEMON en\npleine forme peut\11s'echapper!\11C'est ca, la\11grande aventure\11des POKEMON!",
  ["_OaksLabLastMonText"] = "C'est le dernier\nPOKEMON du\11PROF. TREMBLAY!",
  ["_OaksLabMonEnergeticText"] = "Ce POKEMON est\nben energique!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "TREMBLAY: Reviens me\nvoir de temps en\11temps.\12Tiens-moi informe\ndu niveau de ton\11POKEDEX.",
  ["_OaksLabOak1DeliverParcelText"] = "TREMBLAY: {PLAYER}!\12Comment va ton\nPOKEMON?\12Je crois qu'il\nt'aime bien!\12Tu m'as l'air\ndoue pour\11entrainer les\11POKEMON!\12Comment? Tu as-tu\nquelque chose a\11me donner?\12{PLAYER} donne\nle COLIS DE TREMBLAY.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "TREMBLAY: Je suis\ncontent de te\11revoir. Ou en\11es-t'avec ton\11POKEDEX?\11Voyons, voyons...",
  ["_OaksLabOak1ParcelThanksText"] = "\12Ah! C'est la\nPOKE BALL que\11j'ai commandee!\11Merci!",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "Les POKEMON du\nmonde entier sont\11a toi, {PLAYER}!",
  ["_OaksLabOak1RaiseYourYoungPokemonText"] = "TREMBLAY: {PLAYER},\nentraine ton\11POKEMON au combat\11pour qu'il\11devienne fort!",
  ["_OaksLabOak1ReceivedPokeballsText"] = "TREMBLAY: Il te\nsuffit pas de\11voir un POKEMON\11pour tout savoir\11sur lui, mon\11p'tit bonhomme!\12Il te faut aussi\nl'attraper! Voici\11des POKE BALL\11pour en capturer.\12{PLAYER} obtient\n5 POKE BALL!",
  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "TREMBLAY: {PLAYER},\nquel POKEMON \11choisis-tu?",
  ["_OaksLabOak1YourPokemonCanFightText"] = "TREMBLAY: Ton POKEMON\nte protegera des\11POKEMON sauvages!",
  ["_OaksLabOak2Text"] = "?",
  ["_OaksLabOakBePatientText"] = "TREMBLAY: Patience,\n{RIVAL}! Tu en\11auras un aussi!",
  ["_OaksLabOakChooseMonText"] = "TREMBLAY: {RIVAL}?\nHeu...\12Ah, c'est vrai!\nJe t'ai dit de\11venir...\12Tiens, {PLAYER}!\12Voici 3 POKEMON!\12Mais...\12Ils sont dans des\nPOKE BALL.\12Plus jeune,\nj'etais un sacre\11dresseur de\11POKEMON! Et oui!\12Mais avec l'age,\nil m'en reste\11plus que 3!\11Choisis-en un!",
  ["_OaksLabOakDontGoAwayYetText"] = "TREMBLAY: He! Pars\npas tout d'suite!",
  ["_OaksLabOakGotPokedexText"] = "TREMBLAY: {PLAYER} et\n{RIVAL}! Prenez\11ces POKEDEX!\12{PLAYER} obtient\nle POKEDEX!",
  ["_OaksLabOakIHaveARequestText"] = "TREMBLAY: Bon! J'ai\nune faveur a te\11demander.",
  ["_OaksLabOakMyInventionPokedexText"] = "Y'a sur ce\nbureau mon\11invention...\11Le POKEDEX!\12Il enregistre les\ninformations sur\11les POKEMON\11rencontres ou\11captures!\12C'est comme une\nencyclopedie!",
  ["_OaksLabOakThatWasMyDreamText"] = "Faire un guide\ncomplet sur les\11POKEMON du monde\11entier...\12C'est mon reve!\12Mais je suis trop\nvieux asteur!\12C'est pourquoi je\nveux que tu\11termines mon\11job!\12Allez, roulez\njeunesse!\12Que la grande\nquete des POKEMON\11commence!",
  ["_OaksLabPokedexText"] = "C'est comme une\nencyclopedie\11mais les pages\11sont blanches!",
  ["_OaksLabReceivedMonText"] = "{PLAYER} obtient:\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Ben la,\ntabarnak, chu le\11meilleur, tse!",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Pepe!\nJ'en ai marre\11d'attendre!",
  ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}: Je ne\nsuis pas avide\11comme toi!\12Allez, choisis,\n{PLAYER}!",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: Yo!\n{PLAYER}! Pepe\11est pas la!",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}: Pepe!",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "QUOI???\nIncroyable!\11J'ai pas pris le\11bon POKEMON!",
  ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}: Je\nprends celui-ci!",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Minute,\n{PLAYER}!\11Voyons lequel de\11nos POKEMON est\11le plus fort!\12Allez viens te\nbattre, minable!",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}: OK,\npepe! Donne-les\11moi tous!\12{PLAYER}, c'est\nclair, j'ai pas\11besoin de toi,\11minable!\12Je sais! Je vas\nvoler une CARTE a\11ma soeur!\12Et je lui dirai\nde pas t'en\11donner une! Yark!",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Mon\nPOKEMON est\11plus fort.",
  ["_OaksLabRivalReceivedMonText"] = "{RIVAL} recoit\nun {RAM:wNameBuffer}!",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: OK!\nJe vas entrainer\11mon POKEMON!\12{PLAYER}! Pepe!\nA plus tard!",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: Ben!\nPepe! Mon pepe!\11Et moi?",
  ["_OaksLabRivalWhatDidYouCallMeForText"] = "{RIVAL}: Pourquoi\ntu m'as appele?",
  ["_OaksLabScientistText"] = "J'assiste le\nPROF. TREMBLAY.\11Je suis donc son\11...ta daaa!...\11ASSISTANT!",
  ["_OaksLabThoseArePokeBallsText"] = "Ces POKE BALL\ncontiennent des\11POKEMON!",
