  ["_OaksLabYouWantSquirtleText"] = "Veux-tu le\nPOKEMON de l'eau,\11CARAPUCE?",
  ["_OddishDexEntry"] = "Pendant la\njournee il se\ncache sous terre.\12Il s'aventure la\nnuit pour planter\ndes graines.<DEXEND>",
