  ["_OlderFileWillBeErasedText"] = "L'ancienne\nsauvegarde sera\11effacee. OK?",
  ["_OmanyteDexEntry"] = "Disparu depuis\nlongtemps, il\npeut etre reanime\12genetiquement a\npartir d'anciens\nfossiles.<DEXEND>",
  ["_OmastarDexEntry"] = "Un POKEMON\nprehistorique qui\ndisparut quand sa\12coquille devint\ntrop lourde a\ndeplacer.<DEXEND>",
