  ["_PersianDexEntry"] = "Ben apprecie\npour sa fourrure,\nil est difficile\12a apprivoiser en\nraison de son\ncaractere retif.<DEXEND>",
  ["_PewterCityCooltrainerFText"] = "On raconte que\nles MELOFEE sont\11les habitants de\11la lune!\12Ils sont apparus\napres la chute de\11la PIERRE LUNE\11sur le MONT\11SELENITE.",
  ["_PewterCityCooltrainerMText"] = "Y'a de ben\nbons dresseurs\11par icitte!\12Ils sont SCOUTS\npour la plupart\11mais GAETAN de\11l'ARENE de THETFORD MINES\11est terrible!",
  ["_PewterCityGymSignText"] = "ARENE POKEMON\nde THETFORD MINES\11CHAMPION: GAETAN\12L'dresseur dur\ncomme la pierre!\11Bonne blague.",
  ["_PewterCityMuseumSignText"] = "MUSEE DES\nSCIENCES\11de THETFORD MINES",
  ["_PewterCityPokecenterGuyText"] = "(Baille)!\12Lorsque RONDOUDOU\nchante, tous les\11POKEMON piquent\11du nez...\12...Moi aussi...\n(Pionce)...",
  ["_PewterCityPoliceNoticeSignText"] = "AVIS!\12On nous signale\ndes voleurs de\11fossiles de\11POKEMON sur le\11MONT SELENITE.\11Hesitez pas a\11contacter la\11POLICE de THETFORD MINES!",
  ["_PewterCitySignText"] = "THETFORD MINES\nLe mat et le gris\11de la roche.",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Es-t'alle au\nMUSEE?",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "C'est par la!\nL'entree est\11payante mais ca\11vaut l'coup!",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "Les fossiles du\nMONT SELENITE\11sont beaux, hein?",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "Non?\nMais il faut y\11aller, voyons!",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "Psssst!\nTu sais c'que\11j'fais?",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Je vaporise du\nREPOUSSE pour\11eloigner les\11POKEMON de mon\11bo jardin!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "Ah bon?\nOK.",
  ["_PewterCityTrainerTipsText"] = "ASTUCE\12Chaque POKEMON\nprenant part au\11combat, meme pen-\11dant une seconde,\11gagne de l'EXP!",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "Si t'es fort...\nT'as pas tort...\11Faque...\11Bats GAETAN...\11Ou t'es mort!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "T'es un dresseur?\nPIERRE cherche un\11adversaire!\11Suis-moi!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "\12C'est un BADGE\nofficiel de la\11LIGUE POKEMON!\12Les POKEMON de\nson detenteur\11deviennent plus\11puissants!\12La technique\nFLASH peut etre\11utilisee!",
  ["_PewterGymBrockPostBattleAdviceText"] = "Y'a plusieurs\ntypes de\11dresseurs dans le\11monde!\12Tu sembles etre\nun dresseur\11d'exception!\12Va a l'ARENE\nde BAIE-COMEAU pour\11tester tes\11capacites.",
  ["_PewterGymBrockPreBattleText"] = "Je suis GAETAN!\nJe suis le\11CHAMPION\11de THETFORD MINES!\12Je crois en la\ngrande resistance\11de la pierre!\12C'est pourquoi\nmes POKEMON sont\11des elementaires\11de pierre!\12Tu veux toujours\nte battre avec\11moi? Ben correct.\11En garde!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "Hmm...\nBeau combat.\12En reconnaissance\nde ta victoire,\11voici le BADGE\11ROCHE!\12{PLAYER} recoit\nle BADGE ROCHE!",
  ["_PewterGymBrockWaitTakeThisText"] = "Attends! Prends\nca avec toi!",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Tu es fort...\nMais pas autant\11que GAETAN!",
  ["_PewterGymCooltrainerMBattleText"] = "Une minute,\ngamin!\12Tu es encore loin\nde GAETAN, tu\11vas devoir\11m'affronter!",
  ["_PewterGymCooltrainerMEndBattleText"] = "Mautadine!\12J'aurais du te\nlaisser passer!",
  ["_PewterGymGuideAdviceText"] = "Le 1er POKEMON\napparaissant dans\11un combat est\11celui en tete de\11la LISTE POKEMON!\12En changeant\nl'ordre des\11POKEMON, tu\11peux changer de\11strategie!",
  ["_PewterGymGuideBeginAdviceText"] = "OK! C'est\nparti!",
  ["_PewterGymGuideFreeServiceText"] = "C'est gratuit,\nprofites-en! ",
  ["_PewterGymGuidePostBattleText"] = "Je le savais!\nTu as l'ame d'un\11champion!",
  ["_PewterGymGuidePreAdviceText"] = "Salut graine de\nCHAMPION!\12Je suis pas\ndresseur mais mes\11conseils sont\11avises!\12Laisse-moi te\nmener a la\11victoire!",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER} recoit\nla CT34!",
  ["_PewterGymTM34NoRoomText"] = "Ton inventaire\nest plein!",
  ["_PewterMartSuperNerdText"] = "Si t'eleves bien\ntes POKEMON, meme\11les plus faibles,\11il se passera\11rien que des\11bonnes choses!",
  ["_PewterMartYoungsterText"] = "Un vieil homme\nm'a vendu cet\11etrange poisson\11POKEMON!\12Il est super nul\net il m'a coute\11500¥!",
  ["_PewterNidoranHouseLittleBoyText"] = "NIDORAN, assis!",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Notre POKEMON est\nun echange, il\11est difficile a\11maitriser.\12Un echange est\nun POKEMON\11echange avec un\11autre joueur.\12Il grandit vite,\nmais il en fait\11qu'a sa tete\11pendant les\11combats!\12Si seulement nous\navions des...\11BADGES!",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Nidoni!",
  ["_PewterPokecenterGentlemanText"] = "Quoi!?\12La TEAM ROCKET\na investi le\11MONT SELENITE!\12Damnation!",
  ["_PewterPokecenterJigglypuffText"] = "RONDOUDOU: Dou!\nDoudouuuu!",
  ["_PewterSpeechHouseGamblerText"] = "Un POKEMON\napprend des\11attaques en\11gagnant des\11niveaux!\12Mais certaines\nattaques ne\11sont enseignees\11que par les\11dresseurs!",
  ["_PewterSpeechHouseYoungsterText"] = "Les POKEMON sont\nplus faciles a\11capturer une fois\11endormis ou\11blesses!\12Mais attraper un\nPOKEMON, c'est\11jamais du tout\11cuit!",
  ["_PickUpPayDayMoneyText"] = "{PLAYER} ramasse:\n¥",
  ["_PidgeotDexEntry"] = "Il chasse en\nsurvolant la\nsurface de l'eau\12et en plongeant\npour attraper des\nproies faciles.<DEXEND>",
  ["_PidgeottoDexEntry"] = "Il protege son\nterritoire avec\nardeur et\12repousse a coups\nde bec tout\nintrus.<DEXEND>",
  ["_PidgeyDexEntry"] = "Il est souvent vu\ndans les forets.\nIl brasse l'air\12de ses ailes pres\ndu sol pour\nprojeter du sable.<DEXEND>",
  ["_PikachuDexEntry"] = "Quand plusieurs\nde ces POKEMON\nse reunissent,\12ils provoquent\nde gigantesques\norages.<DEXEND>",
  ["_PinsirDexEntry"] = "Quand il peut\necraser sa proie\navec sa pince, il\12la secoue et\nl'envoie dans les\nairs.<DEXEND>",
