  ["_PokemonCenterWelcomeText"] = "Bienvenue dans\nnotre CENTRE\11POKEMON!\12Nous soignons les\nPOKEMON!",
  ["_PokemonFaintedText"] = "{RAM:wNameBuffer}\nest K.O.!",
  ["_PokemonFanClubBagFullText"] = "Ton inventaire\nest plein!",
  ["_PokemonFanClubChairFinalText"] = "Salut, {PLAYER}!\12t'es venu pour\necouter mes\11histoires de\11POKEMON?\12Non? Dommage!",
  ["_PokemonFanClubChairmanIntroText"] = "Je suis le maitre\ndu Fan Club des\11POKEMON!\12J'ai plus de 100\nPOKEMON!\12Je suis trop mega\ntatillon quand on\11parle de POKEMON!\12Faque...\12Tu veux encore\nsavoir des trucs\11sur mes POKEMON?",
  ["_PokemonFanClubChairmanStoryText"] = "Bien!\nFaque, ecoute!\12Mon prefere...\nGALOPA...\12Il est mignon...\nbeau...rapide...\11elegant...en feu.\11Il fait pataclop,\11pataclop...quand\11il court...c'est\11super non?\11Je l'aime...!\12Je lui fais...des\ncalins...des...\11poutoux...des...\11gnangnans...des\11zigouzigoux...\11...Oups! Regarde\11l'heure! Je crois\11qu'il est temps\11d'y aller!\12Merci d'avoir\necoute! Tiens,\11prends ca!",
  ["_PokemonFanClubExplainBikeVoucherText"] = "\12Echange ca contre\nune BICYCLETTE!\12Moi, c'est mon\nRAPASDEPIC qui me\11transporte\11n'importe ou!\12Je ai plus\nbesoin de\11BICYCLETTE!\12J'espere que tu\naimes pedaler!",
  ["_PokemonFanClubNoStoryText"] = "Reviens quand tu\nveux. Je te\11raconterai mes\11histoires!",
  ["_PokemonFanClubPikachuFanBetterText"] = "Hmm! Mon PIKACHU\nest deux fois\11plus mignon que\11celui-ci!",
  ["_PokemonFanClubPikachuFanNormalText"] = "Mon PIKACHU est\nle plus beau de\11tous les PIKACHU!",
  ["_PokemonFanClubPikachuText"] = "PIKACHU: Chu!\nPikachu!",
  ["_PokemonFanClubReceivedBikeVoucherText"] = "{PLAYER} recoit:\n{RAM:wStringBuffer}!",
  ["_PokemonFanClubReceptionistText"] = "Notre maitre est\nben bavard en ce\11qui concerne les\11POKEMON.",
  ["_PokemonFanClubSeelFanBetterText"] = "Oh!\12Mon OTARIA est\nben gros plus\11elegant!",
  ["_PokemonFanClubSeelFanNormalText"] = "Moi, c'que j'aime\nc'est OTARIA!\12Y fait squitch\nquand je lui fais\11un calin!",
  ["_PokemonFanClubSeelText"] = "OTARIA: Riaaa!",
  ["_PokemonFanClubSign1Text"] = "Ecoutons donc\nl'avis des\11autres dresseurs!",
  ["_PokemonFanClubSign2Text"] = "Si on te nargue,\nnargue en retour!",
  ["_PokemonFightingFitText"] = "Merci!\nTes POKEMON sont\11en feu, asteur!",
  ["_PokemonMansion1FScientistAfterBattleText"] = "Une cle? Je ne\nsais pas d'quoi\11tu parles.",
  ["_PokemonMansion1FScientistBattleText"] = "Qui es-tu?\nC'est interdit\11eud' se balader.",
  ["_PokemonMansion1FScientistEndBattleText"] = "Aie!",
  ["_PokemonMansion1FSwitchNotPressedText"] = "Pas pour vrai...",
  ["_PokemonMansion1FSwitchPressedText"] = "Sans blague!",
  ["_PokemonMansion1FSwitchText"] = "Un bouton secret!\12On appuie?",
  ["_PokemonMansion2FDiary1Text"] = "Rapport:\n5 Juillet.\11Jungle X.\12Un nouveau type \nde POKEMON fut\11decouvert.",
  ["_PokemonMansion2FDiary2Text"] = "Rapport:\n10 Juillet.\11Le POKEMON fut\11baptise MEW.",
  ["_PokemonMansion2FSuperNerdAfterBattleText"] = "Les interrupteurs\nouvrent et\11ferment alterna-\11tivement les\11portes!",
  ["_PokemonMansion2FSuperNerdBattleText"] = "Mais... J'suis\ncompletement\11paume!",
  ["_PokemonMansion2FSuperNerdEndBattleText"] = "Non!\nMon butin!",
  ["_PokemonMansion2FSwitchNotPressedText"] = "Pas pour vrai!",
  ["_PokemonMansion2FSwitchPressedText"] = "Sans blague...",
  ["_PokemonMansion2FSwitchText"] = "Un interrupteur!\12L'actionner?",
  ["_PokemonMansion3FDiaryText"] = "Rapport:\n6 Fevrier.\11MEW est papa \11(ou maman?)\12Le petit fut\nbaptise MEWTWO.",
  ["_PokemonMansion3FScientistAfterBattleText"] = "T'es perdu?\nEssaie de sauter\11par la-bas!",
  ["_PokemonMansion3FScientistBattleText"] = "Mon mentor vivait\nicitte autrefois.",
  ["_PokemonMansion3FScientistEndBattleText"] = "!!!\nImpressionnant!",
  ["_PokemonMansion3FSuperNerdAfterBattleText"] = "Mais ou est donc\nmon complice?",
  ["_PokemonMansion3FSuperNerdBattleText"] = "Fouiii...\nC'est grand icitte!",
  ["_PokemonMansion3FSuperNerdEndBattleText"] = "Yargl!",
  ["_PokemonMansionB1FBurglarAfterBattleText"] = "De bons objets\ntrainent dans le\11coin.",
  ["_PokemonMansionB1FBurglarBattleText"] = "Oh-oh. Ou que je\nsuis, moi?",
  ["_PokemonMansionB1FBurglarEndBattleText"] = "Oups.",
  ["_PokemonMansionB1FDiaryText"] = "Rapport:\n1er Septembre.\11MEWTWO est trop\11puissant.\12Nous sommes\nimpuissants face\11a ses pieges...",
  ["_PokemonMansionB1FScientistAfterBattleText"] = "J'adore cet\nendroit! J'y fais\11mon internat!",
  ["_PokemonMansionB1FScientistBattleText"] = "La science?\nC'est le pied.",
  ["_PokemonMansionB1FScientistEndBattleText"] = "...\nBah pourquoi?",
  ["_PokemonSellingGreetingText"] = "Que desires-tu\nvendre?",
  ["_PokemonStuffText"] = "Cool! Plein de\nmachins sur les\11POKEMON!",
  ["_PokemonTower1FBaldingGuyText"] = "Je suis venu\nprier pour mon\11MELOFEE.\12Sniff! J'arrete\npas de pleurer...",
  ["_PokemonTower1FChannelerText"] = "Je suis une\nEXORCISTE! Je\11chasse les\11esprits!",
  ["_PokemonTower1FGirlText"] = "Mon CANINOS...\nReviens...",
  ["_PokemonTower1FMiddleAgedWomanText"] = "Tu es-tu venu leur\nrendre hommage?\11Grand bien t'en\11fasse!",
  ["_PokemonTower1FReceptionistText"] = "La TOUR DE VAL-JALBERT a\nete erigee en\11memoire des\11braves POKEMON\11morts au combat.",
  ["_PokemonTower2FChannelerText"] = "Nous pouvons\nidentifier les\11SPECTRES!\12Un SCOPE SYLPHE\npourrait les\11demasquer.",
  ["_PokemonTower2FRivalDefeatedText"] = "Hein?\nPetit fennec!\12Je t'ai pas\npris au serieux!\11M-I-N-A-B-L-E!",
  ["_PokemonTower2FRivalHowsYourDexText"] = "Ou en est ton\nPOKEDEX? Je\11viens de capturer\11un OSSELAIT!\12Je ai pas\nencore trouve de\11OSSATUEUR!\12Je crois qu'il\nen existe plus!\11Je dois y aller,\11minable! J'ai du\11pain sur la\11planche, minable!\12A bientot...\nGros minable!",
  ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}: Ben,\nregarde-moi tous\11ces POKEMON\11epais!\12Muscle-les un\ntit peu, calvaire!",
  ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}: He,\n{PLAYER}!\11Kesstu fais la?\11Tes POKEMON sont\11pas morts!\12Je peux quand\nmeme les mettre\11K.O.! Minable!",
  ["_PokemonTower3FChanneler1AfterBattleText"] = "Un SPECTRE est\nidentifiable avec\11un SCOPE SYLPHE.",
  ["_PokemonTower3FChanneler1BattleText"] = "Urrg...Awaa...\nHuhu...graa..",
  ["_PokemonTower3FChanneler1EndBattleText"] = "Ha!\nJe suis sauvee!",
  ["_PokemonTower3FChanneler2AfterBattleText"] = "Pardon! J'etais\npossedee!",
  ["_PokemonTower3FChanneler2BattleText"] = "Kekeke....\nKwaaah!",
  ["_PokemonTower3FChanneler2EndBattleText"] = "Hmm?\nQu'est-ce que je\11fais la?",
  ["_PokemonTower3FChanneler3AfterBattleText"] = "Mes amies etaient\naussi possedees!",
  ["_PokemonTower3FChanneler3BattleText"] = "VADE RETRO!\nEsprit infernal!",
  ["_PokemonTower3FChanneler3EndBattleText"] = "Pfiou!\nL'esprit s'en est\11alle!",
  ["_PokemonTower4FChanneler1AfterBattleText"] = "J'ai du rever...",
  ["_PokemonTower4FChanneler1BattleText"] = "Un SPECTRE!\nRhaaaaaa!",
  ["_PokemonTower4FChanneler1EndBattleText"] = "Ben!\nOu est le\11SPECTRE?",
  ["_PokemonTower4FChanneler2AfterBattleText"] = "Nous pouvons\nidentifier les\11SPECTRES.",
  ["_PokemonTower4FChanneler2BattleText"] = "Sois maudit!!!!\nKwaaah!",
  ["_PokemonTower4FChanneler2EndBattleText"] = "QUOI!",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "Que les ames des\ndefunts POKEMON\11reposent en paix!",
  ["_PokemonTower4FChanneler3BattleText"] = "Huhuhu...\nMe frappe pas!",
  ["_PokemonTower4FChanneler3EndBattleText"] = "Hein?\nQui? Quoi?",
  ["_PokemonTower5FChanneler1Text"] = "Approche, enfant!\nJ'ai scelle cet\11endroit grace a\11ma sainte magie\11blanche!\12Tu peux te\nreposer icitte!",
  ["_PokemonTower5FChanneler2AfterBattleText"] = "J'etais possedee!",
  ["_PokemonTower5FChanneler2BattleText"] = "Donne...moi...\nton...ame...",
  ["_PokemonTower5FChanneler2EndBattleText"] = "Glargh!",
  ["_PokemonTower5FChanneler3AfterBattleText"] = "J'etais possedee!",
  ["_PokemonTower5FChanneler3BattleText"] = "Viens...avec...\nnous...",
  ["_PokemonTower5FChanneler3EndBattleText"] = "Hein!\nJ'ai fait un\11cauchemar!",
  ["_PokemonTower5FChanneler4AfterBattleText"] = "Je suis revenue a\nla raison!",
  ["_PokemonTower5FChanneler4BattleText"] = "Zombis!",
  ["_PokemonTower5FChanneler4EndBattleText"] = "Hein?",
  ["_PokemonTower5FChanneler5AfterBattleText"] = "Mon Tao a moi,\nc'est le plus bo\11des Taos!",
  ["_PokemonTower5FChanneler5BattleText"] = "Poye Polomi!\nLe mal est parmi\11nous....",
  ["_PokemonTower5FChanneler5EndBattleText"] = "Quoi?\nJeune taoiste, tu\11oses m'oter le\11yang de la \11bouche!",
  ["_PokemonTower5FPurifiedZoneText"] = "Tu rentres\ndans une zone\11sanctuaire!\12Les POKEMON de\n{PLAYER} sont\11soignes!",
  ["_PokemonTower6FBeGoneText"] = "Fuis...\nImpudent...",
  ["_PokemonTower6FChanneler1AfterBattleText"] = "Je me sens\nfaible...",
  ["_PokemonTower6FChanneler1BattleText"] = "Ton...Sang...\nDonne...",
  ["_PokemonTower6FChanneler1EndBattleText"] = "Grargh!",
  ["_PokemonTower6FChanneler2AfterBattleText"] = "J'etais sous\nl'emprise d'un\11esprit!",
  ["_PokemonTower6FChanneler2BattleText"] = "Urff... Kwaah!",
  ["_PokemonTower6FChanneler2EndBattleText"] = "Haaa!\nJe me sens mieux!",
  ["_PokemonTower6FChanneler3AfterBattleText"] = "Mais qu'est-ce\nqui se passe icitte?",
  ["_PokemonTower6FChanneler3BattleText"] = "Ke..ke...ke...\nke..ke...ke!!",
  ["_PokemonTower6FChanneler3EndBattleText"] = "Keee!",
  ["_PokemonTower6FGhostWasCubonesMotherText"] = "Le SPECTRE etait\nl'esprit damne de\11la mere de\11OSSELAIT!",
  ["_PokemonTower6FSoulWasCalmedText"] = "L'ame de la mere\na ete apaisee.\12Elle est partie\nvers l'autre\11monde!",
  ["_PokemonTower7FMrFujiRescueText"] = "MR.FUJI: He? Tu\nes venu me\11sauver?\12Merci! Mais je\nsuis venu icitte de\11mon plein gre.\12Je voulais\napaiser l'esprit\11de la mere de\11OSSELAIT.\12Je pense que\nl'esprit de\11OSSATUEUR s'en\11est alle vers\11les cieux.\12Je dois te\nremercier pour\11cet acte noble!\12Viens avec moi\ndans ma cabane,\11la MAISON POKEMON\11au pied de cette\11tour.",
  ["_PokemonTower7FRocket1AfterBattleText"] = "Je t'oublierai\npas!",
  ["_PokemonTower7FRocket1BattleText"] = "Que veux-tu?\nQue cherches-tu?",
  ["_PokemonTower7FRocket1EndBattleText"] = "Rhaaaa!\nJ'abandonne!",
  ["_PokemonTower7FRocket2AfterBattleText"] = "Les POKEMON ne\nservent qu'a\11gagner de\11l'cash!\12Reste en dehors\nde nos affaires!",
  ["_PokemonTower7FRocket2BattleText"] = "Ce vieil homme\nest venu nous\11demander de ne\11plus troubler les\11gentils POKEMON!\12Mais c'est une\nconversation\11d'adultes, petit!\11Degage!",
  ["_PokemonTower7FRocket2EndBattleText"] = "Argh!\nAssez!",
  ["_PokemonTower7FRocket3AfterBattleText"] = "Tu t'en\nsortiras pas\11de meme!",
  ["_PokemonTower7FRocket3BattleText"] = "Tu sauves personne,\ntabarnak de\11morveux!",
  ["_PokemonTower7FRocket3EndBattleText"] = "Te bats pas\ncontre nous\11autres, les\11ROCKET, calvaire!",
  ["_PoliwagDexEntry"] = "Il court mal\navec ses petites\npattes.\12Il prefere nager\nque de se tenir\ndebout.<DEXEND>",
  ["_PoliwhirlDexEntry"] = "Amphibie, il peut\nvivre a l'air\nlibre mais il\12doit rester\nmouille pour\nsurvivre.<DEXEND>",
  ["_PoliwrathDexEntry"] = "Excellent nageur,\nil pratique le\ncrawl ou la nage\12papillon mieux\nqu'un champion\nolympique.<DEXEND>",
  ["_PonytaDexEntry"] = "Ses sabots sont\nplus resistants\nque le diamant.\12Il peut aplatir\nn'importe quoi en\nle pietinant.<DEXEND>",
  ["_PoofText"] = "Pouet!",
  ["_PorygonDexEntry"] = "Un POKEMON fait\nde programmes et\nd'algorithmes. Il\12peut survivre en\nmilieu virtuel.<DEXEND>",
  ["_PotionText"] = "{RAM:wNameBuffer}\ngagne ",
  ["_PowerPlantVoltorbBattleText"] = "Bzzzt!",
  ["_PowerPlantZapdosBattleText"] = "Yahoo!",
  ["_PrimeapeDexEntry"] = "Agressif et\nteigneux, il\npoursuit son\12gibier jusqu'a\nepuisement\ncomplet.<DEXEND>",
  ["_PsyduckDexEntry"] = "Il distrait ses\nennemis avec des\ngrimaces debiles\12et les attaque\nensuite avec ses\npouvoirs psy.<DEXEND>",
  ["_PushStartText"] = "START et...paf!\nV'la le MENU!",
  ["_RaichuDexEntry"] = "Il doit garder sa\nqueue en contact\navec le sol pour\12eviter toute\nelectrocution.<DEXEND>",
  ["_RaisePPWhichTechniqueText"] = "Monter les PP de\nquelle attaque?",
  ["_RanAwayScaredText"] = "{TARGET}\npanique et fuit!",
  ["_RanFromBattleText"] = "{USER}\nfuit le combat!",
  ["_RapidashDexEntry"] = "Dote d'un esprit\nde competition,\nil poursuit\12toute creature\nrapide pour\nfaire la course.<DEXEND>",
  ["_RareCandyText"] = "{RAM:wNameBuffer} monte\nau niveau ",
  ["_RaticateDexEntry"] = "Si ses moustaches\nsont coupees, il\nperd le sens de\12l'equilibre et\ndevient moins\nrapide.<DEXEND>",
  ["_RattataDexEntry"] = "Sa morsure est\nben puissante.\nPetit et rapide,\12on en voit un\npeu partout.<DEXEND>",
  ["_RedBedroomSNESText"] = "{PLAYER} joue a la\nCapote Nintendo!\11...Bon!\11On y va, non?",
  ["_RedsHouse1FMomLookingGreatText"] = "MERE: Ah, bien!\nToi et tes\11POKEMON etes\11en pleine forme!",
  ["_RedsHouse1FMomWakeUpText"] = "MERE: Bon.\nIl arrive qu'un\11jour le fils aime\11quitte la cabane.\11C'est la vie!\12Le PROF. TREMBLAY te\ncherche. Il est\11dans la cabane\11voisine.",
  ["_RedsHouse1FMomYouShouldRestText"] = "MERE: {PLAYER}!\nTu devrais faire\11une sieste.",
  ["_RedsHouse1FTVStandByMeMovieText"] = "Un dessin anime!\nUn petit gars\11avec une queue de\11singe.\12Bon, j'y vais!",
  ["_RedsHouse1FTVWrongSideText"] = "Oups, mauvais\ncote.",
  ["_ReflectGainedArmorText"] = "{USER}\naugmente sa\11protection!",
  ["_RegainedHealthText"] = "{USER}\nregenere!",
  ["_ReleaseWhichMonText"] = "Relacher quel\nPOKEMON?",
  ["_RepelWoreOffText"] = "L'effet REPOUSSE\nest termine.",
  ["_RequireCoinCaseText"] = "T'as pas\nde BOITE JETON!",
  ["_RestorePPWhichTechniqueText"] = "Remplir les PP de\nquelle attaque?",
  ["_ReviveText"] = "{RAM:wNameBuffer}\nrevient a lui!",
  ["_RhydonDexEntry"] = "Son epiderme ben\nepais lui permet\nde survivre dans\12un environnement\nde plus de 3600\ndegres.<DEXEND>",
  ["_RhyhornDexEntry"] = "Avec une ossature\n1000 fois plus\nresistante que\12celle de l'homme,\nses charges sont\ndevastatrices.<DEXEND>",
  ["_Rival1WinText"] = "{RIVAL}: Ben la,\ntabarnak, chu le\11meilleur, tse!",
  ["_RivalDefeatedText"] = "NON!\nCa se peut pas,\11tabarnak!\11T'as battu mon\11meilleur!\12Apres tout ce\ntravail pour\11devenir champion\11de la LEAGUE?\12Mon regne est deja\nfini? C'est pas\11correct pantoute!",
  ["_RivalVictoryText"] = "Hahaha!\nJ'ai gagne, j'ai\11gagne!\12Chu ben trop bon\npour toi,\11tabarnak!\12T'as ben essaye,\nle perdant!\11Hahaha!",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "J'ai vu un\nMACHOC dans\11ce tunnel!",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "Hep! Dans le noir\nfais gaffe ou tu\11mets tes pieds!",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "J'ai\nrien compris!",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "T'as pas l'air si\nmechant pourtant!",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "Je viens de loin\npour ces POKEMON!",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "Ho!\nPlus de POKEMON!",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "He ben! Me voila\nen sueur!",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "T'as des POKEMON!\nOK, bastooonn!",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "T'es\nun dur toi!",
  ["_RockTunnel1FHiker1AfterBattleText"] = "Attention a ONIX!\nIl pourrait\11t'ecrabouiller!",
  ["_RockTunnel1FHiker1BattleText"] = "Il est long ce\ntunnel, oh oui!",
  ["_RockTunnel1FHiker1EndBattleText"] = "Roooh!\nT'as gagne!",
  ["_RockTunnel1FHiker2AfterBattleText"] = "Ce POKEMON\nendormi sur la\11route 12 m'a\11oblige a faire\11un detour.",
  ["_RockTunnel1FHiker2BattleText"] = "Bon, bon, bon,\nje suis perdu...",
  ["_RockTunnel1FHiker2EndBattleText"] = "Hein?\nC'est quoi qui\11faut qu'je fais?",
  ["_RockTunnel1FHiker3AfterBattleText"] = "Tu pourrais faire\nun bon montagnard\11mon p'tit gars!",
  ["_RockTunnel1FHiker3BattleText"] = "Un profane\ncomme toi me\11doit le respect!",
  ["_RockTunnel1FHiker3EndBattleText"] = "Perdu!",
  ["_RockTunnel1FSignText"] = "GROTTE\nBAIE-COMEAU -\11VAL-JALBERT",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "Bon, il me faut\nun NOSFERAPTI!",
  ["_RockTunnel1FSuperNerdBattleText"] = "Baston POKEMON!\nPret, GO!",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "Game\nover!",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "J'veux rentrer a\nma cabane!",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "La nature...\nC'est beau!",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "Oh!\nAu secours!",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "J'aime les petits\nPOKEMON, les gros\11me font peur!",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "J'suis paumee\nmais...\11A l'attaque!",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "Oh!\nPerdu!",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "J'aime pas penser\nfaque je cogne.",
  ["_RockTunnelB1FHiker1BattleText"] = "Hahaha! J'suis\ntrop fort!",
  ["_RockTunnelB1FHiker1EndBattleText"] = "Oups!\nNiveau muscles:\11zero!",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "Les montagnes\nregorgent de\11POKEMON rocheux.",
  ["_RockTunnelB1FHiker2BattleText"] = "Mes POKEMON\nvont te faire\11pleurer!",
  ["_RockTunnelB1FHiker2EndBattleText"] = "Ah!\nJe pleure.",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "Je vas encore\nm'entrainer!",
  ["_RockTunnelB1FHiker3BattleText"] = "Donne-toi a fond,\nmon mignon!",
  ["_RockTunnelB1FHiker3EndBattleText"] = "Mince!\nDetruit!",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Tu me donneras\nton POKEDEX plus\11tard?",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "Tu as-tu un\nPOKEDEX?\11Je le veux!",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "Mautadine!\nJ'suis jaloux!",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Les dresseurs\ncostumes se\11deguisent en\11POKEMON pour\11s'amuser.",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "Connais-tu\nles dresseurs\11costumes?",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "Ben...\nC'est ca.",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Chuis un artiste,\npas un violent.",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Je dessine des\nPOKEMON quand\11chuis tout seul.\11...\11Cool, non?",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "Fouii!\nJe suis creve!",
  ["_RockTunnelPokecenterFisherText"] = "J'ai vendu une\nPEPITE pour\115000¥!",
  ["_RockTunnelPokecenterGentlemanText"] = "Les POKEMON d'un\ncertain element\11sont plus ou\11moins forts que\11d'autres!",
  ["_RockTunnelPokecenterGuyText"] = "On m'a dit qu'il\ny a des SPECTRES\11a VAL-JALBERT!",
  ["_RocketHide3AfterBattleText3"] = "Allez, continue!\nMais il te faut\11la CLE ASC. pour\11l'ascenseur!",
  ["_RocketHideout3BattleText"] = "On nous a\nprevenus de ton\11arrivee!",
  ["_RocketHideout3EndBattleText3"] = "Quoi?\nJ'ai perdu? NON!",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "Tu es-tu pour ou\ncontre la\11TEAM ROCKET?",
  ["_RocketHideoutB1FRocket1BattleText"] = "T'es qui? Comment\nt'es entre icitte?",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "Aie!\nJ'suis battu!",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "Tu vas pas t'en\nsortir de meme,\11mon tabarnak!",
  ["_RocketHideoutB1FRocket2BattleText"] = "Tu as tout casse\nnos plans!!!",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "Enfer!",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "SCOPE SYLPHE?\nC'est quoi donc?",
  ["_RocketHideoutB1FRocket3BattleText"] = "Intrus! \nALERTE! ALERTE!",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "J'ai... \nEchoue!!!",
  ["_RocketHideoutB1FRocket4AfterBattleText"] = "OK, OK, je parle!\nPrends donc\11l'ascenseur et tu\11verras mon chef!",
  ["_RocketHideoutB1FRocket4BattleText"] = "Tiens, pourquoi\nt'es la?",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "Ostie! Tu m'as\neu ben raide!",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "Oups, ce combat a\nouvert la porte!",
  ["_RocketHideoutB1FRocket5BattleText"] = "T'es-tu perdu,\nptit rat de\11tabarnak?",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "Quoi...?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "Le repaire de la\nTEAM ROCKET a 4\11etages. Pourras-\11t'arriver\11jusqu'au chef?",
  ["_RocketHideoutB2FRocketBattleText"] = "Le chef dit qu'on\npeut voir les\11fantomes avec un\11SCOPE SYLPHE!",
  ["_RocketHideoutB2FRocketEndBattleText"] = "STOP!\nJ'me rends!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "Le SCOPE SYLPHE?\nLe bidule que le\11chef a vole?\11Il est la,\11quelque part...",
  ["_RocketHideoutB3FRocket1BattleText"] = "Te mele plus\ndes affaires de\11la TEAM ROCKET!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "Paf!\nJ'suis au tapis!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Tu eleves tes\nPOKEMON trop\11soigneusement.\12Un jeune comme\ntoi peut\11comprendre mes\11plans!\12Tu as gagne cette\nbataille, mais\11pas la guerre...\12On se retrouvera,\net cette fois...",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "Hmm! Tu me\nsurprends. T'es\11dans le genre\11PENIBLE!",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "QUOI!\nCa se peut pas,\11calvaire!",
  ["_RocketHideoutB4FRocket1AfterBattleText"] = "Je comprends pas,\nt'aimes pas la\11TEAM ROCKET?",
  ["_RocketHideoutB4FRocket1BattleText"] = "Je te r'connais!\nT'as gate nos\11plans a MT.MOON,\11tabarnak!",
  ["_RocketHideoutB4FRocket1EndBattleText"] = "Enfer!\nEt encore enfer!",
  ["_RocketHideoutB4FRocket2AfterBattleText"] = "CHEF! Pardon!\nJ'ai echoue...",
  ["_RocketHideoutB4FRocket2BattleText"] = "Tu trouves pas\nque nos plans\11malefiques sont\11super cool?",
  ["_RocketHideoutB4FRocket2EndBattleText"] = "Ayayargh!",
  ["_RocketHideoutB4FRocket3AfterBattleText"] = "Mince! J'ai\nperdu la \11CLE ASC.!",
  ["_RocketHideoutB4FRocket3BattleText"] = "L'ascenseur ne\nmarche pas? Il\11faut la CLE ASC.!",
  ["_RocketHideoutB4FRocket3EndBattleText"] = "Argh!",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "On dirait qu'il\nfaut une cle!",
  ["_RoseText"] = "!",
  ["_Route10CooltrainerF1AfterBattleText"] = "J'ai rencontre\ndes POKEMANIACs\11dans le coin.",
  ["_Route10CooltrainerF1BattleText"] = "Je reviens de\nl'ARENE POKEMON!\11Mais je perds\11tout le temps!",
  ["_Route10CooltrainerF1EndBattleText"] = "Ben,\nvoila! J'ai\11encore perdu!",
  ["_Route10CooltrainerF2AfterBattleText"] = "Ces POKEMON sont\ntrop trapus! Il\11en faudrait des\11roses en forme de\11jolies fleurs!",
  ["_Route10CooltrainerF2BattleText"] = "Cette randonnee\nm'a epuisee!",
  ["_Route10CooltrainerF2EndBattleText"] = "...\nJ'laisse tomber!",
  ["_Route10Hiker1AfterBattleText"] = "Haha-ha-ha!\nNyahahahaha!\11Hohohoho!",
  ["_Route10Hiker1BattleText"] = "Ha-hahah-ah-ha!",
  ["_Route10Hiker1EndBattleText"] = "Ha!\nJe ris pas!\11C'est les nerfs!",
  ["_Route10Hiker2AfterBattleText"] = "J'en ai marre de\nla montagne!",
  ["_Route10Hiker2BattleText"] = "Ah! L'air de la\nmontagne, c'est\11vivifiant!",
  ["_Route10Hiker2EndBattleText"] = "Ben...\nMe voila tout\11vivifie!",
  ["_Route10PowerPlantSignText"] = "CENTRALE",
  ["_Route10RockTunnelSignText"] = "TUNNEL ROCHEUX\nApportez une\11LAMPE POUR VOIR!",
  ["_Route10SuperNerd1AfterBattleText"] = "A ma cabane, j'ai\nplein de POKEMON\11super rares!",
  ["_Route10SuperNerd1BattleText"] = "T'es un dingue\ndes POKEMON?\11Tu veux voir ma\11collec'?",
  ["_Route10SuperNerd1EndBattleText"] = "Nyan!\nMa belle collec'!",
  ["_Route10SuperNerd2AfterBattleText"] = "J'aime pas\nquand tu gagnes!",
  ["_Route10SuperNerd2BattleText"] = "He, le jeune! Tu\nveux voir mes\11POKEMON?",
  ["_Route10SuperNerd2EndBattleText"] = "Yah!\nMes POKEMON!",
  ["_Route11DiglettsCaveSignText"] = "CAVE TAUPIQUEUR",
  ["_Route11Gambler1AfterBattleText"] = "Les POKEMON c'est\nla vie! Et la vie\11c'est le jeu!",
  ["_Route11Gambler1BattleText"] = "Tu veux-tu gagner\nou perdre?",
  ["_Route11Gambler1EndBattleText"] = "OK.\nT'as gagne!",
  ["_Route11Gambler2AfterBattleText"] = "Dans le monde\nmerveilleux des\11POKEMON, y'a\11pas de laches!",
  ["_Route11Gambler2BattleText"] = "J'adore les\ndefis!",
  ["_Route11Gambler2EndBattleText"] = "J'ai eu\nma chance!",
  ["_Route11Gambler3AfterBattleText"] = "Tu as la chance\ndes debutants!",
  ["_Route11Gambler3BattleText"] = "HAHAHA! J'ai\njamais perdu!",
  ["_Route11Gambler3EndBattleText"] = "Heu? Ma\npremiere defaite!",
  ["_Route11Gambler4AfterBattleText"] = "J'suis maudit,\nje crois!",
  ["_Route11Gambler4BattleText"] = "Je ai jamais\ngagne...",
  ["_Route11Gambler4EndBattleText"] = "Je m'y\nattendais...",
  ["_Route11Gate1FGuardText"] = "C'est dur de\ndonner un surnom\11sympa a ses jolis\11POKEMON!\12A VAL-JALBERT, un\nvieil homme\11connait les\11noms de POKEMON.\12Il peut t'aider\na les renommer!",
  ["_Route11Gate2FLeftBinocularsNoSnorlaxText"] = "Tu regardes\ndans les\11jumelles.\12C'est ben beau!\n... \11Bon! On y va?",
  ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "Tu regardes\ndans les\11jumelles.\12Un enorme\nPOKEMON dort\11sur la route!",
  ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "Y'a des objets\ninvisibles sur\11le sol.\12Un CHERCH'OBJET \npourra les\11detecter.\12Mais il faudra\ntout de meme les\11trouver toi-meme!",
  ["_Route11Gate2FRightBinocularsText"] = "Tu regardes\ndans les\11jumelles.\12Y'a qu'un\nseul chemin pour\11aller de BAIE-COMEAU\11a VAL-JALBERT:\11la GROTTE!",
  ["_Route11SuperNerd1AfterBattleText"] = "Il faut\neconomiser\11l'energie!",
  ["_Route11SuperNerd1BattleText"] = "Attention!\nJe pose des\11cables!",
  ["_Route11SuperNerd1EndBattleText"] = "J'me\nsuis pris du jus!",
  ["_Route11SuperNerd2AfterBattleText"] = "Bon, j'ai du\nboulot, moi!",
  ["_Route11SuperNerd2BattleText"] = "Fais gaffe\naux cables!",
  ["_Route11SuperNerd2EndBattleText"] = "Whoa!\nTu fais des\11etincelles!",
  ["_Route11Youngster1AfterBattleText"] = "J'ai fait de mon\nmieux! Pas ma\11faute si j'suis\11nul!",
  ["_Route11Youngster1BattleText"] = "On y va!\nMais triche pas!",
  ["_Route11Youngster1EndBattleText"] = "Rha!\nC'est pas vrai!",
  ["_Route11Youngster2AfterBattleText5"] = "Laisse-moi!",
  ["_Route11Youngster2BattleText"] = "Je suis nouveau,\nmais j'en veux a\11mort!",
  ["_Route11Youngster2EndBattleText"] = "Mes\nPOKEMON sont\11nuls! Beuh...",
  ["_Route11Youngster3AfterBattleText"] = "Y'a un gros\nPOKEMON qui\11vient de la\11montagne.\12Si t'es fort, tu\npeux l'attraper.",
  ["_Route11Youngster3BattleText"] = "Je suis le plus\nfort de ma\11classe!",
  ["_Route11Youngster3EndBattleText"] = "Argh!\nTu veux etre le\11chef de classe?",
  ["_Route11Youngster4AfterBattleText"] = "Faut qu'je chope\ndes plus forts!",
  ["_Route11Youngster4BattleText"] = "Mes POKEMON sont\nprets!",
  ["_Route11Youngster4EndBattleText"] = "Trop,\ntrop trop baleze!",
  ["_Route12CooltrainerMAfterBattleText"] = "J'aurais pu faire\nevoluer mes\11POKEMON avec\11une PIERRE LUNE!",
  ["_Route12CooltrainerMBattleText"] = "As-tu trouve une\nPIERRE LUNE?",
  ["_Route12CooltrainerMEndBattleText"] = "Aie!",
  ["_Route12Fisher1AfterBattleText"] = "Bouge pas! J'ai\nune touche!",
  ["_Route12Fisher1BattleText"] = "Ouais! Ca mord\ndans l'coin!",
  ["_Route12Fisher1EndBattleText"] = "Tsss!\nTrop p'tit!",
  ["_Route12Fisher2AfterBattleText"] = "Pour pecher des\nPOKEMON plus\11gros, il me faut\11une super CANNE!",
  ["_Route12Fisher2BattleText"] = "Patience! Pour\npecher, faut etre\11tranquille!",
  ["_Route12Fisher2EndBattleText"] = "Je l'ai\nlaisse filer!",
  ["_Route12Fisher3AfterBattleText"] = "Tu m'as battu,\nmais...\11j'suis plus fort\11a la peche!",
  ["_Route12Fisher3BattleText"] = "Le PECHEUR FOU\ncontre le KID des\11POKEMON!",
  ["_Route12Fisher3EndBattleText"] = "T'as\ngagne!",
  ["_Route12Fisher4AfterBattleText"] = "C'est bon.\nPerdre me\11fait plus peur.",
  ["_Route12Fisher4BattleText"] = "Bon, j'ai du pain\nsur la planche!",
  ["_Route12Fisher4EndBattleText"] = "C'est\npas facile...",
  ["_Route12Fisher5AfterBattleText"] = "J'ai attrape des\nMAGICARPE, mais\11ils sont nuls!",
  ["_Route12Fisher5BattleText"] = "On sait jamais\nce que l'on peut\11attraper!",
  ["_Route12Fisher5EndBattleText"] = "Hop,\nperdu!",
  ["_Route12Gate1FGuardText"] = "Y'a un beau\npanorama la-haut.",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER} obtient\nCT39!",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "La CT39 s'appelle\nMETEORES.\12Cette attaque est\nben precise.\11Utilise-la pour\11pas rater ton\11coup!",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "Ton inventaire\nest plein!",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "Les cendres de\nmes POKEMON\11sont dans la\11TOUR DE VAL-JALBERT.\12Tiens! Prends\ncette CT. Je en\11ai plus besoin...",
  ["_Route12Gate2FLeftBinocularsText"] = "Tu regardes\ndans les\11jumelles.\12Tu vois un\npecheur!",
  ["_Route12Gate2FRightBinocularsText"] = "Tu regardes\ndans les\11jumelles.\12Tu vois la\nTOUR DE VAL-JALBERT!",
  ["_Route12SignText"] = "ROUTE 12 \nVAL-JALBERT - Nord",
  ["_Route12SnorlaxCalmedDownText"] = "RONFLEX, une\nfois calme, s'en\11retourne vers la\11montagne!",
  ["_Route12SnorlaxText"] = "Un POKEMON en-\ndormi bloque le\11chemin!",
  ["_Route12SnorlaxWokeUpText"] = "RONFLEX se\nreveille!\12Il est de mauvais\npoil! Il t'\11attaque!",
  ["_Route12SportFishingSignText"] = "ZONE DE PECHE",
  ["_Route12SuperNerdAfterBattleText"] = "L'eau conduit\nl'electricite.\11Planque tous\11tes POKEMON\11aquatiques!",
  ["_Route12SuperNerdBattleText"] = "L'electricite est\nma specialite!",
  ["_Route12SuperNerdEndBattleText"] = "Court-jus!",
  ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "Mon frere,\nj'suis le maitre\11pecheur!\12Moi, dans la vie,\nj'suis pecheur!\12T'aimes la peche,\nmon frere?",
  ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "\12La peche c'est\ncomme la vie!\12Quand ca mord,\nca va! \11Quand ca mord\11pas, ca va pas!",
  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "Ha ben non!\12J'avais un cadeau\npour toi, mais\11t'as plus de\11place!",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "Trop cool!\nJ't'aime bien!\12Prends cette\ncanne a peche,\11mon frere!\12{PLAYER} obtient:\n{RAM:wStringBuffer}!",
  ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "Oh... Je suis\nben decu...",
  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "Salut,\n{PLAYER}!\12Avec cette MEGA\nCANNE, tu vas\11vider les oceans\11de tous les\11POKEMON.\12Peche, peche,\net peche encore! ",
  ["_Route13Beauty1AfterBattleText"] = "C'est quoi le\nplus fort,\11un POKEMON\11fille ou gars?",
  ["_Route13Beauty1BattleText"] = "Tu veux-tu te\nmesurer a moi?",
  ["_Route13Beauty1EndBattleText"] = "Oh!\nPetit voyou!",
  ["_Route13Beauty2AfterBattleText"] = "J'y connais rien\naux POKEMON!\11Je les trouve\11juste cool!",
  ["_Route13Beauty2BattleText"] = "Et si on faisait\npoke-poke tous\11les deux?",
  ["_Route13Beauty2EndBattleText"] = "Fini?\nDeja?",
  ["_Route13BikerAfterBattleText"] = "Du balai!",
  ["_Route13BikerBattleText"] = "Qu'est-ce que tu\nregardes, toi!?",
  ["_Route13BikerEndBattleText"] = "Zipp!\nJ'ai derape!",
  ["_Route13CooltrainerF1AfterBattleText"] = "Je veux etre un\nbon dresseur. Je\11travaille dur.",
  ["_Route13CooltrainerF1BattleText"] = "Pas mal pour une\nfille, hein?",
  ["_Route13CooltrainerF1EndBattleText"] = "Oh!\nPerdu!",
  ["_Route13CooltrainerF2AfterBattleText"] = "Tu as gagne ces\nBADGES chez les\11CHAMPIONS!",
  ["_Route13CooltrainerF2BattleText"] = "Woaa! Tes BADGES\nsont trop cool!",
  ["_Route13CooltrainerF2EndBattleText"] = "...\nJ'en ai assez!",
  ["_Route13CooltrainerF3AfterBattleText"] = "Tu dois faire\ncombattre tes\11POKEMON pour les\11entrainer!",
  ["_Route13CooltrainerF3BattleText"] = "Mes POKEMON tout\nmignons veulent\11te connaitre.",
  ["_Route13CooltrainerF3EndBattleText"] = "Wow!\nJ'suis morte!",
  ["_Route13CooltrainerF4AfterBattleText"] = "Le CARBONE a\naugmente la\11vitesse de mon\11POKEMON.",
  ["_Route13CooltrainerF4BattleText"] = "J'ai trouve du\nCARBONE dans une\11grotte, une fois!",
  ["_Route13CooltrainerF4EndBattleText"] = "J'ai\ntout rate!",
  ["_Route13CooltrainerM1AfterBattleText"] = "Mes POKEMON ont\nl'air content,\11meme s'ils ont\11perdu.",
  ["_Route13CooltrainerM1BattleText"] = "Mes POKEMON\noiseaux cherchent\11la baston!",
  ["_Route13CooltrainerM1EndBattleText"] = "Tu\nm'as vole dans\11les plumes!",
  ["_Route13CooltrainerM2AfterBattleText"] = "J'ai perdu. Je\nrentre chez moi.",
  ["_Route13CooltrainerM2BattleText"] = "Le vent souffle\npar la. Cool!",
  ["_Route13CooltrainerM2EndBattleText"] = "Le\nvent a tourne!",
  ["_Route13CooltrainerM3AfterBattleText"] = "J'aimerais voler\ncomme ROUCOOL\11ou ROUCOUPS...",
  ["_Route13CooltrainerM3BattleText"] = "J'aime bien mes\nPOKEMON oiseaux!\11...Ouais... \11C'est vrai.",
  ["_Route13CooltrainerM3EndBattleText"] = "Oh!\nMa cage!",
  ["_Route13SignText"] = "ROUTE 13\nPONT DU SILENCE\11au Nord",
  ["_Route13TrainerTips1Text"] = "ASTUCE\12Regardez a\ngauche!",
  ["_Route13TrainerTips2Text"] = "ASTUCE\12Utilisez SELECT\npour organiser\11votre inventaire!",
  ["_Route14Biker1AfterBattleText"] = "Quoi? Quoi?\nTu veux quoi?",
  ["_Route14Biker1BattleText"] = "Allez, viens!\nTu vas voir la\11tete de tes\11POKEMON!",
  ["_Route14Biker1EndBattleText"] = "Arrg!\nT'as fait une\11tete au carre a\11mes POKEMON!",
  ["_Route14Biker2AfterBattleText"] = "Elever des\nPOKEMON, c'est\11crevant!",
  ["_Route14Biker2BattleText"] = "Parfait! Tu vas\ndeguster!",
  ["_Route14Biker2EndBattleText"] = "Oh!\nPlein ma face!",
  ["_Route14Biker3AfterBattleText"] = "Cool, tes\nPOKEMON sont\11super balezes!\12La force, c'est\nbien!",
  ["_Route14Biker3BattleText"] = "On s'en va,\ny'a plus de\11place!",
  ["_Route14Biker3EndBattleText"] = "Balaye!",
  ["_Route14Biker4AfterBattleText"] = "Tu sais que sans\ntes POKEMON, je\11te pulverise!",
  ["_Route14Biker4BattleText"] = "Combat POKEMON?\nTremble, minus!",
  ["_Route14Biker4EndBattleText"] = "Vroom!\nDans l'vent!",
  ["_Route14CooltrainerM1AfterBattleText"] = "Tu as-tu des CS?\nLes POKEMON ne\11peuvent pas les\11oublier.",
  ["_Route14CooltrainerM1BattleText"] = "Utilise des CT\npour apprendre\11de bonnes\11attaques a tes\11POKEMON!",
  ["_Route14CooltrainerM1EndBattleText"] = "T'es pas pire,\nfeliciations!",
  ["_Route14CooltrainerM2AfterBattleText"] = "Il leur faut de\nbonnes attaques.",
  ["_Route14CooltrainerM2BattleText"] = "Mes POKEMON\noiseaux veulent\11se battre.",
  ["_Route14CooltrainerM2EndBattleText"] = "...\nY veulent plus!",
  ["_Route14CooltrainerM3AfterBattleText"] = "Apprends a tes\nPOKEMON des\11attaques de leur\11element pour les\11rendre plus\11puissants.",
  ["_Route14CooltrainerM3BattleText"] = "On vend des CT a\nLAVAL!\11Mais, seuls\11quelques elus ont\11des CS!",
  ["_Route14CooltrainerM3EndBattleText"] = "Ah!\nFiasco complet!",
  ["_Route14CooltrainerM4AfterBattleText"] = "J'adore les\nPOKEMON oiseaux!",
  ["_Route14CooltrainerM4BattleText"] = "As-t'appris a\ntes POKEMON\11oiseaux a voler?",
  ["_Route14CooltrainerM4EndBattleText"] = "Ah!\nChute libre!",
  ["_Route14CooltrainerM5AfterBattleText"] = "Les 3 POKEMON\nlegendaires sont\11des oiseaux\11de proie.",
  ["_Route14CooltrainerM5BattleText"] = "As-t'entendu\nparler des\11POKEMON\11legendaires?",
  ["_Route14CooltrainerM5EndBattleText"] = "Ah?\nJ'ai perdu?",
  ["_Route14CooltrainerM6AfterBattleText"] = "Perdre ou gagner,\nc'est pas le plus\11important!",
  ["_Route14CooltrainerM6BattleText"] = "J'suis pas au\njeu! Mais bon...",
  ["_Route14CooltrainerM6EndBattleText"] = "Ben,\nt'as gagne, non?",
  ["_Route14SignText"] = "ROUTE 14\nHEMMINGFORD\11a l'Ouest",
  ["_Route15Beauty1AfterBattleText"] = "Je te pardonne!\nT'es trop mignon!",
  ["_Route15Beauty1BattleText"] = "Oh! T'es un p'tit\njeunot!",
  ["_Route15Beauty1EndBattleText"] = "T'etais\nmignon, pourtant!",
  ["_Route15Beauty2AfterBattleText"] = "Je rentre chez\nmoi pour etre\11avec mes POKEMON!",
  ["_Route15Beauty2BattleText"] = "J'ai des POKEMON\nparce que je vis\11toute seule!",
  ["_Route15Beauty2EndBattleText"] = "He, mais,\nj'suis gentille!",
  ["_Route15Biker1AfterBattleText"] = "On vit qu'une\nfois! C'est pour\11ca que je suis\11mechant, nyark!",
  ["_Route15Biker1BattleText"] = "He, l'mouflet!\nRegarde ca!",
  ["_Route15Biker1EndBattleText"] = "Bon,\nben, t'as vu!",
  ["_Route15Biker2AfterBattleText"] = "Heu...\nJe plaisantais!",
  ["_Route15Biker2BattleText"] = "La bourse\nou la vie!",
  ["_Route15Biker2EndBattleText"] = "Tiens,\nvoila ma bourse!",
  ["_Route15CooltrainerF1AfterBattleText"] = "Tu peux pas\nrenommer un\11POKEMON echange.\12Seul son dresseur\npeut le faire.",
  ["_Route15CooltrainerF1BattleText"] = "Je vas tester\nles POKEMON que\11j'ai echange!",
  ["_Route15CooltrainerF1EndBattleText"] = "Oh!\nPerdu!",
  ["_Route15CooltrainerF2AfterBattleText"] = "Les MOTARDS me\nfont peur, ils\11sont si mechants!",
  ["_Route15CooltrainerF2BattleText"] = "T'as l'air niais,\nje dois pouvoir\11te battre!",
  ["_Route15CooltrainerF2EndBattleText"] = "!!!\nPas trop niais!",
  ["_Route15CooltrainerF3AfterBattleText"] = "J'echange des\nPOKEMON avec\11mes amis!",
  ["_Route15CooltrainerF3BattleText"] = "Quoi? Echanger\ndes POKEMON\11c'est cool?",
  ["_Route15CooltrainerF3EndBattleText"] = "He!\nJe parlais\11d'echanges, pas\11de bastons!",
