  ["_Route22Rival1DefeatedText"] = "Haha!\nTu as eu une\11chance de\11minable, minable!",
  ["_Route22Rival1VictoryText"] = "{RIVAL}: Quoi?\nPourquoi j'ai 2\11POKEMON?\12Tu devrais\11aussi en choper\11d'autres,\11minable!",
  ["_Route22Rival2DefeatedText"] = "Quoi!?\12Je pensais a\nautre chose!",
  ["_Route22Rival2VictoryText"] = "{RIVAL}: Hahaha!\n{PLAYER}! T'es\11pour vrai nul! Un\11enorme minable,\11pas bon du tout!\12Allez, retourne\nt'entrainer!",
  ["_Route22RivalAfterBattleText1"] = "Y parait qu'il y\na des dresseurs\11balezes dans la\11LIGUE POKEMON!\12Je dois trouver\nun moyen de les\11battre!\12Tu devrais t'y\nmettre aussi,\11minable!",
  ["_Route22RivalAfterBattleText2"] = "Tu m'as amuse\nun p'tit peu! J'suis\11chaud pour la\11LIGUE POKEMON!\12{PLAYER}, t'es\npour vrai un\11minable!\12Mais je crois que\ntu commences a le\11savoir, minable!",
  ["_Route22RivalBeforeBattleText1"] = "{RIVAL}: He!\n{PLAYER}!\12Tu vas a la\nLIGUE POKEMON?\12Laisse tomber!\nT'es bien trop\11minable. En plus\11il te faut des\11BADGES!\12Les gardes ne\nlaisseront pas\11passer un minable\11comme toi!\12Enfin, si tu veux\nje suis pret a\11exploser tes\11POKEMON!",
  ["_Route22RivalBeforeBattleText2"] = "{RIVAL}: Tiens?\n{PLAYER}! Quelle\11bonne surprise,\11t'es la aussi?!\12Faque de meme on\nva a la LIGUE?\12Tu as tous les\nBADGES aussi?\11C'est bien!\12Eh ben...j'vais\nt'casser en deux\11minab'.\11Ta maman te\11reconnaitra qu'a\11la couleur de ton\11p'tit cartable!\12Allez, viens\nprendre ta baffe,\11minable!",
  ["_Route23GoRightAheadText"] = "\12OK! Tu peux\npasser!",
  ["_Route23OhThatIsTheBadgeText"] = "On passe que\nsur presentation\11d'un...\11{RAM:wNameBuffer}!\12Oh! Mais c'est le\n{RAM:wNameBuffer}!",
  ["_Route23VictoryRoadGateSignText"] = "ROUTE VICTOIRE\n- LIGUE POKEMON",
  ["_Route23YouDontHaveTheBadgeYetText"] = "On passe que\nsur presentation\11d'un...\11{RAM:wNameBuffer}!\12Tu as pas le\n{RAM:wNameBuffer}!\12Il te le faut\npour acceder a la\11LIGUE POKEMON!",
  ["_Route24CooltrainerF1AfterBattleText"] = "J'ai participe,\net j'ai perdu!",
  ["_Route24CooltrainerF1BattleText"] = "Je suis la 4eme!\nT'en veux encore?",
