  ["_Route24CooltrainerF2BattleText"] = "Je suis la 2eme!\nCa rigole plus!",
  ["_Route24CooltrainerF2EndBattleText"] = "Ben...\nTu m'as battue?",
  ["_Route24CooltrainerM1DefeatedText"] = "Arrgh!\nTu es ben fort!",
  ["_Route24CooltrainerM1JoinTeamRocketText"] = "Veux-tu rejoindre\nles rangs de la\11TEAM ROCKET?\12Nous sommes des\ndresseurs de\11POKEMON ben\11mechants!\12Ca t'interesse?\12T'es sur?\12Allez, viens!\12Bon, je t'ai dit\nde venir avec\11nous!\12Je vois...\12Je vas me\nmontrer plus\11persuasif!",
