  ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "Tu pourrais vite\ndevenir un chef\11au sein de la\11TEAM ROCKET!",
  ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "\12Tu as gagne un\nfabuleux prix!",
