  ["_Route24CooltrainerM2BattleText"] = "Je t'ai vu!",
  ["_Route24CooltrainerM2EndBattleText"] = "Oh!\nJ'ai vu ma\11defaite!",
  ["_Route24CooltrainerM3AfterBattleText"] = "Pas de regrets,\nj'ai fait de mon\11mieux!",
  ["_Route24CooltrainerM3BattleText"] = "OK! J'suis le 5!\nJ'vais te broyer!",
  ["_Route24CooltrainerM3EndBattleText"] = "Ah!\nPuree!",
  ["_Route24Youngster1AfterBattleText"] = "J'ai fait de mon\nmieux!",
  ["_Route24Youngster1BattleText"] = "Je suis le 3eme!\nC'est pas gagne!",
  ["_Route24Youngster1EndBattleText"] = "Oh!\nTu m'as ecrase!",
  ["_Route24Youngster2AfterBattleText"] = "J'ai fait de mon\nmieux. Si si!\11C'est vrai!",
  ["_Route24Youngster2BattleText"] = "Voici le PONT\nPEPITE!\115 dresseurs\11defendent ce\11pont! Bats-nous\11et tu seras\11super content!\12Tu crois pouvoir\ny arriver?",
  ["_Route24Youngster2EndBattleText"] = "Haha!\nBien joue!",
  ["_Route25BillSignText"] = "VILLA\nTI-GUY habite icitte!",
  ["_Route25CooltrainerF1AfterBattleText"] = "Mon chum a moi, il\nest ben fort!",
  ["_Route25CooltrainerF1BattleText"] = "Mon p'tit chum,\nc'est le plus\11beau de tous!\11J'ai le plus beau\11de tous les\11copains du monde!",
  ["_Route25CooltrainerF1EndBattleText"] = "Hmm...\nJ'pensais a mon\11mec!",
  ["_Route25CooltrainerF2AfterBattleText"] = "Tu viens du MONT\nSELENITE? Tu as-tu\11un MELOFEE?",
  ["_Route25CooltrainerF2BattleText"] = "Mon chum a des\nPOKEMON trognons!\11Je suis jalouse!",
  ["_Route25CooltrainerF2EndBattleText"] = "J'suis\npas jalouse,\11j'suis nulle!",
  ["_Route25CooltrainerMAfterBattleText"] = "Ma blonde va\nm'encourager.",
  ["_Route25CooltrainerMBattleText"] = "J'suis cool.\nEt j'ai une\11blonde aussi!",
  ["_Route25CooltrainerMEndBattleText"] = "Mautadine!\nMautadine, mautadine et mautadine!",
  ["_Route25Hiker1AfterBattleText"] = "Aaaaaaargh!\nJe me suis fait\11mordre par un\11NOSFERAPTI.",
  ["_Route25Hiker1BattleText"] = "J'arrive du MONT\nSELENITE, et je\11suis pret!",
  ["_Route25Hiker1EndBattleText"] = "Pfiou!\nT'es un baleze!",
  ["_Route25Hiker2AfterBattleText"] = "Le collectionneur\na plein de\11POKEMON rares.",
  ["_Route25Hiker2BattleText"] = "Je cherche le\ncollectionneur de\11POKEMON!",
  ["_Route25Hiker2EndBattleText"] = "Heu!\nJ'suis eu.",
  ["_Route25Hiker3AfterBattleText"] = "La route, en bas,\nest un raccourci\11vers BAIE-COMEAU.",
  ["_Route25Hiker3BattleText"] = "Tu vas-tu voir TI-GUY?\nOk, mais d'abord,\11BASTOONNN!",
  ["_Route25Hiker3EndBattleText"] = "Hmm.\nTu te bats bien.",
  ["_Route25Youngster1AfterBattleText"] = "Chaque POKEMON a\nses faiblesses.\11Il vaut mieux te\11faire une equipe\11avec des POKEMON\11varies.",
  ["_Route25Youngster1BattleText"] = "Les dresseurs\nviennent icitte pour\11s'entrainer!",
  ["_Route25Youngster1EndBattleText"] = "Tu es\nbon gagnant.",
  ["_Route25Youngster2AfterBattleText"] = "Sur LE TRANS-SAINT-LAURENT,\nj'ai vu des\11dresseurs du\11monde entier.",
  ["_Route25Youngster2BattleText"] = "Je suis alle a\nune super fete.\11C'etait sur\11LE TRANS-SAINT-LAURENT, a\11RIMOUSKI!",
  ["_Route25Youngster2EndBattleText"] = "Yaha!\nJ'suis pas fou!",
  ["_Route25Youngster3AfterBattleText"] = "Si ton POKEMON\nest devenu fou ou\11s'est endormi,\11rappelle-le!",
  ["_Route25Youngster3BattleText"] = "Y'a un dresseur\nde trop icitte!",
  ["_Route25Youngster3EndBattleText"] = "Ben...\nJ'suis d'trop!",
  ["_Route2DiglettsCaveSignText"] = "CAVE TAUPIQUEUR",
  ["_Route2GateOaksAideFlashExplanationText"] = "La CS du FLASH\npeut eclairer les\11endroits sombres.",
  ["_Route2GateYoungsterText"] = "Si un POKEMON a\nappris le FLASH,\11tu pourras tra-\11verser la GROTTE.",
  ["_Route2SignText"] = "ROUTE 2\nMONT-TREMBLANT -\11THETFORD MINES",
  ["_Route2TradeHouseScientistText"] = "Un POKEMON K.O.\npeut se battre\11mais il peut\11encore utiliser\11des techniques\11comme la COUPE!",
  ["_Route3CooltrainerF1AfterBattleText"] = "Baisse les yeux\nsi tu veux eviter\11la baston!",
  ["_Route3CooltrainerF1BattleText"] = "Tu veux-tu ma\nphoto?",
  ["_Route3CooltrainerF1EndBattleText"] = "Tiens,\nc'est ma photo!",
  ["_Route3CooltrainerF2AfterBattleText"] = "Evite les regards\nsi tu veux\11pas combattre!",
  ["_Route3CooltrainerF2BattleText"] = "Dis donc beau\ntenebreux...\11Tu veux qu'on\11s'boxe?",
  ["_Route3CooltrainerF2EndBattleText"] = "Hmmm...\nSois gentil!",
  ["_Route3CooltrainerF3AfterBattleText"] = "La ROUTE 4\nest au pied du\11MONT SELENITE.",
  ["_Route3CooltrainerF3BattleText"] = "He! Tu m'as\ntouchee la?",
  ["_Route3CooltrainerF3EndBattleText"] = "OK!",
  ["_Route3SignText"] = "ROUTE 3 vers le\nMONT SELENITE",
  ["_Route3Text1"] = "Pfou...Je vas\nfaire une halte.\11Moouarf...\12Ce tunnel\nde BAIE-COMEAU est\11epuisant!",
  ["_Route3Youngster1AfterBattleText"] = "Y'a ben gros\nde POKEMON\11differents dans\11la foret!",
  ["_Route3Youngster1BattleText"] = "He! On s'est deja\nvu dans la FORET TREMBLANT!",
  ["_Route3Youngster1EndBattleText"] = "Ben,\ntu m'as encore\11battu!",
  ["_Route3Youngster2AfterBattleText"] = "Pour ranger tes\nPOKEMON,\11utilise un PC.\11Chaque boite\11contient\1120 POKEMON!",
  ["_Route3Youngster2BattleText"] = "Yahaa! J'adore\nles shorts! Viens\11t'battre!",
  ["_Route3Youngster2EndBattleText"] = "Nyahaa,\ntu m'as taille\11un short!",
  ["_Route3Youngster3AfterBattleText"] = "Quand l'une des\nboites de ton PC\11est pleine,\11active une autre\11boite!",
  ["_Route3Youngster3BattleText"] = "T'es un dresseur?\nA l'attaque!",
  ["_Route3Youngster3EndBattleText"] = "Avec\nd'autres POKEMON\11j'aurais gagne!",
  ["_Route3Youngster4AfterBattleText"] = "Je porte toujours\ndes shorts, meme\11en hiver!",
  ["_Route3Youngster4BattleText"] = "He! T'as pas de\nshort! T'es nul!",
  ["_Route3Youngster4EndBattleText"] = "Perdu!\nPerdu, et perdu!",
  ["_Route3Youngster5AfterBattleText"] = "Les POKEMON\ndomptes sont plus\11forts que\11les sauvages!",
  ["_Route3Youngster5BattleText"] = "Fais gaffe a mes\nnouveaux POKEMON!",
  ["_Route3Youngster5EndBattleText"] = "Ben,\ny m'en faut\11des nouveaux!",
  ["_Route4CooltrainerF1Text"] = "Ha! J'ai trebuche\nsur un POKEMON de\11pierre: RACAILLOU!",
  ["_Route4CooltrainerF2AfterBattleText"] = "Je crois qu'il\ny a plus de\11champignons dans\11le coin.\12Je les ai tous\nramasses.",
  ["_Route4CooltrainerF2BattleText"] = "Je viens chercher\nmon POKEMON\11champignon!",
  ["_Route4CooltrainerF2EndBattleText"] = "Oh!\nMon POKEMON!",
  ["_Route4MtMoonSignText"] = "MONT SELENITE\nEntree du tunnel",
  ["_Route4SignText"] = "ROUTE 4\nMONT SELENITE -\11BAIE-COMEAU",
  ["_Route5UndergroundPathSignText"] = "SOUTERRAIN\nBAIE-COMEAU -\11RIMOUSKI",
  ["_Route6CooltrainerAfterBattleText"] = "Soupirs...\nGros soupirs...",
  ["_Route6CooltrainerF1BattleText"] = "Heu, c'est une\nconversation\11privee, DEGAGE!",
  ["_Route6CooltrainerF1EndBattleText"] = "Non!\nPas bon perdre!",
  ["_Route6CooltrainerF2AfterBattleText"] = "Je veux etre\nforte! Comme toi!\11C'est quoi ton\11secret?",
  ["_Route6CooltrainerF2BattleText"] = "Qui ca? Moi?\nOk. Attaque!",
  ["_Route6CooltrainerF2EndBattleText"] = "Ho.\nPas glop!",
  ["_Route6CooltrainerM1BattleText"] = "Qui est la?\nArrete de nous\11espionner!",
  ["_Route6CooltrainerM1EndBattleText"] = "...\nJ'suis nul!",
  ["_Route6CooltrainerM2AfterBattleText"] = "Il me faut plus\nde POKEMON\11pour me proteger.",
  ["_Route6CooltrainerM2BattleText"] = "Hein? Tu veux-tu\nme causer?",
  ["_Route6CooltrainerM2EndBattleText"] = "...\nJ'ai rien fait!",
  ["_Route6UndergroundPathSignText"] = "SOUTERRAIN\nBAIE-COMEAU -\11RIMOUSKI",
  ["_Route6Youngster1AfterBattleText"] = "Les insectes\nj'aime ca, je\11retourne dans la\11FORET TREMBLANT.",
  ["_Route6Youngster1BattleText"] = "C'est plein\nd'insectes, icitte.",
  ["_Route6Youngster1EndBattleText"] = "Non!\nC'est une blague!",
  ["_Route6Youngster2AfterBattleText"] = "Mes POKEMON sont\nnuls ou je suis\11ben mauvais?",
  ["_Route6Youngster2BattleText"] = "J't'ai jamais\nvu dans le coin!\11T'es puissant?",
  ["_Route6Youngster2EndBattleText"] = "Whaa!\nTrop puissant!",
  ["_Route7UndergroundPathSignText"] = "SOUTERRAIN\nLAVAL -\11VAL-JALBERT",
  ["_Route8CooltrainerF1AfterBattleText"] = "Quand un POKEMON\ngrandit, il est\11gros et laid.\11Je les prefere\11tout petits!",
  ["_Route8CooltrainerF1BattleText"] = "Moi, j'aime les\nNIDORAN! Yaha!",
  ["_Route8CooltrainerF1EndBattleText"] = "Hein?",
  ["_Route8CooltrainerF2AfterBattleText"] = "Je trouve que\nROUCOOL et\11RATTATA sont trop\11cool!",
  ["_Route8CooltrainerF2BattleText"] = "MIAOUSS est si\nmignon. Miaou!",
  ["_Route8CooltrainerF2EndBattleText"] = "Miaou!",
  ["_Route8CooltrainerF3AfterBattleText"] = "Le gardien de la\nporte de MONTREAL\11nous laissera\11pas passer!",
  ["_Route8CooltrainerF3BattleText"] = "Je sais, on a\nl'air niaiseux\11debout!",
  ["_Route8CooltrainerF3EndBattleText"] = "Ben...\nC'est malin ca!",
  ["_Route8CooltrainerF4AfterBattleText"] = "Il parait que\nMELOFEE peut\11evoluer grace a \11une PIERRE LUNE.",
  ["_Route8CooltrainerF4BattleText"] = "Qu'il est mimi,\ngentil et trognon\11ce POKEMON!\11Il est a qui?\11Hein? A qui?",
  ["_Route8CooltrainerF4EndBattleText"] = "Arrete!\12T'es pas gentil\navec MELOFEE!",
  ["_Route8Gambler1AfterBattleText"] = "Dame chance est\npas avec moi!",
  ["_Route8Gambler1BattleText"] = "Le sort en est\njete!",
  ["_Route8Gambler1EndBattleText"] = "Haaa!\nLe hasard...",
  ["_Route8Gambler2AfterBattleText"] = "Le jeu et les\nPOKEMON, c'est\11comme les\11cacahuetes.\11Tu commences et\11tu peux plus\11t'arreter! Fou!",
  ["_Route8Gambler2BattleText"] = "Je suis un\njoueur errant!",
  ["_Route8Gambler2EndBattleText"] = "J'ai\nrate le jackpot!",
  ["_Route8SuperNerd1AfterBattleText"] = "Je suis meilleur\na l'ecole!",
  ["_Route8SuperNerd1BattleText"] = "T'es un bon avec\ntes POKEMON.\11Mais les maths,\11tu connais?",
  ["_Route8SuperNerd1EndBattleText"] = "Ouch!\n2 plus 2... 7?",
  ["_Route8SuperNerd2AfterBattleText"] = "D'abord TADMORV\net apres...\11Et puis...",
  ["_Route8SuperNerd2BattleText"] = "Il te faut une\nbonne strategie!",
  ["_Route8SuperNerd2EndBattleText"] = "He!\nPas logique!",
  ["_Route8SuperNerd3AfterBattleText"] = "On est bloque\nicitte, aux portes\11de MONTREAL.",
  ["_Route8SuperNerd3BattleText"] = "L'ecole c'est\ncool, les POKEMON\11c'est mieux!",
  ["_Route8SuperNerd3EndBattleText"] = "Ben...\nL'ecole c'est\11plus facile!",
  ["_Route8UndergroundSignText"] = "SOUTERRAIN\nLAVAL -\11VAL-JALBERT",
  ["_Route9CooltrainerF1AfterBattleText"] = "Il te faudra de\nla lumiere dans\11ce sombre tunnel.",
  ["_Route9CooltrainerF1BattleText"] = "T'as des POKEMON\navec toi!\11En garde!",
  ["_Route9CooltrainerF1EndBattleText"] = "Ah!\nBien defendu!",
  ["_Route9CooltrainerF2AfterBattleText"] = "T'as l'air doue!\nBonne chance,\11gars!",
  ["_Route9CooltrainerF2BattleText"] = "Traite-moi avec\nrespect!",
  ["_Route9CooltrainerF2EndBattleText"] = "...\nJe merite que\11ton dedain!",
  ["_Route9CooltrainerM1AfterBattleText"] = "Passe ton chemin!",
  ["_Route9CooltrainerM1BattleText"] = "Mais qui voila,\nles bras charges\11de POKEMON?",
  ["_Route9CooltrainerM1EndBattleText"] = "Paf!\nJ'suis fini!",
  ["_Route9CooltrainerM2AfterBattleText"] = "Tu vas-tu dans la\nGROTTE, toi\11aussi?",
  ["_Route9CooltrainerM2BattleText"] = "Je passe par la\nGROTTE pour voir\11VAL-JALBERT!",
  ["_Route9CooltrainerM2EndBattleText"] = "...\nJ'suis pas bon!",
  ["_Route9Hiker1AfterBattleText"] = "T'es un\ncourageux toi!",
  ["_Route9Hiker1BattleText"] = "Bwahaha!\nAllez... \11Viens manger ta\11patee...",
  ["_Route9Hiker1EndBattleText"] = "Ha!\nViens, viens!\12Heu, j'ai plus\nde POKEMON!",
  ["_Route9Hiker2AfterBattleText"] = "Les jeunes, c'est\npas assez fort!",
  ["_Route9Hiker2BattleText"] = "Hahaha!\nT'es un p'tit\11dur, toi!",
  ["_Route9Hiker2EndBattleText"] = "Dur,\nben dur!",
  ["_Route9Hiker3AfterBattleText"] = "Hahahaha!\nQuand j'perds,\11j'me marre!",
  ["_Route9Hiker3BattleText"] = "Viens t'battre,\ngalopin!",
  ["_Route9Hiker3EndBattleText"] = "Ha!\nTu m'as bien eu!",
  ["_Route9SignText"] = "ROUTE 9\nBAIE-COMEAU-\11GROTTE",
  ["_Route9Youngster1AfterBattleText"] = "Il me faut autre\nchose que des\11insectes pour\11etre plus fort...",
  ["_Route9Youngster1BattleText"] = "Mes cocons de\nPOKEMON me\11prennent ben gros\11de temps!",
  ["_Route9Youngster1EndBattleText"] = "Nyargh?\12Quelle perte de\ntemps!",
  ["_Route9Youngster2AfterBattleText"] = "T'aimes pas les\ninsectes POKEMON?\11T'es infect!",
  ["_Route9Youngster2BattleText"] = "Capote-cafards,\nen avant!",
  ["_Route9Youngster2EndBattleText"] = "Capote-\ncafards! Houhou!\11Reveille-toi!",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "Tu as fait mal\na mes POKEMON!\12Il faut que\ntu les soignes\11dans un\11CENTRE POKEMON!!!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "J'ai deniche\nces POKEMON\11un p'tit peu partout\11dans le monde!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "Quoi!\nUn tour du monde\11pour ce resultat!\11C'est nul!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "Il faut etre\ngentil avec ses\11POKEMON!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "Je voyage\ntoujours en\11solitaire!\12Mes POKEMON\nsont mes amis!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "Non!\nMes p'tits amis!",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "J'aimerais etre\nseul! Va-t'en!",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "Toi, jeune sot! Tu\noses entrer icitte!?",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "Huf!\nTu es mal eleve!!",
  ["_SSAnne1FRoomsGentleman3Text"] = "Pst! Je suis de\nla SQ!\12Je suis sur la\ntrace de la\11TEAM ROCKET!\11Chut!",
  ["_SSAnne1FRoomsGirl1Text"] = "Serveur,\napporte-moi du\11pouding chomeur!",
  ["_SSAnne1FRoomsGirl2Text"] = "Nous parcourons\nles mers du\11monde entier!",
  ["_SSAnne1FRoomsLittleGirlText"] = "Je voyage\ntoujours avec\11GRODOUDOU!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "Ha! Une croisiere!\nC'est tellement\11romantique!",
  ["_SSAnne1FRoomsWigglytuffText"] = "GRODOUDOU: Gro!\nDouuuuuuu!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Soyons amis,\nOK?\12On pourra faque\nechanger nos\11POKEMON!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "J'aime les\nPOKEMON! Et toi?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "Woo!\nT'es cool, toi!",
  ["_SSAnne1FSailorText"] = "Les passagers\nsont capotes\11en tabarnak!\12Y vont surement\nte provoquer en\11duel!",
  ["_SSAnne1FWaiterText"] = "Bonjour! Je suis\nle serveur de ce\11bateau!\12Je me ferai une\njoie de te\11servir!\12Ha! L'air du\ngrand large!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Il y\na le maitre de la\11technique COUPE\11a bord.\12Mais ce est\nqu'un vieil homme\11malade et senile!\12La technique\nCOUPE est ben\11utile!\12Tu devrais le\nrencontrer!\11Salut! Minable!",
  ["_SSAnne2FRivalDefeatedText"] = "Mouaff!\12Au moins, tu\nt'occupes de tes\11POKEMON!",
  ["_SSAnne2FRivalText"] = "{RIVAL}: Salut!\n{PLAYER}!\12Toi! Icitte!\nSans blague!\12{PLAYER}, as-tu\npour vrai ete\11invite?\12Ou en es-t'avec\nton POKEDEX?\12Moi, j'ai deja\nattrape 40\11POKEMON! Minable!\12Y'en a partout!\12Tu as qu'a ramper\ndans les hautes\11herbes!",
  ["_SSAnne2FRivalVictoryText"] = "{PLAYER}! Tu as-tu\nle mal de mer?\12Tu devrais te\nmettre au frais!\11Minable!",
  ["_SSAnne2FRoomsBeautyText"] = "C'est assez\nfrequent d'avoir\11le mal de mer!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "Le CAPITAINE\navait l'air tout\11palot!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "Woah! Tes POKEMON\nsont super forts!\11Je les adore!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Je t'ai pas vu\na la fete.",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "Relax!\nT'enerve pas!!!",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "Une fete?\12Elle doit etre\nfinie asteur.",
  ["_SSAnne2FRoomsFisherBattleText"] = "He! Regarde ce\nque j'ai peche!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "OK!\nJ'suis fait!!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "Hmm! Y'a 15\nans, j'aurais\11gagne...",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "Les duels contre\nles jeunes me\11maintiennent en\11forme!",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "Woah!\nHa! Je me sens\11en pleine forme!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "Je prefere les\nPOKEMON rares\11et costauds!",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "Que veux-tu?\nUn POKEMON\11costaud ou rare?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "Bravo!\nTu es ben fort!",
  ["_SSAnne2FRoomsGentleman3Text"] = "Dans tous mes\nvoyages, je ai\11jamais vu un\11POKEMON dormir\11autant!\12Il etait un\npeu de meme...",
  ["_SSAnne2FRoomsGentleman4Text"] = "Oui! J'ai vu des\ngens transporter\11des POKEMON par-\11dela les eaux!",
  ["_SSAnne2FRoomsGentleman5Text"] = "As-tu deja vu\nle PARC SAFARI\11a HEMMINGFORD?\12On y trouve plein\nde POKEMON rares!",
  ["_SSAnne2FRoomsGrampsText"] = "Les POKEMON\npeuvent couper des\11petits buissons\11avec la technique\11COUPE.",
  ["_SSAnne2FRoomsLittleBoyText"] = "Mon Popa et moi,\non pense que le\11PARC SAFARI\11il est capotant!",
  ["_SSAnne2FWaiterText"] = "Ce luxueux bateau\naccueille tous\11les dresseurs!\12Dans chaque port\nnous organisons\11une fete pour\11les dresseurs!",
  ["_SSAnne3FSailorText"] = "Notre CAPITAINE\nest un maitre\11d'armes!\12Il enseigne\na ses POKEMON\11la technique\11COUPE!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "J'allais faire de\ntoi mon\11assistant!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "Salut etranger!\nParlons un p'tit peu!\12Tous mes POKEMON\nsont aquatiques!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "Mautadine!\nCelui-la s'est\11echappe!",
  ["_SSAnneB1FRoomsMachokeText"] = "MACHOPEUR: Chop!\nChop! Chop!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "Faque, mousse, tu\nveux devenir\11un marin?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "Tu sais ce que\nl'on raconte sur\11les marins et\11les duels!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "Ouaip!\nBeau combat!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "As-tu rencontre le\nMaitre Pecheur a\11RIMOUSKI?",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "Ma reputation de\nmarin est en jeu!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "Ha!\nJe sombre!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "Tous nos POKEMON\nviennent des\11hautes mers!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "Nous, les marins,\non a aussi des\11POKEMON!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "OK!\nT'es pas nul!",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "Les POKEMON d'eau\nvivent dans les\11grands fonds!\12J'ai besoin d'une\nCANNE!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "J'aime les p'tits\ngars joyeux\11comme toi!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "Hein!\nJ'ai perdu? Argh!",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "Souvent, quelques\nmeduses sont\11entrainees dans\11le sillage\11du bateau...",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "Si tu perds, on\nte balance aux\11requins!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "Hein?\nBattu par toi?",
  ["_SSAnneB1FRoomsSuperNerdText"] = "Mon POKEMON,\nMACHOPEUR, est\11super fort!!!\12Sa FORCE lui\npermet de bouger\11les rochers!",
  ["_SSAnneBowCooltrainerMText"] = "Gueuh! J'suis\nmalaaaaade...\12Je vas bientot\nvom... (beurp)",
  ["_SSAnneBowSailor1Text"] = "Nyah! Briquer le\npont c'est un\11job epuisant!",
  ["_SSAnneBowSailor2AfterBattleText"] = "Tu sais-tu combien\ny'a de POKEMON\11differents? Hein,\11tu l'sais, hein?",
  ["_SSAnneBowSailor2BattleText"] = "He! Chum!\12Tu danses?\nUn tango?",
  ["_SSAnneBowSailor2EndBattleText"] = "...\nT'es bon!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Mon Popa, y dit\nqu'y a 100 POKEMON\11differents. J'suis\11sur qu'y en a\11plus...",
  ["_SSAnneBowSailor3BattleText"] = "Hoho! Faque, on\na le mal de mer? ",
  ["_SSAnneBowSailor3EndBattleText"] = "Oh!\nBeau combat!",
  ["_SSAnneBowSuperNerdText"] = "La fete est\nfinie! Nous\12allons bientot\nlever l'ancre!",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "Ha mautadine! Tu as\nplus de place\11pour cet objet!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "CAPITAINE: Merci\nmoussaillon!\11Ca va ben gros\11mieux...\12Mille sabords!\nTu veux voir\11la technique\11COUPE?\12Je pourrais te la\nmontrer, mais\11j'suis malade.\12Je sais!\nPrends ca!\12C'est la technique\nCOUPE.\11Enseigne-la a\11tes POKEMON!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "CAPITAINE: Haaaa!\12Asteur que\nje suis gueri, on\11va lever l'ancre!",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER} obtient\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "CAPITAINE: Blorf.\nJ'suis pas bien.\11Beurp...\12{PLAYER} masse\nle dos du\11CAPITAINE!\12Scratch...\nScratch...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "Comment guerir\nle mal de mer...\11Le CAPITAINE lit\11ce manuel!",
  ["_SSAnneCaptainsRoomTrashText"] = "Quoi?!?\nIl a mange ca???",
  ["_SSAnneKitchenCook1Text"] = "He! Le mouflet,\ny'en a qui bossent\12dur icitte!\nFaque degage!",
  ["_SSAnneKitchenCook2Text"] = "J'ai vu une Ball\nbizarre dans la\11poubelle...",
  ["_SSAnneKitchenCook3Text"] = "J'ai trop de\nboulot! J'en ai\11des vertiges!",
  ["_SSAnneKitchenCook4Text"] = "Pourquoi?\nPourquoi moi?\12J'suis tout\nl'temps d'corvee\11d'patates...",
  ["_SSAnneKitchenCook5Text"] = "Tu connais\nRONFLEX?\12Il passe ses\njournees a manger\11et a coller\11des buches!",
  ["_SSAnneKitchenCook6Text"] = "Sniff... \n...sniff...\12J'epluche\ndes oignons...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "Hm, hm! Je suis\nle chef cuistot!\12Voila le menu:",
  ["_SSTicketNoRoomText"] = "Ton inventaire\nest plein, mon chum!",
  ["_SSTicketReceivedText"] = "{PLAYER} obtient:\n{RAM:wStringBuffer}!",
  ["_SafariZoneAngryText"] = "Le {RAM:wEnemyMonNick}\nsauvage se fache!",
  ["_SafariZoneCenterRestHouseGirlText"] = "JULIA: Ou est\nNICO, mon petit\11ami?",
