  ["_SafariZoneCenterRestHouseSignText"] = "ABRI",
  ["_SafariZoneCenterTrainerTipsSignText"] = "ASTUCE\12Appuyez sur START\npour consulter la\11montre!",
  ["_SafariZoneEastRestHouseRockerText"] = "J'ai trouve un\nLEVEINARD!\12J'ai bien fait\nde chercher\11pendant 4 heures!",
  ["_SafariZoneEastRestHouseScientistText"] = "T'en as capture\ncombien? Moi\11j'suis naze!",
