  ["_SafariZoneEastTrainerTipsText"] = "ASTUCE\12Le temps s'ecoule\nen fonction des\11pas!",
  ["_SafariZoneEatingText"] = "Le {RAM:wEnemyMonNick}\nsauvage mange!",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "\12J'utiliserai le\nHAUT-PARLEUR\11lorsque ton temps\11ou tes SAFARI\11BALL seront\11epuises!",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "Bonne chasse?\nAllez...\11A plus tard!",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "Bonne chance!",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "On part deja?",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "Hop hop hop!\nPas d'sous!",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "Ben correct!\nA plus tard!",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Donne-moi donc\ntes SAFARI BALL\11neuves.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "Bienvenue au\nPARC SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "Ca fera 500¥\nsiouplait!\12Seul un certain\ntype de POKE BALL\11est utilise icitte.\12{PLAYER} recoit\n30 SAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "Pour juste 500¥,\ntu peux attraper\11autant de POKEMON\11qu'il te plaira\11dans le parc!\12Qu'en dis-tu?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "C'est...c'est la\npremiere fois?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "Le PARC SAFARI a\n4 zones.\12Tu y trouveras\ndes POKEMON\11differents.\11Utilise tes\11SAFARI BALL pour\11les capturer!\12Le Safari sera\ntermine lorsque\11t'auras epuise\11tes SAFARI BALL!\12Avant de partir,\nouvre donc une\11nouvelle boite de\11POKEMON pour\11avoir plus de\11place!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "Oh! T'es un\nhabitue!",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "Mon EVOLI s'est\ntransforme en un\11PYROLI!\12Mais celui d'un\nami s'est change\11en AQUALI!\11Bah pourquoi?",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Un recoin du PARC\nSAFARI renferme\11un prix!",
  ["_SafariZoneNorthRestHouseScientistText"] = "Tu peux garder\ntous les objets\11trouves dans le\11coin.\12Mais perds pas\nde temps a tous\11les essayer!",
  ["_SafariZoneNorthRestHouseSignText"] = "ABRI",
  ["_SafariZoneNorthSignText"] = "PARC 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "ASTUCE\12La Cabane Secrete\nest tout droit!",
  ["_SafariZoneNorthTrainerTips2Text"] = "ASTUCE\12Les POKEMON se\ncachent dans les\11hautes herbes!\12Explorez ces\nzones pour les\11faire sortir.",
  ["_SafariZoneNorthTrainerTips3Text"] = "ASTUCE\12Decouvrez la\nCABANE SECRETE et\11gagnez une CS!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "CS03 est SURF!\12Un POKEMON pourra\nte faire naviguer\11sur les flots!\12En plus, cette CS\npeut s'utiliser a\11l'infini!\12T'en as de la\nchance, mon p'tit\11bouchon!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "Heu... Tu as\npas assez de\11place!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER} obtient:\n{RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "Ah! Quand meme!\12Tu es le premier\na decouvrir la\11CABANE SECRETE!\12J'avais peur que\npersonne gagne\11notre prix.\12Felicitations!\nTu as gagne!",
  ["_SafariZoneWestFindWardensTeethSignText"] = "AVIS\12Veuillez trouver\nla DENT D'OR du\11GARDIEN. Explorez\11les environs.\12Recompense\nassuree! \11Contactez le\11GARDIEN.",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Un APPAT peut\nfaciliter tes\11captures.",
  ["_SafariZoneWestRestHouseScientistText"] = "Une PIERRE peut\nfaire fuir les\11POKEMON mais ils\11seront plus fa-\11ciles a capturer.",
  ["_SafariZoneWestRestHouseSignText"] = "ABRI",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "J'ai cherche\ntoute la sainte\11journee mais j'ai\11rien capture.",
  ["_SafariZoneWestSignText"] = "PARC 3\nEST: PARC CENTRAL",
  ["_SafariZoneWestTrainerTipsText"] = "ASTUCE\12Grand concours\norganise:\12Cherchez la\nCABANE SECRETE!",
  ["_SaffronCityFightingDojoSignText"] = "DOJO",
  ["_SaffronCityGentlemanText"] = "Je suis venu icitte\nen volant sur mon\11ROUCARNAGE apres\11avoir lu les\11nouvelles de la\11SYLPHE.\12Tout est deja\nfini? J'ai tout\11loupe?",
  ["_SaffronCityGymSignText"] = "MONTREAL\nARENE POKEMON\11CHAMPION: MORGANE\12Maitresse des\nforces psychiques",
  ["_SaffronCityMrPsychicsHouseSignText"] = "MAISON DE\nMR. PSY",
  ["_SaffronCityPidgeotText"] = "ROUCARNAGE: Rou!",
  ["_SaffronCityPokecenterGuyText1"] = "Pourquoi le\nCONSEIL des 4 ne\11vient pas casser\11les dents de la\11TEAM ROCKET?",
  ["_SaffronCityPokecenterGuyText2"] = "La TEAM ROCKET\nest partie! Faque\11c'est la fete!\11Youpi!",
  ["_SaffronCityRockerText"] = "J'ai vu le CHEF\nde la TEAM ROCKET\11s'enfuir de la\11SYLPHE.",
  ["_SaffronCityRocket1Text"] = "Kesstu veux?\nDu vent!",
  ["_SaffronCityRocket2Text"] = "Eul' CHEF dit\nqu'il controlera\11c'te ville!",
  ["_SaffronCityRocket3Text"] = "Bouge eud' la!",
  ["_SaffronCityRocket4Text"] = "MONTREAL est a\nla TEAM ROCKET!",
  ["_SaffronCityRocket5Text"] = "Etre mechant,\nc'est mieux que\11d'se laver les\11dents!",
  ["_SaffronCityRocket6Text"] = "Tu m'as marche\nsul'pied, non?",
  ["_SaffronCityRocket7Text"] = "Avec la SYLPHE\ndans not' poche,\11les POKEMON du\11monde entier\11seront notre\11bizness!",
  ["_SaffronCityRocket8Text"] = "Moi....\nChuis un garde.\12Les nabots tout\nlouches, moi,\11j'les laisse pas\11passer!",
  ["_SaffronCityRocket9Text"] = "...\n(pionce)...\12Ha! Il dort!",
  ["_SaffronCityScientistText"] = "T'as tout casse\nla ROCKET tout\11seul? Dingue!",
  ["_SaffronCitySignText"] = "MONTREAL\nBelle et doree,\11le commerce est\11icitte prospere",
  ["_SaffronCitySilphCoLatestProductSignText"] = "Dernier produit\nde la SYLPHE!\12La date de sortie\nest encore a\11determiner...",
  ["_SaffronCitySilphCoSignText"] = "SYLPHE INC.\nSIEGE SOCIAL",
  ["_SaffronCitySilphWorkerFText"] = "Tout le monde va\nvite revenir a\11MONTREAL.",
  ["_SaffronCitySilphWorkerMText"] = "Ouais! La TEAM\nest partie!\11On peut enfin\11respirer!",
  ["_SaffronCityTrainerTips1Text"] = "ASTUCE\12TOTAL SOIN fait\ndisparaitre tous\11les changements\11de statut comme\11le sommeil ou le\11gel.\12C'est un p'tit peu cher\nmais ca vaut le\11coup.",
  ["_SaffronCityTrainerTips2Text"] = "ASTUCE\12La SUPER BALL\naugmente les\11chances de\11capture.\12Faites un essai\nsur des POKEMON\11ben vivaces.",
  ["_SaffronGateGuardGeeImThirstyText"] = "Je suis de garde\nmais je creve de\11soif!\12La route est\nfermee. Degage.",
  ["_SaffronGateGuardImParchedText"] = "C'que j'ai soif!\nC'est dingue!\11...\11Hein? Tu m'donnes\11a boire? Dingue!\11Merci, p'tit!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "Salut! Merci\npour le verre!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "\12...\nGlou gloup...\11...\11Glourp...\11Si tu veux aller\11a MONTREAL...\11...glouarps...\11Tu peux passer...\11T'inquiete pas\11pour les autres\11gardes!",
  ["_SaffronGymChanneler1AfterBattleText"] = "Dans une baston,\nce qui est\11important, c'est\11la volonte de\11gagner!\12Si tu veux gagner\nface a MORGANE,\11concentre-toi sur\11la victoire!",
  ["_SaffronGymChanneler1BattleText"] = "MORGANE est une\npetite parvenue!\11Mais je l'aime\11bien!",
  ["_SaffronGymChanneler1EndBattleText"] = "Rhha!\nJ'suis nulle!",
  ["_SaffronGymChanneler2AfterBattleText"] = "Les attaques de\nmes POKEMON ne\11sont pas assez\11fortes!",
  ["_SaffronGymChanneler2BattleText"] = "L'aura du maitre\ndeteint sur ses\11POKEMON.\12Tes POKEMON sont\nforts, non?",
  ["_SaffronGymChanneler2EndBattleText"] = "Argh!\nJe l'savais!",
  ["_SaffronGymChanneler3AfterBattleText"] = "J'avais prevu ce\nqui s'est passe.",
  ["_SaffronGymChanneler3BattleText"] = "Toi...Moi...\nNos POKEMON...\11FIGHT!",
  ["_SaffronGymChanneler3EndBattleText"] = "Puff!\nJ'ai perdu!",
  ["_SaffronGymGuideBeatSabrinaText"] = "Pouvoirs psy?\nHmmm...\12Si j'en avais, je\ngagnerais!",
  ["_SaffronGymGuideChampInMakingText"] = "Salut! Graine de\nchampion!\12Les POKEMON de\nMORGANE utilisent\11les pouvoirs de\11l'esprit!\12Les POKEMON du\ntype combat sont\11desavantages!\12Ils deviennent\ndingues avant de\11pouvoir porter\11un coup!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "Avec le BADGE\nMARAIS, les\11POKEMON de niveau\1170 t'obeiront!\12Les POKEMON plus\npuissants seront\11incontrolables\11lors des combats!\12Fais en sorte que\ntes POKEMON ne\11depassent pas\11cette limite!\12Tiens! Prends ca\naussi!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "Tout le monde est\nun p'tit peu medium!\11Il faut juste\11travailler ses\11dons!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "Ha!\nJe suis surprise!\11Tu as gagne.\12C'est vrai, je\nai pas fait de\11mon mieux! Tu\11merites ta\11victoire!\12Tu gagnes le\nBADGE MARAIS!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER} obtient:\nCT46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "Ton inventaire\nest plein!",
  ["_SaffronGymSabrinaText"] = "J'avais predit\nton arrivee!\12J'ai des pouvoirs\npsychiques depuis\11l'enfance.\12J'ai appris a\nplier des\11cuilleres par la\11force de mon\11esprit. C'est pas\11super utile, mais\11ca en jette!\12Je aime pas les\ncombats, mais si\11t'insistes, je\11vais te montrer\11mes pouvoirs!",
  ["_SaffronGymYoungster1AfterBattleText"] = "Les POKEMON psy\ncraignent les\11insectes et les\11fantomes!",
  ["_SaffronGymYoungster1BattleText"] = "Nos pouvoirs\noccultes te font\11peur?",
  ["_SaffronGymYoungster1EndBattleText"] = "Nyan!\nT'as pas l'air\11effraye!",
  ["_SaffronGymYoungster2AfterBattleText"] = "MORGANE a\npulverise le\11grand MAITRE de\11KARATE!",
  ["_SaffronGymYoungster2BattleText"] = "La puissance sans\nmaitrise est\11rien!",
  ["_SaffronGymYoungster2EndBattleText"] = "Huh!\nJ'appelle pas ca\11rien!",
  ["_SaffronGymYoungster3AfterBattleText"] = "Il y avait deux\nARENES POKEMON a\11MONTREAL.\12Le DOJO KARATE a\nperdu son titre\11le jour ou nous\11l'avons\11pulverise!",
  ["_SaffronGymYoungster3BattleText"] = "MORGANE est jeune\nmais elle est\11aussi notre\11CHAMPION!\12Tu vas en baver\ncomme un russe\11avant de\11l'atteindre!",
  ["_SaffronGymYoungster3EndBattleText"] = "Oups!\nJ'ai rien capte!",
  ["_SaffronGymYoungster4AfterBattleText"] = "J'ai lu dans ton\nesprit! C'est pas\11ben correct range\11la d'dans!",
  ["_SaffronGymYoungster4BattleText"] = "Le CHAMPION de\nl'ARENE POKEMON\11de MONTREAL est\11une medium psy!\12Tu veux voir\nMORGANE, hein?\11Je lis tes\11pensees... \11Vilain crapaud!",
  ["_SaffronGymYoungster4EndBattleText"] = "Arrrgh!",
  ["_SaffronMartCooltrainerFText"] = "Le RAPPEL est\ncouteux mais il\11permet de\11reanimer un\11POKEMON K.O.!",
  ["_SaffronMartSuperNerdText"] = "Le MAX REPOUSSE\nfonctionne plus\11longtemps que le\11SUPEREPOUSSE!",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "Merci pour cette\nbelle lettre, a\11bientot!\12He! R'garde pas\nc'que j'ecris!\11J'suis amoureuse!",
  ["_SaffronPidgeyHousePaperText"] = "J'ai recu comme\nrecompense un\11PP PLUS.\12Je l'ai utilise\npour augmenter\11les PP des\11attaques de mes\11POKEMON!",
  ["_SaffronPidgeyHousePidgeyText"] = "ROUCOOL: Rourou!",
  ["_SaffronPidgeyHouseYoungsterText"] = "La COPIEUSE est\nmignonne! Je vas\11lui offrir une\11POKEPOUPEE!",
  ["_SaffronPokecenterBeautyText"] = "La puissance des\nPOKEMON est\11differente selon\11leur espece.",
  ["_SaffronPokecenterGentlemanText"] = "La SYLPHE INC.\nest ben connue.\11C'est pourquoi la\11TEAM ROCKET l'a\11investie!",
  ["_SandshrewDexEntry"] = "Il s'enterre dans\nles regions\narides et\12desertiques. Il\nemerge seulement\npour chasser.<DEXEND>",
  ["_SandslashDexEntry"] = "Il se roule en\nboule herissee de\npiques s'il est\12menace. Il peut\nainsi s'enfuir ou\nattaquer.<DEXEND>",
  ["_SaveOptionText"] = "L'option SAUVER\nest sur l'ecran\11du MENU.",
  ["_SavingEnergyText"] = "{USER}\nse concentre!",
  ["_ScaredText"] = "{RAM:wBattleMonNick} a peur\nde bouger!",
  ["_ScytherDexEntry"] = "Rapide et agile\ncomme un ninja,\nil se deplace si\12vite qu'il cree\nl'illusion d'etre\nen groupe.<DEXEND>",
  ["_SeadraDexEntry"] = "Il peut nager a\nl'envers en\nagitant ses\12petites nageoires\npectorales.<DEXEND>",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "Yahoo!",
  ["_SeafoamIslandsB4FBouldersSignText"] = "Les rochers\npeuvent changer\11le niveau de\11l'eau!",
  ["_SeafoamIslandsB4FDangerSignText"] = "DANGER!\nRapides!",
  ["_SeakingDexEntry"] = "Pendant la\nsaison des\namours, on peut\12le voir nager\ndans les rivieres\net les lacs.<DEXEND>",
  ["_SeelDexEntry"] = "La corne sur son\nfront est ben\nresistante. Elle\12lui sert a\npercer des\nblocs de glace.<DEXEND>",
  ["_SentToBoxText"] = "Plus de place\npour un POKEMON!\11{RAM:wBoxMonNicks} est\11transfere a la\11BOITE {RAM:wStringBuffer} du PC!",
  ["_ShallWeHealYourPokemonText"] = "Tu veux-tu\nsoigner tes\11POKEMON?",
  ["_ShellderDexEntry"] = "Protege par une\ncarapace ben\nresistante, il\12est vulnerable\nquand celle-ci\ns'ouvre.<DEXEND>",
  ["_ShroudedInMistText"] = "{USER}\ns'estompe dans la\11brume!",
  ["_SilphCo10FGiovanniILostAgainText"] = "Arrgh!!\nEncore perdu!?",
  ["_SilphCo10FPorygonText"] = "Des POKEMON sur\nle moniteur!",
  ["_SilphCo10FRocketAfterBattleText"] = "Bien joue, mais\nla salle du\11conseil est\11au-dessus!",
  ["_SilphCo10FRocketBattleText"] = "Bienvenue au\n9eme etage!\11J'adore les\11visites !",
  ["_SilphCo10FRocketEndBattleText"] = "Aie!\nBobo!",
  ["_SilphCo10FScientistAfterBattleText"] = "T'as gagne!\nT'es content?",
  ["_SilphCo10FScientistBattleText"] = "Asteur...\nFini de jouer!",
  ["_SilphCo10FScientistEndBattleText"] = "Oh!\nGame Over!",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "Waaaaa!\nMamaaaan!",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "Repete a\npersonne que j'ai\11pleure!",
  ["_SilphCo11FBeautyText"] = "SECRETAIRE: Merci\nde nous avoir\11tous sauves!\12Ton courage est\nexemplaire.",
  ["_SilphCo11FGiovanniText"] = "Ah, {PLAYER}!\nUne fois encore\11nos routes se\11croisent...\12Le PDG et moi-\nmeme discutons\11d'une affaire\11ben importante.\12Viens pas t'meler\nde tout ca, mon\11bonhomme...\12Degage ou...\nDeguste!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "NOoOoOoOon!\nNotre invasion de\11la SYLPHE est\11fichue!\12Mais la TEAM\nROCKET est\11invincible!\12{PLAYER}! Oublie\njamais que tous\11les POKEMON sont\11pour la TEAM\11ROCKET!\12Je pars, mais...\nMa vengeance te\11fera bobo!",
  ["_SilphCo11FRocket1AfterBattleText"] = "Tu cherches\nl'embrouille?",
  ["_SilphCo11FRocket1BattleText"] = "Hola toi!\nPas bouger!",
  ["_SilphCo11FRocket1EndBattleText"] = "Non...\nPitie!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Prends garde...\nLes POKEMON de\11mon chef sont\11terribles!",
  ["_SilphCo11FRocket2BattleText"] = "Halte! As-t'un\nrendez-vous en\11regle avec mon\11chef?",
  ["_SilphCo11FRocket2EndBattleText"] = "Gaah!\nCasse la tete!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PDG: Tu peux\nacheter ceci\11nulle part!\12C'est notre\nprototype secret:\11la MASTER BALL!\12Elle pourra\nattraper n'importe\11quel POKEMON!\12Faque utilise-la\navec sagesse.",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "Tu as pas assez\nde place sur toi.",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER} obtient:\n{RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PDG: Merci d'avoir\nsauve la SYLPHE!\12Je oublierai\njamais ton\11haut fait!\12Tu merites une\nrecompense!\12L'cash est\npas un probleme\11pour moi!\12Tiens... Je crois\nque ceci te fera\11plaisir!",
  ["_SilphCo1FLinkReceptionistText"] = "Bienvenue!\12Le PRESIDENT est\ndans la salle du\11conseil, au 10eme\11etage!",
  ["_SilphCo2FRocket1AfterBattleText"] = "Les dalles en\nforme de diamant\11sont des\11teleporteurs!\12C'est de la super\ntechnologie!",
  ["_SilphCo2FRocket1BattleText"] = "He! Pas de\nmioches icitte!",
  ["_SilphCo2FRocket1EndBattleText"] = "La vache!\nBaleze le p'tit!",
  ["_SilphCo2FRocket2AfterBattleText"] = "La SYLPHE INC. et\nla TEAM ROCKET\11vont fusionner!",
  ["_SilphCo2FRocket2BattleText"] = "He, p'tite tete!\nQu'est-ce tu\11fais la?",
  ["_SilphCo2FRocket2EndBattleText"] = "Oups,\nj'ai perdu!",
  ["_SilphCo2FScientist1AfterBattleText"] = "Je travaille pour\nla SYLPHE INC. et\11la TEAM ROCKET!",
  ["_SilphCo2FScientist1BattleText"] = "A l'aide! Je suis\nun employe de la\11SYLPHE INC.!",
  ["_SilphCo2FScientist1EndBattleText"] = "???\nComment t'as su\11que j'etais de\11La TEAM ROCKET?",
  ["_SilphCo2FScientist2AfterBattleText"] = "Trouve la\nsortie du\11Labyrinthe!",
  ["_SilphCo2FScientist2BattleText"] = "Hophop! Zone\nprivee, degage!",
  ["_SilphCo2FScientist2EndBattleText"] = "OK.\nJ'suis battu!",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER} obtient\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "Voici la CT36:\nDESTRUCTION!\12C'est une attaque\nben puissante!\11Mais elle mettra\11K.O. le POKEMON\11qui l'utilise!!!",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "Plus de place\npour cet objet!!!",
  ["_SilphCo3FRocketAfterBattleText"] = "Tu peux ouvrir\nles portes avec\11la CARTE MAGN.!",
  ["_SilphCo3FRocketBattleText"] = "T'occupe pas de\nnos affaires!",
  ["_SilphCo3FRocketEndBattleText"] = "Yaha!\nT'es trop fort!",
  ["_SilphCo3FScientistAfterBattleText"] = "Hmmm...\12J'aide la TEAM\nROCKET et ils\11me laissent\11etudier les\11POKEMON!",
  ["_SilphCo3FScientistBattleText"] = "Je prefere\nla TEAM ROCKET a\11la SYLPHE INC.!!!",
  ["_SilphCo3FScientistEndBattleText"] = "!!!\nTu m'as eu!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Je travaille pour\nla SYLPHE INC..\11Que faire d'autre?",
  ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}! Toi et\ntes POKEMON,\11vous nous avez\11sauves!",
  ["_SilphCo4FRocket1AfterBattleText"] = "Le BOSS attend\nce moment depuis\11longtemps!",
  ["_SilphCo4FRocket1BattleText"] = "La TEAM ROCKET\ncontrole\11la SYLPHE INC.!!!",
  ["_SilphCo4FRocket1EndBattleText"] = "Arrgh!",
  ["_SilphCo4FRocket2AfterBattleText"] = "Je dois prevenir\nle chef au 10eme\11etage!",
  ["_SilphCo4FRocket2BattleText"] = "CONTACT!\nINTRUS DETECTE!",
  ["_SilphCo4FRocket2EndBattleText"] = "Mais?\nQui es-tu?",
  ["_SilphCo4FScientistAfterBattleText"] = "Les portes sont\nsecurisees! Il\11te faut une\11CARTE MAGN. pour\11les ouvrir!",
  ["_SilphCo4FScientistBattleText"] = "Mes POKEMON sont\nmes soldats!!!",
  ["_SilphCo4FScientistEndBattleText"] = "NAN!\nMes POKEMON!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "Chut! Tu vois\npas que je\11suis cache?",
  ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "La TEAM ROCKET\nest partie? COOL!",
  ["_SilphCo5FPokemonReport1Text"] = "C'est un RAPPORT\nsur les POKEMON!\12PORYGON:\nPOKEMON virtuel,\11cree par le\11LABO POKEMON!",
  ["_SilphCo5FPokemonReport2Text"] = "C'est un RAPPORT\nsur les POKEMON!\12Il existe 160\nattaques pour\11les POKEMON!",
  ["_SilphCo5FPokemonReport3Text"] = "C'est un RAPPORT\nsur les POKEMON!\124 POKEMON\nevoluent que\11s'ils sont\11echanges!",
  ["_SilphCo5FRockerAfterBattleText"] = "Tu es qu'au\n4eme etage!\11Le chef est\11encore loin!",
  ["_SilphCo5FRockerBattleText"] = "Mais? C'est pas\npour les p'tits\11morveux icitte!",
  ["_SilphCo5FRockerEndBattleText"] = "Non!\nMon Dieu!",
  ["_SilphCo5FRocket1AfterBattleText"] = "C'est pas ben\nmalin d'provoquer\11la TEAM ROCKET!",
  ["_SilphCo5FRocket1BattleText"] = "Il parait qu'un\ngosse se balade\11dans le coin...",
  ["_SilphCo5FRocket1EndBattleText"] = "Vlan!",
  ["_SilphCo5FRocket2AfterBattleText"] = "Ce qui me\nrappelle...\12SMOGO evolue en\nSMOGOGO!",
  ["_SilphCo5FRocket2BattleText"] = "Cause mieux\na la grande\11TEAM ROCKET!",
  ["_SilphCo5FRocket2EndBattleText"] = "Kheu...\nKheu...",
  ["_SilphCo5FScientistAfterBattleText"] = "Nous recherchons\nla POKE BALL\11ultime, capable\11de tout attraper!",
  ["_SilphCo5FScientistBattleText"] = "Nous etudions la\ntechnologie des\11POKE BALL!",
  ["_SilphCo5FScientistEndBattleText"] = "PAF!\nJ'suis mauvais!",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "La TEAM ROCKET\ncherche un\11intrus. C'est\11toi, non?",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "La TEAM ROCKET\nest battue! Tu es\11notre heros!",
  ["_SilphCo6FRocket1AfterBattleText"] = "Pas grave!\nMes freres me\11vengeront!",
  ["_SilphCo6FRocket1BattleText"] = "Je suis l'un des\n4 freres ROCKET!",
  ["_SilphCo6FRocket1EndBattleText"] = "Oups...\nDans le vent!",
  ["_SilphCo6FRocket2AfterBattleText"] = "Si t'es gentil,\nt'es pas mechant!",
  ["_SilphCo6FRocket2BattleText"] = "Tu oses defier\nla TEAM ROCKET?",
  ["_SilphCo6FRocket2EndBattleText"] = "Rebelle...\nVilain!",
  ["_SilphCo6FScientistAfterBattleText"] = "TRIFOUILLI?\nC'est au beau\11milieu de nulle\11part!",
  ["_SilphCo6FScientistBattleText"] = "Quel porc ce\nPDG!\12Il a decide de me\nmuter au siege de\11TRIFOUILLI!",
  ["_SilphCo6FScientistEndBattleText"] = "Mautadine!",
  ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "Il me fait pitie,\nfaque... Je vas\11l'epouser!",
  ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "Regarde-moi ca!\nQuel froussard!",
  ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "La TEAM ROCKET\nveut dominer le\11monde avec des\11POKEMON!",
  ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "Tu as fait fuir\nla TEAM ROCKET!",
  ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "Envoye, hop! \nA la job!",
  ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "La Team ROCKET\na investi tout\11l'immeuble!",
  ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "Les produits\nPOKEMON de la\11SYLPHE devaient\11les interesser.",
  ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "Travaille donc\npour la SYLPHE\11une fois plus\11grand!",
  ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "Pitie, pitie...\nAidez-moi!",
  ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "On va s'marier!\nHaha!",
  ["_SilphCo7FRivalDefeatedText"] = "Oh non!\nTu es donc pret\11pour le chef de\11la TEAM ROCKET!",
  ["_SilphCo7FRivalGoodLuckToYouText"] = "OK, {PLAYER}!\12Je decampe!\12Grace a mon joli\nPOKEDEX, je\11decouvre qui est\11fort et quelles\11sont toutes les\11evolutions!\12Je vas a la\nLIGUE POKEMON\11pour detroner le\11CONSEIL des 4!\12Je serai bientot\nle dresseur le\11plus puissant du\11monde!\12Bonne chance,\n{PLAYER}!\11Tu en auras\11besoin, minable!",
  ["_SilphCo7FRivalText"] = "{RIVAL}: C'que tu\nes lent, {PLAYER}!",
  ["_SilphCo7FRivalVictoryText"] = "{RIVAL}: Quelle\nperte de temps!\12Va jouer dans ton\nbac a sable!",
  ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}: Hahaha!\nJ'etais sur que\11tu passerais par\11la!\12La TEAM ROCKET\nt'a pose des\11problemes?\11C'est de valeur!\12Je t'ai vu a\nMONTREAL. Es-tu\11toujours aussi\11nul?",
  ["_SilphCo7FRocket1AfterBattleText"] = "Tu pourras\ntrouver mon chef\11en te baladant!",
  ["_SilphCo7FRocket1BattleText"] = "Heu?\nAlerte! Alerte!",
  ["_SilphCo7FRocket1EndBattleText"] = "Oups.\nPerdu! Perdu!",
  ["_SilphCo7FRocket2AfterBattleText"] = "Pas grave.\nMes freres se\11chargeront de\11toi, mon petit!",
  ["_SilphCo7FRocket2BattleText"] = "Je suis l'un des\n4 freres ROCKET!",
  ["_SilphCo7FRocket2EndBattleText"] = "Yaaah!\nFreres! A l'aide!",
  ["_SilphCo7FRocket3AfterBattleText"] = "Rentre chez toi!\nMon chef est sans\11pitie!",
  ["_SilphCo7FRocket3BattleText"] = "Un jeune intrus?\nMais! C'est toi!",
  ["_SilphCo7FRocket3EndBattleText"] = "OK.\nJ'ai perdu.",
  ["_SilphCo7FScientistAfterBattleText"] = "Bien que jeune,\ntu te debrouilles\11pas trop mal!",
  ["_SilphCo7FScientistBattleText"] = "Nyah ha ha!\12Tu me prends pour\nun employe de la\11SYLPHE?",
  ["_SilphCo7FScientistEndBattleText"] = "...\nFichu!",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "Oh! Tu es pas\nun ROCKET! Es-tu\11la pour nous\11sauver? Merci!\12Prends donc ce\njoli POKEMON en\11cadeau.",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "Le chef de la\nTEAM ROCKET est\11dans la salle du\11conseil. Le PDG\11va-t-il bien?",
  ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "C'est un LOKHLASS.\nIl est ben\11intelligent.\12Nous le gardions\ndans le labo,\11mais il sera\11mieux avec toi!\12Tu seras un bon\ndresseur pour\11LOKHLASS!\12Etant bon nageur,\nil pourra meme te\11porter!",
  ["_SilphCo7FSilphWorkerM1SavedText"] = "De l'aide! Enfin!\nMerci!",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "La TEAM ROCKET\nvoulait s'emparer\11de la MASTER BALL\11pouvant attraper\11n'importe quel\11POKEMON!",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Le projet MASTER\nBALL fut annule\11a cause de la\11TEAM ROCKET.",
  ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "Grace au ciel la\nTEAM ROCKET ne\11put investir la\11SYLPHE ou voler\11nos POKEMON!",
  ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "Woah! Tu as-tu battu\nla TEAM ROCKET\11tout seul?",
  ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "He toi! C'est\ndangereux par\11icitte! Tu es-tu venu\11me sauver?\11Impossible!",
  ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "Enfin libre!\nMerci merci!",
  ["_SilphCo8FRocket1AfterBattleText"] = "Va-t'en ou\nj'appelle du\11renfort!",
  ["_SilphCo8FRocket1BattleText"] = "Hop hop hop !\nOn bouge plus!",
  ["_SilphCo8FRocket1EndBattleText"] = "Je suis\nfaible!",
  ["_SilphCo8FRocket2AfterBattleText"] = "Mes freres te\ndegommeront!",
  ["_SilphCo8FRocket2BattleText"] = "Je suis l'un des\n4 freres ROCKET!",
  ["_SilphCo8FRocket2EndBattleText"] = "Whoo!\nFreeeeres!",
  ["_SilphCo8FScientistAfterBattleText"] = "La SYLPHE est un\nvrai labyrinthe,\11hein?",
  ["_SilphCo8FScientistBattleText"] = "Tu nous casses\nles pieds!",
  ["_SilphCo8FScientistEndBattleText"] = "Heu?\nJ'ai perdu?",
  ["_SilphCo8FSilphWorkerMSilphIsFinishedText"] = "SILPH est finie...\nTEAM ROCKET a\11tout pris...",
  ["_SilphCo8FSilphWorkerMThanksForSavingUsText"] = "Merci de nous\navoir sauves!",
  ["_SilphCo9FRocket1AfterBattleText"] = "Si j'avais\ncommence a ton\11age...",
  ["_SilphCo9FRocket1BattleText"] = "Tes POKEMON ont\nl'air de t'aimer!",
  ["_SilphCo9FRocket1EndBattleText"] = "Ghaaah!",
  ["_SilphCo9FRocket2AfterBattleText"] = "Mes freres me\nvengeront!",
  ["_SilphCo9FRocket2BattleText"] = "Je suis l'un des\n4 freres ROCKET!",
  ["_SilphCo9FRocket2EndBattleText"] = "Freres!\nJ'suis nul!",
  ["_SilphCo9FScientistAfterBattleText"] = "Jouer sur les\npoints faibles\11est la cle! Pense\11aux elements!",
