  ["_SilphCo9FScientistEndBattleText"] = "Non!\nJ'ai perdu!",
  ["_SkyAttackGlowingText"] = "\nbrille!",
  ["_SlowbroDexEntry"] = "Le KOKIYAS\naccroche a la\nqueue du RAMOLOSS\12se nourrit des\nrestes de son\nhote.<DEXEND>",
