  ["_TM24ExplanationText"] = "\12CT24 : TONNERRE!\12Enseigne-la a un\nPOKEMON de la\11foudre!",
  ["_TM34ExplanationText"] = "\12Une CT (Capsule\nTech.) contient\11une attaque a\11enseigner a un\11POKEMON!\12Une CT marche\nqu'une fois!\11Faque choisis\11bien le POKEMON\11a qui la donner!\12CT34 contient\nPATIENCE!\12Ton POKEMON\nabsorbera les\11degats pour\11ensuite infliger\11le double!",
  ["_TM46ExplanationText"] = "\12CT46 : VAGUE PSY!\nUne onde\11d'energie psy\11devastatrice!",
  ["_TangelaDexEntry"] = "Son corps est\nrecouvert de\nlianes similaires\12a des algues.\nElles bougent\nquand il marche.<DEXEND>",
  ["_TaurosDexEntry"] = "Une fois sa cible\nen vue, il la\ncharge\12furieusement en\nfouettant l'air\nde sa queue.<DEXEND>",
