  ["_UndergroundPathRoute7CopyUnusedGirlText"] = "Je veux aller au\ncentre commercial\11de LAVAL...\12Mais, c'est plein\nde vilains voyous\11la-bas.",
  ["_UndergroundPathRoute7CopyUnusedGoesUnderSaffronText"] = "Le SOUTERRAIN\npasse sous\11MONTREAL et\11debouche sur\11VAL-JALBERT.\12Pour aller a\nBAIE-COMEAU, va dans\11la cabane de\11l'autre cote\11de la rue.",
  ["_UndergroundPathRoute7CopyUnusedMiddleAgedManText"] = "Tu veux-tu acheter\nplein de trucs?\12Sors d'icitte et va\nvers l'ouest!",
  ["_UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText"] = "La TEAM ROCKET\npossede un abri\11secret dans\11LAVAL!",
  ["_UndergroundPathRoute7MiddleAgedManText"] = "Y'a un POKEMON\nendormi pres de\11LAVAL.",
  ["_UndergroundPathRoute8GirlText"] = "Le centre\ncommercial de\11LAVAL est\11gigantesque!",
  ["_UnleashedEnergyText"] = "{USER}\nenvoie la sauce!",
  ["_UnusedBenchGuyText1"] = "Moi aussi j'veux\ncapturer un\11POKEMON.",
  ["_UnusedBenchGuyText2"] = "La fatigue...\11Doucement...\11Me gagne...",
  ["_UnusedBenchGuyText3"] = "Le patron de la\nSYLPHE se cache\11dans le PARC\11SAFARI.",
  ["_UnveiledGhostText"] = "Le SCOPE SYLPHE\nrevele l'identite\11du SPECTRE!",
  ["_UseNextMonText"] = "Appeler un autre\nPOKEMON?",
  ["_UsedCutText"] = "{RAM:wNameBuffer} a tout\ncoupe! Trop fort!",
  ["_UsedInsteadText"] = "a la place:\11",
  ["_UsedMove1Text"] = "\nlance ",
  ["_UsedMove2Text"] = "\nlance ",
  ["_UsedStrengthText"] = "{RAM:wNameBuffer}\nutilise FORCE.",
  ["_VaporeonDexEntry"] = "Il vit au bord de\nl'eau. Sa\nqueue lui donne\12l'apparence d'une\nsirene.<DEXEND>",
  ["_VendingMachineText1"] = "Un distributeur!\nQue choisir?",
  ["_VendingMachineText4"] = "Oups! Pas assez\nd'cash!",
  ["_VendingMachineText5"] = "Et hop!\n{RAM:wStringBuffer}!",
  ["_VendingMachineText6"] = "L'inventaire est\nplein!",
  ["_VendingMachineText7"] = "Pas soif!",
  ["_VenomothDexEntry"] = "Les motifs ocre\nde ses ailes\nchangent en\12fonction de son\ntype de poison.<DEXEND>",
  ["_VenonatDexEntry"] = "Il vit a l'ombre\ndes grands arbres\nou il mange des\12insectes. Il\nest attire par la\nlumiere.<DEXEND>",
  ["_VenusaurDexEntry"] = "Sa plante murit\nen absorbant les\nrayons du soleil.\12Il migre souvent\nvers les endroits\nensoleilles.<DEXEND>",
  ["_VermilionCityBeautyText"] = "La pollution,\nc'est mal!\12On dit que TADMORV\nse multiplie!",
  ["_VermilionCityGambler1DidYouSeeText"] = "As-tu vu\nLE TRANS-SAINT-LAURENT au port?",
  ["_VermilionCityGambler1SSAnneDepartedText"] = "LE TRANS-SAINT-LAURENT a\nleve l'ancre!\12Il reviendra l'an\nprochain.",
  ["_VermilionCityGambler2Text"] = "Je construis un\nimmeuble sur ce\11terrain.\12Mes POKEMON\ndament le sol.",
  ["_VermilionCityGymSignText"] = "RIMOUSKI\nARENE POKEMON\11CHAMPION:\11SERGENT BOUCHARD\12Le Ricain\nSurvolte!",
  ["_VermilionCityHarborSignText"] = "PORT DE RIMOUSKI",
  ["_VermilionCityMachopStompingTheLandFlatText"] = "\12Un MACHOC\npilonne le sol.",
  ["_VermilionCityMachopText"] = "MACHOC: Maaaaa!\nMachoooo!",
  ["_VermilionCityNoticeSignText"] = "AVIS!\12La ROUTE 12 peut\netre bloquee par\11un POKEMON\11endormi.\12Prendre la GROTTE\npour rejoindre\11VAL-JALBERT.\12POLICE DE\nRIMOUSKI",
  ["_VermilionCityPokemonFanClubSignText"] = "FAN CLUB POKEMON\nTous les dingues\11de POKEMON sont\11bienvenus!",
  ["_VermilionCitySailor1DoYouHaveATicketText"] = "Bienvenue a bord\nde LE TRANS-SAINT-LAURENT!\12Puis-je voir\nvotre passe?",
  ["_VermilionCitySailor1FlashedTicketText"] = "{PLAYER} montre\nle passe et crane\11a mort!\12Heu...merci!\nBienvenue a bord!",
  ["_VermilionCitySailor1ShipSetSailText"] = "LE TRANS-SAINT-LAURENT a\nleve l'ancre.",
  ["_VermilionCitySailor1WelcomeToSSAnneText"] = "Bienvenue a bord\nde LE TRANS-SAINT-LAURENT!",
  ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER} a pas\nde passe!\12Desole!\12Ca te prend un\npasse pour monter\11a bord.",
  ["_VermilionCitySailor2Text"] = "LE TRANS-SAINT-LAURENT est\nun paquebot de\11luxe.\12Nous nous rendons\na RIMOUSKI\11une fois par an.",
  ["_VermilionCitySignText"] = "RIMOUSKI\nLe port aux\11crepuscules\11flamboyants",
  ["_VermilionGymGentlemanAfterBattleText"] = "Les portes ne\ns'ouvrent pas?\12Le SERGENT BOUCHARD\nest prudent!",
  ["_VermilionGymGentlemanBattleText"] = "Dans l'armee, le\nSERGENT BOUCHARD etait\11mon instructeur\11de combat!",
  ["_VermilionGymGentlemanEndBattleText"] = "Stop!\nTu es fort!",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "Wouh! Ce match\netait survolte!",
  ["_VermilionGymGymGuideChampInMakingText"] = "Salut! Champion\nen herbe!\12Le SERGENT BOUCHARD a\nun surnom. On\11l'appelle...\11Le Ricain\11Survolte!\12Il est expert\nen POKEMON\11electriques!\12C'est pas bon\npour les POKEMON\11volants et\11aquatiques! Fais\11aussi gaffe aux\11eclairs pouvant\11paralyser!\12Le SERGENT BOUCHARD\nest ben prudent!\12Il te faudra\nresoudre une\11enigme pour\11arriver jusqu'a\11lui!",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "Un p'tit conseil,\ngamin!\12L'electricite est\nben puissante!\12Mais elle est\ninutile face a\11des POKEMON de\11la terre!",
  ["_VermilionGymLTSurgePreBattleText"] = "He, le jeune!\nTu fais quoi la?\12Tu resisterais\npas longtemps\11en temps de\11guerre!\12Je vas te dire,\nmes POKEMON\11electriques m'ont\11sauve la vie!\11Et ouais!\12Ils ont paralyse\nmes ennemis avec\11leurs eclairs!\11Une vraie\11boucherie!\12Y va t'arriver la\nmeme chose!\11Compte tes dents!\11Tu vas morfler!",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER} recoit:\n{RAM:wStringBuffer}!",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "Whoo!\12Ayoye! T'es\nun dur, mon p'tit\11gars!\12Ben correct, prends\nle BADGEFOUDRE!",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "Revue d'paquetage\np'tit gars, ton\11inventaire est\11plein!",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "Le BADGEFOUDRE\naugmente la\11VITESSE de tes\11POKEMON!\12Il permet aussi\na tes POKEMON\11de VOLER!\12Tu es un bon, mon\np'tit gars!\11Prends ca!",
  ["_VermilionGymSailorAfterBattleText"] = "Y'a une double\nsecurite! Voici\11un indice!\12Appuie sur un\nbouton et le 2eme\11est a cote!",
  ["_VermilionGymSailorBattleText"] = "C'est pas un\nendroit pour les\11gamins, icitte!",
  ["_VermilionGymSailorEndBattleText"] = "Argh!\nTu m'as eu par\11surprise!",
  ["_VermilionGymSuperNerdAfterBattleText"] = "OK, je parle!\12Le SERGENT BOUCHARD a\ncache des boutons\11pour ouvrir les\11portes...\11...Quequ'part!",
  ["_VermilionGymSuperNerdBattleText"] = "J'suis un poids\nplume, mais je\11suis bon avec\11l'electricite!",
  ["_VermilionGymSuperNerdEndBattleText"] = "Argh!\nJ'suis cuit!",
  ["_VermilionGymTrashFailText"] = "Une poubelle bien\ndegueulasse!\11Oups... Les\11verrouillages\11sont en place!",
  ["_VermilionGymTrashSuccessText1"] = "Oh! Un bouton\ndans la poubelle!\11Dingue!\12Le premier\nverrouillage est\11leve!",
  ["_VermilionGymTrashSuccessText2"] = "He! Un autre\nbouton dans la\11poubelle! Delire!\11On appuie!",
  ["_VermilionGymTrashSuccessText3"] = "Le deuxieme\nverrouillage est\11leve!\12La porte s'ouvre!",
  ["_VermilionGymTrashText"] = "Mmmm!\nUn joli tas\11d'ordures...miam!",
  ["_VermilionMartCooltrainerFText"] = "Les POKEMON\npeuvent etre\11gentils ou\11mechants, cela\11depend de leur\11maitre.",
  ["_VermilionMartCooltrainerMText"] = "Il y en a, des\nben mechants,\11qui utilisent les\11POKEMON pour\11voler les autres\11dresseurs.\12La TEAM ROCKET\nfait du trafic de\11POKEMON rares.\12Ils abandonnent\nsur le bord de la\11route les POKEMON\11trop faibles!\11Ouais, y sont\11de meme chez les\11ROCKET.",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "Je suis le...\nMAITRE PECHEUR!\12La peche...moi...\nJ'adore ca!\12Et toi, p'tite\ntete?",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "\12Pecher, c'est la\nvie! Et la vie,\11c'est la peche!\12Du ruisseau\njusqu'aux oceans,\11peche, peche et\11peche encore!",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "B'jour a toi,\n{PLAYER}!\12Ca mord?\nHein? Hein?",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "Oh non!\12T'as plus d'place\npour mon cadeau!",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "Terrib'! Toi,\nj't'aime bien!\12Prends ca et...\nPeche! Peche!\12{PLAYER} recoit\n{RAM:wStringBuffer}!",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "Oh...ben...\nC'est dommage...",
  ["_VermilionPidgeyHouseLetterText"] = "Cher JULIO,\nj'espere te voir\11ben bientot.\12On raconte que\nMONTREAL a des\11problemes avec la\11TEAM ROCKET.\12RIMOUSKI\nest paisible.",
  ["_VermilionPidgeyHousePidgeyText"] = "ROUCOOL: Rourou!",
  ["_VermilionPidgeyHouseYoungsterText"] = "Mon ROUCOOL va\napporter une\11lettre jusqu'a\11MONTREAL au Nord!",
  ["_VermilionPokecenterFishingGuruText"] = "Deux POKEMON d'un\nmeme niveau sont\11differents.\12Un POKEMON eleve\npar un dresseur\11est toujours plus\11fort qu'un\11POKEMON sauvage.\11Ouais mon gars!",
  ["_VermilionPokecenterGuyText"] = "C'est vrai qu'un\nPOKEMON de haut\11niveau est ben\11puissant...\12Mais tout POKEMON\nest vulnerable\11face a un certain\11element.\12Y'a donc pas\nde POKEMON de\11la mort qui tue.",
  ["_VermilionPokecenterSailorText"] = "Mon POKEMON est\nempoisonne! Il\11est tombe dans\11les pommes\11pendant que je\11marchais!",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "Perdre ca craint!",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "Es-t'aussi fort\nque moa? ",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "Oh!\nVilain!",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "T'es fort, \non a compris!",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "Mmm...\nT'as l'air fort! \11Mais l'es-tu\11pour vrai?",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "OK.\nT'es fort.",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "Tu as le droit de\nparcourir la\11ROUTE VICTOIRE!",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "Allez, viens\nmanger ta claque!",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "Beuh!\nJ'me suis pris\11une claque!",
  ["_VictoryRoad2FHikerAfterBattleText"] = "Si t'es bloque,\nessaie de bouger\11les rochers!",
  ["_VictoryRoad2FHikerBattleText"] = "La ROUTE VICTOIRE\nest l'epreuve\11finale de tout\11dresseur!",
  ["_VictoryRoad2FHikerEndBattleText"] = "Ouargh!",
  ["_VictoryRoad2FMoltresBattleText"] = "Yahoo!",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "{RIVAL} est aussi\narrive icitte!",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "Faque de meme,\ntu cherches les\11claques?",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "Argh!\nT'as gagne!",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "En ce qui\nconcerne les\11POKEMON, j'suis\11le plus fort!\11... ... ...\11Du mooooonde!",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "Si tu peux\nremporter ces\11epreuves,\11tu parviendras\11jusqu'au CONSEIL\11des 4!",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "Ha!\nJ'y crois pas!",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "De nombreux\ndresseurs ont\11abandonne icitte!",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "La ROUTE de la\nVICTOIRE est une\11etape difficile?",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "Bon...\nJ'ai perdu, non?",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "Ben, j'suis pas\nsi forte que ca!",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "Je vas te\nmontrer ma\11puissance!",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "Non!\nJe suis furieuse!",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "Bats-toi bien,\net tu seras\11un bon dresseur!",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "Un dresseur est\ntoujours en quete\11d'adversaires plus\11puissants!",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "Oh!\nT'es un dur toi!",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "Tu as-tu battu\nGIOVANNI de la\11TEAM ROCKET?",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "J'ai entendu\nparler d'un jeune\11prodige!",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "...\nC'etait vrai!",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "Ces dresseurs\nsont de la\11LIGUE POKEMON!\11Fais attention!",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "Seuls les elus\npeuvent passer!",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "Oh!\nJ'y crois pas!",
  ["_VictreebelDexEntry"] = "Il vit en\ncolonie dans la\njungle mais\12personne en est\njamais revenu\nvivant.<DEXEND>",
  ["_VileplumeDexEntry"] = "Plus ses petales\nsont grands,\nplus ils\12contiennent de\npollen toxique.<DEXEND>",
  ["_ViridianBlackboardBurnText"] = "La BRULURE reduit\nla puissance et\11la vitesse. Elle\11inflige aussi des\11degats continus.\12La brulure ne\ndisparait pas\11apres un combat.\12L'ANTI-BRULE\nsoigne les grands\11brules!",
  ["_ViridianBlackboardFrozenText"] = "Un POKEMON\nprisonnier des\11glaces reste\11immobile!\12Il reste gele\nmeme apres la\11fin du combat.\12Un ANTIGEL peut\nrechauffer un\11POKEMON!",
  ["_ViridianBlackboardPoisonText"] = "Un POKEMON\nempoisonne voit\11son energie se\11vider doucement.\12Le poison ne\ndisparait pas\11apres un combat.\12L'ANTIDOTE soigne\nle poison!",
  ["_ViridianBlackboardPrlzText"] = "La paralysie peut\nannuler certaines\11attaques!\12La paralysie ne\ndisparait pas\11apres un combat.\12L'ANTI-PARA\nsoigne toute\11paralysie!",
  ["_ViridianBlackboardSleepText"] = "Un POKEMON ne\npeut attaquer\11s'il est endormi!\12Un POKEMON reste\nendormi meme\11apres un combat.\12Un REVEIL peut\nle reveiller!",
  ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER} recoit:\nCT42!",
  ["_ViridianCityFisherTM42ExplanationText"] = "CT42 contient\nDEVOREVE...\11...(pionce)...",
  ["_ViridianCityFisherTM42NoRoomText"] = "Tu es trop\ncharge.",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "Cette ARENE\nPOKEMON est\11toujours fermee.\12Mais qui en est\nle CHAMPION?",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "Le CHAMPION de\nl'ARENE de\11MONT-TREMBLANT est de\11retour! Dingue!",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "Papinou! Tu vas-tu\nt'lever, ouais?\11T'as vide la cave\11ou quoi?",
  ["_ViridianCityGirlWhenIGoShopText"] = "Je passe par la\nFORET TREMBLANT\11pour faire mes\11courses a\11THETFORD MINES.",
  ["_ViridianCityGymLockedText"] = "Les portes de\nl'ARENE sont\11fermees...",
  ["_ViridianCityGymSignText"] = "ARENE POKEMON\nde MONT-TREMBLANT",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "Ahh... Un p'tit\nsomme, un bon\11cafe et hop! La\11peche pour la\11journee!\12Mais bien sur que\ntu peux passer!\12Mais au fait...\nT'es presse?",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Je vois que t'as\nun POKEDEX.\12Capture un\nPOKEMON et il\11sera mis a jour\11automatiquement.\12Qu...QUOI?\nTu sais pas\11comment attraper\11un POKEMON?\12J'vais t'montrer.",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "Passage...\nINTERDIT!\12Propriete privee!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "Le temps, c'est\nd'l'cash. Va.",
  ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "D'abord, il faut\naffaiblir le\11POKEMON desire.",
  ["_ViridianCityPokecenterGuyText"] = "Les CENTRES\nPOKEMON soignent\11tous les POKEMON\11blesses ou K.O.!",
  ["_ViridianCitySignText"] = "MONT-TREMBLANT\nVerte comme\11l'esperance",
  ["_ViridianCityTrainerTips1Text"] = "ASTUCE\12Capture des\nPOKEMON et\11agrandis ta\11collection!\12Plus t'en\ncaptures, plus\11les combats sont\11faciles!",
  ["_ViridianCityTrainerTips2Text"] = "ASTUCE\12Les attaques sont\nlimitees par des\11PP (Points de\11Pouvoir).\12Pour disposer de\ntous tes PP,\11fais soigner\11tes POKEMON dans\11un CENTRE\11POKEMON!",
  ["_ViridianCityYoungster1Text"] = "Des POKE BALL!\nMais... T'as des\11POKEMON!\12C'est cool de\npouvoir s'en\11servir quand on\11veut, hein?",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "Tu veux-tu tout\nsavoir sur les 2\11types de chenille\11POKEMON?",
  ["_ViridianForestLeavingSignText"] = "VOUS QUITTEZ LA\nFORET TREMBLANT.\11VOUS ALLEZ VERS\11THETFORD MINES.",
  ["_ViridianForestNorthGateGrampsText"] = "As-tu remarque\nles buissons sur\11la route?\12Une technique\nsecrete de\11POKEMON peut les\11couper.",
  ["_ViridianForestNorthGateSuperNerdText"] = "De nombreux\nPOKEMON vivent\11uniquement dans\11les forets ou les\11cavernes.\12Cherche bien\npartout pour tous\11les avoir!",
  ["_ViridianForestSouthGateGirlText"] = "Vas-tu dans la\nFORET TREMBLANT,\11mon poussin? Fais\11bien attention,\11c'est un vrai\11labyrinthe!",
  ["_ViridianForestSouthGateLittleGirlText"] = "RATTATA est\npetit mais il est\11vicieux! En as-tu\11capture un?",
  ["_ViridianForestTrainerTips1Text"] = "ASTUCE\12Pour eviter les\ncombats, \11marchez pas dans\11les hautes herbes!",
  ["_ViridianForestTrainerTips2Text"] = "ASTUCE\12Pour evaluer\nvotre POKEDEX,\11appelez le Prof.\11Chen via un PC!",
  ["_ViridianForestTrainerTips3Text"] = "ASTUCE\12Interdiction de\ncapturer les\11POKEMON d'un\11autre dresseur!\11La capture se\11fait a l'etat\11sauvage!",
  ["_ViridianForestTrainerTips4Text"] = "ASTUCE\12Un POKEMON\nblesse se capture\11plus facilement!\12En pleine forme,\nil peut s'enfuir!",
  ["_ViridianForestUseAntidoteSignText"] = "L'ANTIDOTE vendu\ndans les\11BOUTIQUES PKMN\11guerit du poison.",
  ["_ViridianForestYoungster1Text"] = "Je suis icitte\navec des amis!\12Ils sont icitte\npour se battre!",
  ["_ViridianForestYoungster2AfterBattleText"] = "Chut! Tu fais\npeur aux\11insectes...",
  ["_ViridianForestYoungster2BattleText"] = "Regarde ben ca,\nles insectes\11c'est mon dada!",
  ["_ViridianForestYoungster2EndBattleText"] = "NON!\nCHENIPAN y\11arrivera pas!",
  ["_ViridianForestYoungster3AfterBattleText"] = "Fichtre! J'vais\nen choper des\11plus balezes!",
  ["_ViridianForestYoungster3BattleText"] = "Haha! Un dresseur\nde POKEMON, un\11vrai, se\11debine jamais!!!",
  ["_ViridianForestYoungster3EndBattleText"] = "Oups!\nEn a plus des\11POKEMON, moi!",
  ["_ViridianForestYoungster4AfterBattleText"] = "Tu trouveras\npeut-etre ben des\11objets par terre!\12Je cherche les\nobjets que j'ai\11laisse tomber...",
  ["_ViridianForestYoungster4BattleText"] = "Hop, hop! Minute!\nOn est pas\11presse!",
  ["_ViridianForestYoungster4EndBattleText"] = "Houla!\nJ'abandonne!\11T'es trop fort!",
  ["_ViridianForestYoungster5Text"] = "J'suis a court de\nPOKE BALL!\11Je peux plus\11attraper de\11POKEMON!\12Il t'en faut\ntoujours un max!",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "Il faut que tu\nsois fort pour te\11mesurer au...\11CHAMPION!",
  ["_ViridianGymCooltrainerM1BattleText"] = "He! Tu dois-tu etre\ncreve, non? ",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "Ha!\nJ'suis essouffle!",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "Le CHAMPION va\nme taper dessus!",
  ["_ViridianGymCooltrainerM2BattleText"] = "Je vas t'ecraser\navec style et\11elegance!",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "...\nTout perdu!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "Tu pourras\nacceder a la\11LIGUE POKEMON\11seulement en\11battant notre\11CHAMPION!",
  ["_ViridianGymCooltrainerM3BattleText"] = "L'ARENE de\nMONT-TREMBLANT etait\11fermee depuis\11longtemps, mais\11le CHAMPION est\11enfin revenu!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "!!!\nDefaite!",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "Grace au BADGE\nTERRE tous les\11POKEMON obeiront\11a tes ordres!\12Il est le\ntemoignage de ta\11grande maitrise\11des POKEMON!\12Tu pourras ainsi\nacceder a la\11LIGUE POKEMON!\12C'est un cadeau\nque je te fais.\11Va asteur,\11et deviens le\11plus grand des\11dresseurs!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "OK, j'ai perdu!\nJe suis pas\11digne d'etre le\11chef de la TEAM\11ROCKET! Ainsi,\11son existence\11s'acheve avec ma\11defaite!\12Je vas me\nretirer, loin, en\11ermite, pour\11etudier les\11POKEMON!\12Un jour, nos\nchemins se\11croiseront a\11nouveau! Adieu!",
  ["_ViridianGymGiovanniPreBattleText"] = "Fwahaha! Te voici\ndans mon repaire!\12Je voulais\nreformer la TEAM\11ROCKET icitte!\12Mais t'as encore\ntout fait rater!\11Je suis furieux\11et ca sent pas\11bon pour toi!\12Une fois de plus\nt'oses me\11defier, moi, le\11grand GIOVANNI!\11Mais aujourd'hui,\11tu vas deguster!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "Ah!\nVoila ce que\11j'appelle du\11combat! Tu as\11gagne! En\11recompense voici\11le BADGE TERRE!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER} recoit\nCT27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "\12CT27: ABIME!\nCette attaque\11peut mettre hors\11combat un POKEMON\11en un seul coup!\12Je l'ai inventee\ny'a bien\11longtemps...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "Ton inventaire\nest plein!",
  ["_ViridianGymGuidePostBattleText"] = "Quoi?! C'etait\nGIOVANNI le\11CHAMPION?\11Ben ca faque!",
  ["_ViridianGymGuidePreBattleText"] = "Salut! Champion\nen herbe!\12Meme moi, je ne\nsais pas qui est\11le CHAMPION de\11MONT-TREMBLANT!\12Le combat qui\nt'attend sera le\11plus dur de tous!\12Le dresseur de\ncette ARENE aime\11les POKEMON du\11type SOL!",
  ["_ViridianGymHiker1AfterBattleText"] = "Grouargh!",
  ["_ViridianGymHiker1BattleText"] = "Groaar!\nColere! Viens\11te battre!",
  ["_ViridianGymHiker1EndBattleText"] = "Rargh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Mes POKEMON sont\ndes karatekas...",
  ["_ViridianGymHiker2BattleText"] = "Le Karate est\nl'art martial\11ultime!",
  ["_ViridianGymHiker2EndBattleText"] = "Yaha!",
  ["_ViridianGymHiker3AfterBattleText"] = "La LIGUE POKEMON?\nToi? Hahahahah!!!\11T'es un rigolo!",
  ["_ViridianGymHiker3BattleText"] = "J'suis le ROI du\nKARATE! Ton\11destin repose\11entre mes mains!",
  ["_ViridianGymHiker3EndBattleText"] = "Yaah!",
  ["_ViridianGymRocker1AfterBattleText"] = "Sais-tu qui est\nnotre CHAMPION?",
  ["_ViridianGymRocker1BattleText"] = "Avec mes POKEMON\nje fais de la\11jolie musique!",
  ["_ViridianGymRocker1EndBattleText"] = "Tu es\nben fort!",
  ["_ViridianGymRocker2AfterBattleText"] = "Attends! Je ne\nfaisais pas\11attention!",
  ["_ViridianGymRocker2BattleText"] = "Tes POKEMON vont\nse courber sous\11mes coups de\11fouet!",
  ["_ViridianGymRocker2EndBattleText"] = "Aiee!",
  ["_ViridianMartClerkParcelQuestText"] = "Tu connais le\nPROF. TREMBLAY?\12Sa commande vient\nd'arriver.\11Peux-tu la lui\11apporter?\12{PLAYER} obtient\nle COLIS DE TREMBLAY!",
