  ["_ViridianSchoolNotebookText1"] = "Tu examines le\njournal!\12Premiere page...\12Les POKE BALL\npeuvent capturer\11les POKEMON.\12Jusqu'a 6\nPOKEMON sont\11transportables.\12Les personnes\ns'occupant des\11POKEMON sont\11des dresseurs de\11POKEMON.",
  ["_ViridianSchoolNotebookText2"] = "Deuxieme page...\12Un POKEMON\nsauvage et en\11pleine forme est\11difficile a\11capturer, faque\11affaiblissez-le!\12Le poison, la\nbrulure et les\11autres types de\11degats sont aussi\11efficaces!",
  ["_ViridianSchoolNotebookText3"] = "Troisieme page...\12Le but de chaque\ndresseur est\11d'affronter les\11autres dresseurs\11dans des combats\11de POKEMON.\12Les combats se\ntiennent en\11permanence dans\11les ARENES\11POKEMON.",
  ["_ViridianSchoolNotebookText4"] = "Quatrieme page...\12Le reve de chaque\ndresseur est de\11vaincre les 8\11CHAMPIONS des\11differentes\11ARENES POKEMON.\12Ces victoires\ndonnent le droit\11d'affronter...\12Le CONSEIL des 4\nde la LIGUE\11POKEMON!",
  ["_ViridianSchoolNotebookText5"] = "FILLE: He! Lis\npas mon journal!",
