  ["_OaksLabRivalTakesText3"] = "TREMBLAY: {RIVAL}!\nQue fais-tu?",
  ["_OaksLabRivalTakesText4"] = "{RIVAL}: Pepe,\nje veux celui-la!",
  ["_OaksLabRivalTakesText5"] = "TREMBLAY: Mais...\nEnfin mais...\11Bah, c'est que...\11OK.\12J'allais t'en\ndonner un tot ou\11tard...\12{PLAYER},\nviens par la.",
  ["_OaksLabThatsAPokeball"] = "C'est une POKE\nBALL. Y'a un\11POKEMON a\11l'interieur!",
  ["_OfficerJennyText1"] = "Je viens juste de\ncapturer un\11CARAPUCE qui fait\11n'importe quoi!\12Je vas avoir\nbesoin d'un bon\11DRESSEUR pour le\11remettre dans le\11droit chemin.",
  ["_OfficerJennyText2"] = "Tu as le BADGE\nFOUDRE!?\12Tu dois etre un\ndresseur baleze!\12Je viens juste\nd'attraper un\11CARAPUCE qui fait\11n'importe quoi!\12Veux-tu t'en\noccuper? Moi, je\11y arrive pas.",
  ["_OfficerJennyText3"] = "Capote! Occupe-toi\nbien de CARAPUCE!",
  ["_OfficerJennyText4"] = "Ben... J'fais\nquoi asteur?",
  ["_OfficerJennyText5"] = "Comment va mon\nCARAPUCE?",
  ["_PalletTownOakComeWithMe"] = "PROF. TREMBLAY: Des\nPOKEMON sauvages\11peuvent surgir a\11tout instant!\12Tu as besoin d'un\nPOKEMON pour te\11proteger!\12Allez, suis-moi!\nViens par la!",
  ["_PalletTownOakThatWasCloseText"] = "PROF. TREMBLAY:\nDe justesse!\12Des POKEMON\nsauvages vivent\11dans les hautes\11herbes!",
  ["_PalletTownOakWhewText"] = "PROF. TREMBLAY: Pfou!",
  ["_PewterGymGuyText"] = "Allez! En\nchar Simone!\12Ca va etre dur\npour ton p'tit\11PIKACHU icitte!\12L'electricite est\nsans effet sur\11les POKEMON du\11sol.",
  ["_PewterPokecenterText3"] = "Les CENTRES\nPOKEMON sont\11formidables!\12Ils soignent les\nPOKEMON totale-\11ment!\12Ils annulent meme\nle sommeil, le\11gel, le poison\11et tout ca!",
  ["_PikachuUnhappyText"] = "{RAM:wNameBuffer} est\npas content!",
  ["_PokemonFanClubClefairyFanBetterText"] = "Hmm! Mon MELOFEE\nest deux fois\11plus mignon que\11ce truc!",
  ["_PokemonFanClubClefairyFanNormalText"] = "Mon MELOFEE est\nle plus beau de\11tous les MELOFEE!",
  ["_PokemonFanClubClefairyFanText"] = "Notre maitre est\nben bavard en ce\11qui concerne les\11POKEMON.",
  ["_PokemonFanClubClefairyText"] = "MELOFEE: Meloooo!",
  ["_PokemonFanClubSeelFanText"] = "Je vas connecter\nun cable pour\11IMPRIMER une\11photo de OTARIA!",
  ["_PokemonText"] = "POKEMON!",
  ["_PokemonTowerJessieJamesText1"] = "Pas bouger!",
  ["_PokemonTowerJessieJamesText2"] = "Le vieux s'est\nplaint faque on\11l'a enferme!\12Faque toi, fais\ncou-couche panier\11ou bobo la tete!",
  ["_PokemonTowerJessieJamesText3"] = "...\nTu vas voir!",
  ["_PokemonTowerJessieJamesText4"] = "TEAM ROCKET...\nA la vitesse d'un\11gros bike...",
  ["_RefusingText"] = "{RAM:wNameBuffer}\nrefuse!",
  ["_RocketHideoutB4FRocketAfterBattleText"] = "Mince! J'ai\nperdu la \11CLE ASC.!",
  ["_RocketHideoutB4FRocketBattleText"] = "L'ascenseur ne\nmarche pas? Il\11faut la CLE ASC.!",
  ["_RocketHideoutB4FRocketEndBattleText"] = "Argh!",
  ["_RocketHideoutJessieJamesText1"] = "Pas bouger,\nmorveux!",
  ["_RocketHideoutJessieJamesText2"] = "Comment as-t'ose\nnous humilier au\11MONT SELENITE?\12Cette fois tu vas\nprendre cher!",
  ["_RocketHideoutJessieJamesText3"] = "...\nT'es terrible!",
  ["_RocketHideoutJessieJamesText4"] = "La TEAM ROCKET...\nA la vitesse du\11son...",
  ["_Route24DamianText1"] = "Je sais pas\nentrainer mes\11POKEMON.\12Je devrais peut-\netre relacher mon\11SALAMECHE...\12Si tu promets de\nt'en occuper, il\11est a toi.",
  ["_Route24DamianText2"] = "Occupe-toi bien\nde mon SALAMECHE!",
  ["_Route24DamianText3"] = "Oh... Je vas le\nrelacher faque...",
  ["_Route24DamianText4"] = "Comment va mon\nSALAMECHE?",
  ["_Route6CooltrainerF1AfterBattleText"] = "Il faut aimer les\nPOKEMON. C'est la\11seule solution!",
  ["_Route6CooltrainerM1AfterBattleText"] = "L'amour...\nC'est cruel!",
  ["_Route9AJAfterBattleText"] = "Je vas entrainer\nmon SABELETTE!",
  ["_Route9AJBattleText"] = "Je serai le plus\ngrand dresseur du\11moooooonde!",
  ["_Route9AJEndBattleText"] = "???\nMon SABELETTE a\11perdu?",
  ["_RunAwayText"] = "Vite! Fuyons!",
  ["_SafariZoneLowCostText1"] = "\12Bon, allez...\nDonne-moi ce que\11tu peux.",
  ["_SafariZoneLowCostText2"] = "Par contre, ne\ncompte pas trop\11sur les 30 BALLs!",
  ["_SafariZoneLowCostText3"] = "\12T'es du genre\npersistant!\12OK, cette fois\nje te laisse\11passer, mais\11juste cette fois!",
  ["_SafariZoneLowCostText4"] = "",
  ["_SafariZoneLowCostText5"] = "Desole, pour\nentrer, faut\11payer.",
  ["_SafariZoneLowCostText6"] = "Pas d'entree sans\nallonger l'ble!",
  ["_SafariZoneLowCostText7"] = "J'ai dit...\nPas sans pognon!",
  ["_SafariZoneLowCostText8"] = "Bon, j'peux\nt'tutoyer?\11TU DE-GA-GES!",
  ["_SavingText"] = "Sauvegarde...",
  ["_SilphCoJessieJamesText1"] = "Une minute,\navorton!",
  ["_SilphCoJessieJamesText2"] = "Notre BOSS est en\nreunion!\12Tu dois pas le\nderanger!!!",
  ["_SilphCoJessieJamesText3"] = "...\nCa craint...",
  ["_SilphCoJessieJamesText4"] = "TEAM ROCKET...\nA la vitesse\11d'une char!\12En gros...",
  ["_SleepingPikachuText1"] = "Pas de reponse...",
  ["_SleepingPikachuText2"] = "Pas de reponse...",
  ["_SummerBeachHousePikachuText"] = "PIKACHU: Pikaa",
  ["_SummerBeachHousePoster1Text1"] = "Le DAVE est le\nBoss des surfers!\12Quand j'suis dans\nle tube, c'est du\11total adrenaline!",
  ["_SummerBeachHousePoster1Text2"] = "DAVE le SURFER\n30 ans de vagues!",
  ["_SummerBeachHousePoster2Text1"] = "SURF-ASTUCE 1!\12Apres un flip,\naligner le surf\11avec la vague!",
  ["_SummerBeachHousePoster2Text2"] = "BUNGALOW D'ETE\nBienvenue aux\11POKEMON!",
  ["_SummerBeachHousePoster3Text1"] = "SURF-ASTUCE 2!\12Les flips pendant\nun saut c'est\11d'la balle!",
  ["_SummerBeachHousePoster3Text2"] = "Le surf, la mer:\nc'est la vie!",
  ["_SummerBeachHousePrinterText1"] = "On dirait une\nmachine...",
  ["_SummerBeachHousePrinterText2"] = "PRINTER du\nBUNGALOW D'ETE!",
  ["_SummerBeachHousePrinterText3"] = "Le meilleur score\nest affiche.\12On l'imprime?",
  ["_SummerBeachHousePrinterText4"] = "Le meilleur score\nest affiche.\12On l'imprime?",
  ["_SummerBeachHousePrinterText5"] = "Impression: OK!",
  ["_SummerBeachHousePrinterText6"] = "ERREUR IMPRESSION",
  ["_SummerBeachHouseSurfinDudeText1"] = "Woah!\12Ton PIKACHU aussi\nsait surfer!\12Cool! Tu as donc\nle droit de\11surfer avec le\11DAVE!\12Ca te tente?",
  ["_SummerBeachHouseSurfinDudeText2"] = "Viens surfer\nquand tu veux!",
  ["_SummerBeachHouseSurfinDudeText3"] = "Tu veux-tu surfer?",
  ["_SummerBeachHouseSurfinDudeText4"] = "Hot Dogs et\nBurgers a gogo!",
  ["_VermilionDockUnusedText"] = "",
  ["_ViridianCityOldManLosingMyTouchText"] = "J'ai rate!\nJ'me fais vieux,\11ben vieux!\12Et j'ai plus\nde POKE BALLS!\12Je vas en ache-\nter a la BOUTIQUE\11POKEMON!",
  ["_ViridianCityOldManNotGoodEnoughForYouText"] = "Oh... Je suis\npas assez bon\11pour toi!",
  ["_ViridianCityOldManWantMeToShowYouAgainText"] = "Hmm? Tu veux-tu que\nje te montre\11comment capturer\11un POKEMON?",
  ["_ViridianCityOldManWatchCloselyText"] = "Ok! Ouvre grand\ntes p'tits yeux!",
  ["_ViridianForestCooltrainerFAfterBattleText"] = "J'ai cherche\npendant des\11heures sans\11jamais trouver de\11PIKACHU!",
  ["_ViridianForestCooltrainerFBattleText"] = "Salut! Tu as-tu un\nPIKACHU?",
  ["_ViridianForestCooltrainerFEndBattleText"] = "Non?\nPour vrai?",
  ["_ViridianForestYoungster5AfterBattleText"] = "CHRYSACIER est\ntrop cool!\11Son attaque a lui\11c'est la defense!",
  ["_ViridianForestYoungster5BattleText"] = "Je suis terrible!\nTu peux me\11battre!",
  ["_ViridianForestYoungster5EndBattleText"] = "...\nTrop injuste...",
  ["_ViridianForestYoungster6Text"] = "J'suis a court de\nPOKE BALLs!\11Je peux plus\11attraper de\11POKEMON!\12Il t'en faut\ntoujours un max!",
  ["_ViridianSchoolHouseLittleGirlText"] = "Ma soeur eh ben\nelle dit qu'un\11POKEMON devient\11gentil eh ben si\11on est gentil\11aussi. Ouais.",
  ["MelanieText1"] = "Je m'occupe des\nPOKEMON malades.\12J'ai soigne ce\nBULBIZARRE.\12Il lui faut main-\ntenant un bon\11dresseur.",
  ["MelanieText2"] = "Au fait! Tu vou-\ndrais pas de ce\11joli BULBIZARRE?",
  ["MelanieText3"] = "Prends soin de\nBULBIZARRE!",
  ["MelanieText4"] = "BULBIZARRE se\nporte bien?",
  ["MelanieText5"] = "Oh...\nDommage...",
  ["MelanieBulbasaurText"] = "BULBIZARRE: BUL!\nBIZZZAAARRR!",
  ["MelanieOddishText"] = "MYSTHERBE: Miiis!",
  ["MelanieSandshrewText"] = "SABELETTE: Belet!",
  ["FanClubChairPrintText1"] = "Salut, {PLAYER}!\nAs-tu vu mes\11photos de\11POKEMON?\12Elles sont\naccrochees au\11mur.\12Ah! J'ai une\nidee!\12Veux-tu que je\nphotographie tes\11POKEMON?",
  ["FanClubChairPrintText2"] = "Non? Ben, c'est\nbien dommage.",
  ["FanClubChairPrintText3"] = "OK. J'ai fini.",
  ["FanClubChairPrintText4"] = "On va IMPRIMER ca\nplus tard.",
  ["SilphCo2FSilphWorkerFPleaseTakeThisText"] = "Au secours!\nA l'aide!\12Quoi? Tu es-tu pas\nde la TEAM?\11Tant mieux!\11Tiens prends ca!",
  ["SilphCo9FNurseYouLookTiredText"] = "Tu as l'air ben\nfatigue! Tu\11devrais faire une\11sieste!",
  ["SilphCo9FNurseDontGiveUpText"] = "Courage!",
  ["SilphCo9FNurseThankYouText"] = "Merci mille\nfois!",
  ["SSAnneKitchenCook7SalmonDuSaladText"] = "De la poutine\nben grasse!\12Pour ceux qui\nsont pas contents,\11c'est pareil\11pour tout le\11monde!",
  ["SSAnneKitchenCook7EelsAuBarbecueText"] = "De la tourtiere\ndu Lac-Saint-Jean!\12De quoi donner\ndes envies de\11mutinerie!",
  ["SSAnneKitchenCook7PrimeBeefSteakText"] = "Du pouding\nchomeur!\12Mais je crois\nque j'ai pu\11de sirop!",
  ["ViridianCityYoungster2OkThenText"] = "Bon. OK.",
  ["ViridianCityYoungster2CaterpieAndWeedleDescriptionText"] = "Contrairement a\nCHENIPAN, ASPICOT\11est venimeux.\12Attention a son\nDARD-VENIN!",
  ["ViridianCityFisherYouCanHaveThisText"] = "(Baiiiille)!\nJ'ai du dormir\11dehors.\12J'ai reve qu'un\nSOPORIFIK\11devorait mes\11reves... Heu?\11Qu'est-ce que\11cette CT fait la?\12C'est dingue ca!\nTiens... Elle est\11pour toi.",
  ["TMNotebookText"] = "C'est un rapport\nsur les CT.\12...\12Il existe en tout\n50 CT (Capsule\11Technique).\125 CS (Capsule\nSecrete) sont a\11utiliser a\11l'infini.\12SYLPHE INC.",
  ["TeachingHMsText"] = "Une fois qu'un\nPOKEMON a appris\11une CS, il ne\11pourra plus\11l'oublier.\12Il faut faque\nbien choisir le\11POKEMON en\11question.",
}
